--
-- Name: applications_fill_opening(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.applications_fill_opening() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  seat uuid;
begin
  if new.stage = 'hired' and (tg_op = 'INSERT' or old.stage <> 'hired') then
    if exists (select 1 from openings o where o.filled_by_application_id = new.id) then
      return null;
    end if;
    select o.id into seat from openings o
    where o.role_id = new.role_id and o.status = 'open'
    order by o.created_at, o.number
    limit 1
    for update skip locked;
    if seat is null then
      return null;
    end if;
    update openings set status = 'filled', filled_by_application_id = new.id where id = seat;
    if not exists (select 1 from openings o where o.role_id = new.role_id and o.status = 'open') then
      update roles set status = 'filled', updated_at = now() where id = new.role_id and status = 'open';
    end if;
  elsif tg_op = 'UPDATE' and old.stage = 'hired' and new.stage <> 'hired' then
    update openings set status = 'open' where filled_by_application_id = new.id and status = 'filled';
    -- A job with a job_open approval flow (20261016110000) stays filled: opening
    -- it again needs a new approval, which validate_job_approval would demand
    -- and which an un-hire must neither fail on nor spend.
    if found and not exists (
      select 1 from approval_flow_approvers a join approval_flows f on f.id = a.flow_id
      where f.role_id = new.role_id and f.kind = 'job_open'
    ) then
      update roles set status = 'open', updated_at = now() where id = new.role_id and status = 'filled';
    end if;
  end if;
  return null;
end;
$$;


--
-- Name: applications_guard_added_by(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.applications_guard_added_by() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.added_by_actor_id is distinct from old.added_by_actor_id
     and current_actor_id() is not null
     and current_access_level() <> 'admin' then
    raise exception 'only an admin may change who added an application'
      using errcode = 'insufficient_privilege';
  end if;
  return new;
end;
$$;


--
-- Name: applications_guard_channel(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.applications_guard_channel() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if current_actor_id() is not null
     and new.channel is distinct from (case when tg_op = 'UPDATE' then old.channel end) then
    raise exception 'channel is recorded by the public job post, not by a member'
      using errcode = 'insufficient_privilege';
  end if;
  return new;
end;
$$;


--
-- Name: applications_validate_rejection_reason(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.applications_validate_rejection_reason() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  want text := case new.stage when 'rejected' then 'rejected' when 'withdrawn' then 'withdrew' end;
  got text;
begin
  if want is null then
    new.rejection_reason_id := null;
    new.rejection_note := null;
    return new;
  end if;
  if new.rejection_reason_id is null then
    return new;
  end if;
  select r.kind into got from rejection_reasons r where r.id = new.rejection_reason_id and r.org_id = new.org_id;
  if got is distinct from want then
    -- A move between rejected and withdrawn under a reason of the other kind
    -- drops the reason rather than refusing the move.
    if tg_op = 'UPDATE' and new.rejection_reason_id is not distinct from old.rejection_reason_id then
      new.rejection_reason_id := null;
      return new;
    end if;
    raise exception 'that reason is not for a % application', new.stage using errcode = '22023';
  end if;
  return new;
end;
$$;


