--
-- Name: bot_task_command(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_task_command(p_task_id uuid, p_command text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := current_actor_id();
  my_org uuid := current_org_id();
  task bot_tasks%rowtype;
  command_id uuid;
begin
  if me is null then
    raise exception 'not a signed-in member of an org' using errcode = '42501';
  end if;
  if p_command is null or p_command not in ('retry', 'nudge', 'send_invite', 'cancel') then
    raise exception 'unknown bot task command' using errcode = '22023';
  end if;
  select t.* into task from bot_tasks t where t.id = p_task_id and t.org_id = my_org for update;
  if not found or can_read_bot_task(task.application_id, task.actor_id) is not true then
    raise exception 'bot task not found' using errcode = 'P0002';
  end if;
  if task.application_id is not null and not exists (
    select 1 from applications a
    where a.id = task.application_id and can_edit_application(a.role_id, a.added_by_actor_id)
  ) then
    raise exception 'you cannot act on this application' using errcode = '42501';
  end if;
  if task.status not in ('running', 'waiting', 'failed') then
    raise exception 'this bot task is already %', task.status using errcode = '22023';
  end if;
  insert into bot_task_commands (org_id, task_id, command, created_by_actor_id)
  values (my_org, p_task_id, p_command, me)
  on conflict (task_id, command) where status = 'pending' do nothing
  returning id into command_id;
  if command_id is null then
    select c.id into command_id from bot_task_commands c
    where c.task_id = p_task_id and c.command = p_command and c.status = 'pending';
    return command_id;
  end if;
  -- A fresh command on a stuck task means a member just handled the needs-you.
  update bot_tasks set needs_you = false, updated_at = now() where id = p_task_id and needs_you;
  insert into audit_log (org_id, actor_id, source, action, entity, after)
  values (my_org, me, 'dashboard', 'bot_task.command', 'bot_tasks', jsonb_build_object('task_id', p_task_id, 'command', p_command));
  return command_id;
end;
$$;


--
-- Name: bot_tasks_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_tasks_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if exists (
    select 1 from people p
    where p.anonymized_at is not null
      and (p.id = new.waiting_on_person_id
        or p.id = (select a.person_id from applications a where a.id = new.application_id)
        or p.id = (select coalesce(i.person_id, a.person_id)
                   from interviews i left join applications a on a.id = i.application_id
                   where i.id = new.interview_id))
  ) then
    new.steps := '[]'::jsonb;
    new.error := null;
    new.waiting_on_person_id := null;
    new.waiting_channel := null;
    if new.status in ('running', 'waiting', 'failed') then
      new.status := case when tg_op = 'UPDATE' and old.status = 'done' then 'done' else 'cancelled' end;
    end if;
  end if;
  if new.status in ('done', 'cancelled') then
    new.needs_you := false;
  end if;
  return new;
end;
$$;


