-- Name: can_add_people(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_add_people() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select case (select current_access_level())
    when 'admin' then true
    when 'elevated' then exists (
      select 1
      from job_access ja join access_roles ar on ar.id = ja.access_role_id
      where ja.actor_id = (select current_actor_id())
        and ar.can_edit_pipeline and not ar.own_candidates_only
    )
    else false
  end
$$;


