--
-- Name: can_edit_person(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_edit_person(p_person uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select case (select current_access_level())
    when 'admin' then exists (select 1 from people p where p.id = p_person and p.org_id = (select current_org_id()))
    when 'elevated' then exists (
      select 1 from applications a
      where a.person_id = p_person
        and a.org_id = (select current_org_id())
        and can_edit_application(a.role_id, a.added_by_actor_id)
    ) or (
      person_in_no_pipeline(p_person)
      and exists (
        select 1 from people p
        where p.id = p_person
          and p.org_id = (select current_org_id())
          and p.added_by_actor_id = (select current_actor_id()))
    )
    else false
  end
$$;


--
-- Name: can_on_role(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_on_role(p_role uuid, perm text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me actors%rowtype;
  job roles%rowtype;
  via access_roles%rowtype;
begin
  if perm not in ('can_view_candidates', 'can_edit_pipeline', 'can_email', 'can_schedule',
                  'can_view_feedback', 'can_view_private', 'can_manage_job') then
    raise exception 'can_on_role: unknown permission %', perm;
  end if;

  select a.* into me from actors a where a.id = current_actor_id();
  if not found or me.access_level = 'limited' then
    return false;
  end if;
  select r.* into job from roles r where r.id = p_role and r.org_id = me.org_id;
  if not found then
    return false;
  end if;
  select ar.* into via
  from job_access ja join access_roles ar on ar.id = ja.access_role_id
  where ja.actor_id = me.id and ja.role_id = p_role;

  if perm = 'can_view_private' then
    if job.confidential and via.id is null and not (me.access_level = 'admin' and me.can_view_all_confidential) then
      return false;
    end if;
    return me.can_view_private or coalesce(via.can_view_private, false);
  end if;

  if me.access_level = 'admin' and (not job.confidential or me.can_view_all_confidential or via.id is not null) then
    return true;
  end if;

  return case perm
    when 'can_view_candidates' then coalesce(via.can_view_candidates, false)
    when 'can_edit_pipeline' then coalesce(via.can_edit_pipeline, false)
    when 'can_email' then coalesce(via.can_email, false)
    when 'can_schedule' then coalesce(via.can_schedule, false)
    when 'can_view_feedback' then coalesce(via.can_view_feedback, false)
    when 'can_manage_job' then coalesce(via.can_manage_job, false)
  end;
end;
$$;


--
-- Name: can_read_application(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_read_application(p_role uuid, p_added_by uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select can_on_role(p_role, 'can_view_candidates')
    and (not own_candidates_only(p_role) or p_added_by = (select current_actor_id()))
$$;


--
-- Name: can_read_bot_task(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_read_bot_task(p_application uuid, p_actor uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select case
    when p_application is not null then exists (
      select 1 from applications a
      where a.id = p_application
        and a.org_id = (select current_org_id())
        and can_read_application(a.role_id, a.added_by_actor_id))
    else coalesce(p_actor = (select current_actor_id()) or (select current_access_level()) = 'admin', false)
  end
$$;


--
-- Name: can_read_person(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_read_person(p_person uuid, p_detail boolean DEFAULT false) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select case (select current_access_level())
    when 'admin' then exists (select 1 from people p where p.id = p_person and p.org_id = (select current_org_id()))
    when 'elevated' then exists (
      select 1 from applications a
      where a.person_id = p_person
        and a.org_id = (select current_org_id())
        and can_read_application(a.role_id, a.added_by_actor_id)
        and not (p_detail and own_candidates_only(a.role_id))
    ) or (
      person_in_no_pipeline(p_person)
      and (can_see_prospects()
           or (not p_detail and exists (
             select 1 from people p
             where p.id = p_person and p.added_by_actor_id = (select current_actor_id()))))
    )
    else false
  end
$$;


--
-- Name: can_see_approvals(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_see_approvals(p_role uuid, p_kind text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.can_on_role(p_role, 'can_manage_job')
    or exists (
      select 1 from approval_flow_approvers a
      join approval_flows f on f.id = a.flow_id
      where f.role_id = p_role and f.kind = p_kind
        and f.org_id = (select current_org_id())
        and a.actor_id = (select current_actor_id())
    )
$$;


--
-- Name: can_see_feedback(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_see_feedback(p_interview uuid, p_interviewer uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := current_actor_id();
  app applications%rowtype;
  mode text;
begin
  if me is null then
    return false;
  end if;
  if p_interviewer = me then
    return true;
  end if;
  select a.* into app
  from interviews i join applications a on a.id = i.application_id
  where i.id = p_interview and i.org_id = current_org_id();
  if not found or not can_on_role(app.role_id, 'can_view_feedback')
     or (own_candidates_only(app.role_id) and app.added_by_actor_id is distinct from me) then
    return false;
  end if;
  if current_access_level() = 'admin' then
    return true;
  end if;
  select o.feedback_visibility into mode from orgs o where o.id = app.org_id;
  if mode = 'always' then
    return true;
  elsif mode = 'never' then
    return false;
  end if;
  -- after_submit: nothing of theirs is outstanding on this application.
  return not exists (
    select 1 from interviews i
    where i.application_id = app.id
      and me = any (i.interviewer_actor_ids)
      and not exists (
        select 1 from interview_feedback f
        where f.interview_id = i.id and f.interviewer_actor_id = me
      )
  );
end;
$$;


--
-- Name: can_see_prospects(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_see_prospects() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select case (select current_access_level())
    when 'admin' then true
    when 'elevated' then can_add_people() or not exists (
      select 1
      from job_access ja join access_roles ar on ar.id = ja.access_role_id
      where ja.actor_id = (select current_actor_id()) and ar.own_candidates_only
    )
    else false
  end
$$;


--
-- Name: can_see_role(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_see_role(p_role uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select can_on_role(p_role, 'can_view_candidates')
    or can_on_role(p_role, 'can_manage_job')
    or exists (
      select 1
      from interviews i join applications a on a.id = i.application_id
      where a.role_id = p_role
        and i.org_id = (select current_org_id())
        and (select current_actor_id()) = any (i.interviewer_actor_ids)
    )
$$;


--
-- Name: can_view_private_person(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_view_private_person(p_person uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce((select a.can_view_private and a.access_level <> 'limited' from actors a where a.id = (select current_actor_id())), false)
    or exists (
      select 1 from applications a
      where a.person_id = p_person
        and a.org_id = (select current_org_id())
        and can_on_role(a.role_id, 'can_view_private')
    )
$$;


--
-- Name: candidate_emails_sent_via_validate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.candidate_emails_sent_via_validate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'INSERT' then
    new.sent_via := null;
    new.thread_id := null;
  elsif not (old.status = 'sending' and new.status = 'sent') then
    new.sent_via := old.sent_via;
    new.thread_id := old.thread_id;
  elsif new.thread_id is not null and new.sent_via is distinct from 'gmail' then
    raise exception 'only an email sent through Gmail has a thread' using errcode = '22023';
  end if;
  return new;
end;
$$;


--
-- Name: candidate_emails_validate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.candidate_emails_validate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  sent_last_hour int;
begin
  if tg_op = 'INSERT' then
    -- Another org's person: refused before the checks below can answer
    -- anything about them (the policy would refuse it too, but after).
    if current_org_id() is not null and new.org_id is distinct from current_org_id() then
      raise exception 'not your company''s candidate' using errcode = '42501';
    end if;
    if new.status <> 'draft' then
      raise exception 'an email starts as a draft' using errcode = '22023';
    end if;
    new.provider_id := null;
    new.error := null;
    new.sending_at := null;
    new.sent_at := null;
    if new.application_id is not null and not exists (
      select 1 from applications a
      where a.id = new.application_id and a.org_id = new.org_id and a.person_id = new.person_id
    ) then
      raise exception 'that application is not this candidate''s' using errcode = '22023';
    end if;
    if not exists (
      select 1 from people p
      where p.id = new.person_id and p.org_id = new.org_id and lower(btrim(p.email)) = new.to_email
    ) and not exists (
      select 1 from person_identifiers i
      where i.person_id = new.person_id and i.org_id = new.org_id and i.kind = 'email' and lower(btrim(i.value)) = new.to_email
    ) then
      raise exception 'that address is not on file for this candidate' using errcode = '22023';
    end if;
    new.updated_at := now();
    return new;
  end if;

  -- 20261016160000: client_merge_candidates moves an email to the record
  -- kept, and nothing else about it, inside its own transaction (tacit.merging
  -- is set only there; a member cannot set a setting through the API).
  if current_setting('tacit.merging', true) = 'on' and new.person_id <> old.person_id
     and (to_jsonb(new) - 'person_id') = (to_jsonb(old) - 'person_id') then
    return new;
  end if;

  -- What was drafted is what goes out. The FKs' own set null is the one
  -- change those columns take.
  if new.org_id <> old.org_id or new.person_id <> old.person_id
     or new.to_email <> old.to_email or new.subject <> old.subject or new.body <> old.body
     or new.created_at <> old.created_at
     or (new.application_id is distinct from old.application_id and new.application_id is not null)
     or (new.template_id is distinct from old.template_id and new.template_id is not null)
     or (new.author_actor_id is distinct from old.author_actor_id and new.author_actor_id is not null) then
    raise exception 'an email does not change once drafted: write a new draft' using errcode = '22023';
  end if;

  if new.status = old.status then
    new.provider_id := old.provider_id;
    new.error := old.error;
    new.sending_at := old.sending_at;
    new.sent_at := old.sent_at;
  elsif old.status = 'draft' and new.status = 'sending' then
    if new.author_actor_id is not null then
      perform pg_advisory_xact_lock(hashtextextended('candidate_emails.send:' || new.author_actor_id::text, 0));
      select count(*) into sent_last_hour from candidate_emails e
      where e.author_actor_id = new.author_actor_id and e.sending_at > now() - interval '1 hour';
      if sent_last_hour >= 30 then
        raise exception 'at most 30 candidate emails an hour' using errcode = '54000';
      end if;
    end if;
    new.sending_at := now();
    new.sent_at := null;
    new.provider_id := null;
    new.error := null;
  elsif old.status = 'sending' and new.status = 'sent' then
    if new.provider_id is null then
      raise exception 'a sent email names the provider''s id for it' using errcode = '22023';
    end if;
    new.sending_at := old.sending_at;
    new.sent_at := now();
    new.error := null;
  elsif old.status = 'sending' and new.status = 'failed' then
    new.sending_at := old.sending_at;
    new.sent_at := null;
    new.provider_id := null;
  else
    raise exception 'an email cannot go from % to %', old.status, new.status using errcode = '22023';
  end if;
  new.updated_at := now();
  return new;
end;
$$;


--
-- Name: claim_notify_delivery(uuid, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_notify_delivery(p_delivery_id uuid, p_daily_cap integer, p_now timestamp with time zone DEFAULT now()) RETURNS text
    LANGUAGE plpgsql
    AS $$
declare
  d public.notify_deliveries;
  recent integer;
  agent_channels constant text[] := array['grok_bot_webhook', 'claude_routine_webhook'];
begin
  select * into d from public.notify_deliveries where id = p_delivery_id;
  if not found then return 'taken'; end if;

  -- Serialises claims for one recipient, so the count below is not raced.
  perform pg_advisory_xact_lock(hashtextextended('notify:' || coalesce(d.actor_id::text, 'target:' || d.target), 0));

  select * into d from public.notify_deliveries where id = p_delivery_id for update;
  if not found or d.status <> 'pending' then return 'taken'; end if;

  select count(*) into recent
  from public.notify_deliveries o
  where o.status in ('sending', 'sent')
    and o.claimed_at > p_now - interval '24 hours'
    and case when d.actor_id is not null then o.actor_id = d.actor_id
             else o.actor_id is null and o.target = d.target end
    and case when d.channel = any (agent_channels) then o.channel = d.channel
             else o.channel <> all (agent_channels) end;

  if recent >= p_daily_cap then
    update public.notify_deliveries set status = 'skipped', error = 'daily_cap' where id = p_delivery_id;
    return 'capped';
  end if;

  update public.notify_deliveries
    set status = 'sending', claimed_at = p_now, attempts = attempts + 1, error = null
    where id = p_delivery_id;
  return 'claimed';
end;
$$;


--
-- Name: client_add_contact(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_add_contact(p_person uuid, p_kind text, p_value text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  k text := lower(regexp_replace(coalesce(p_kind, ''), '^\s+|\s+$', '', 'g'));
  v text := regexp_replace(coalesce(p_value, ''), '^\s+|\s+$', '', 'g');
  new_id uuid;
begin
  if k not in ('email', 'phone', 'linkedin') then
    raise exception 'unknown contact kind' using errcode = '22023';
  end if;
  if v = '' or length(v) > 320 then
    raise exception 'a contact value of at most 320 characters' using errcode = '22023';
  end if;
  if not (select can_edit_person(p_person)) then
    raise exception 'no candidate with that id that you can edit' using errcode = '42501';
  end if;
  insert into person_identifiers (person_id, org_id, kind, value)
  select p.id, p.org_id, k, v from people p where p.id = p_person
  on conflict do nothing
  returning id into new_id;
  return new_id;
end;
$_$;


--
-- Name: client_anonymize_candidate(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_anonymize_candidate(p_person uuid, p_confirm text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  me uuid := current_actor_id();
  my_org uuid := current_org_id();
  target people%rowtype;
  expected text;
  unhandled text[];
  ids uuid[];
  apps uuid[];
  ints uuid[];
  offs uuid[];
  feedback uuid[];
  file_ids uuid[];
  paths text[];
  msgs uuid[];
  note_ids uuid[];
  digests text[];
  cols text;
  n int;
  removed jsonb := '{}'::jsonb;
begin
  if me is null or current_access_level() is distinct from 'admin' then
    raise exception 'only an admin can anonymize a candidate' using errcode = '42501';
  end if;
  select * into target from people where id = p_person and org_id = my_org for update;
  if not found then
    raise exception 'no such candidate' using errcode = 'P0002';
  end if;
  if target.anonymized_at is not null then
    raise exception 'candidate already anonymized' using errcode = '55000';
  end if;
  if target.merged_into_id is not null then
    raise exception 'candidate already merged into another record' using errcode = '55000';
  end if;
  expected := 'ANONYMIZE ' || coalesce(nullif(regexp_replace(btrim(target.display_name), '\s+', ' ', 'g'), ''), target.id::text);
  if p_confirm is null or regexp_replace(btrim(p_confirm), '\s+', ' ', 'g') is distinct from expected then
    raise exception 'the confirmation does not name this candidate' using errcode = '22023';
  end if;
  unhandled := client_person_fks_unhandled();
  if cardinality(unhandled) > 0 then
    raise exception 'erasure does not know %', array_to_string(unhandled, ', ') using errcode = '0A000';
  end if;

  -- The person and every row merged into them, at any depth.
  with recursive s(id) as (
    select p_person
    union
    select p.id from people p join s on p.merged_into_id = s.id where p.org_id = my_org
  )
  select array_agg(s.id) into ids from s;
  perform 1 from people where id = any (ids) order by id for update;
  if exists (select 1 from actors where person_id = any (ids)) then
    raise exception 'candidate is linked to a team member' using errcode = '55000';
  end if;

  select coalesce(array_agg(id), '{}') into apps from applications where person_id = any (ids);
  select coalesce(array_agg(id), '{}') into ints from interviews where application_id = any (apps);
  select coalesce(array_agg(id), '{}') into offs from offers where application_id = any (apps);
  select coalesce(array_agg(id), '{}') into feedback from interview_feedback where interview_id = any (ints);
  select coalesce(array_agg(id), '{}'), coalesce(array_agg(storage_path), '{}') into file_ids, paths
    from person_files where person_id = any (ids);
  select coalesce(array_agg(id), '{}') into msgs from candidate_messages
    where person_id = any (ids) or application_id = any (apps);
  select coalesce(array_agg(id), '{}') into note_ids from person_notes where person_id = any (ids);
  select coalesce(array_agg(distinct md5(e)), '{}') into digests from (
    select lower(btrim(email)) as e from people where id = any (ids) and email is not null
    union select lower(btrim(value)) from person_identifiers where person_id = any (ids) and kind = 'email'
  ) x;

  -- The people rows: every nullable column but the structural ones is erased.
  select string_agg(format('%I = null', c.column_name), ', ' order by c.ordinal_position) into cols
  from information_schema.columns c
  where c.table_schema = 'public' and c.table_name = 'people'
    and c.is_nullable = 'YES' and c.is_generated = 'NEVER'
    and c.column_name::text not in (
      'id', 'org_id', 'created_at', 'updated_at', 'display_name', 'funnel_stage', 'funnel_stage_at', 'stage',
      'applicant_status', 'rubric_id', 'merged_into_id', 'merged_at', 'merged_by_actor_id',
      'anonymized_at', 'anonymized_by_actor_id', 'added_by_actor_id', 'prospect_source');
  perform set_config('tacit.reason', 'manual', true);
  perform set_config('tacit.actor_id', me::text, true);
  execute format(
    'update people set %s, display_name = %L, anonymized_at = now(), anonymized_by_actor_id = $1 where id = any ($2)',
    cols, 'Anonymized candidate') using me, ids;
  get diagnostics n = row_count;
  removed := removed || jsonb_build_object('people', n);

  -- Deleted: everything that is about the person rather than the process.
  -- person_snapshots goes after the update above, which wrote one.
  delete from person_identifiers where person_id = any (ids);
  get diagnostics n = row_count; removed := removed || jsonb_build_object('identifiers', n);
  delete from transcript_entries where person_id = any (ids);
  get diagnostics n = row_count; removed := removed || jsonb_build_object('transcript_entries', n);
  delete from person_notes where person_id = any (ids);
  get diagnostics n = row_count; removed := removed || jsonb_build_object('notes', n);
  delete from person_files where person_id = any (ids);
  get diagnostics n = row_count; removed := removed || jsonb_build_object('files', n);
  delete from person_tags where person_id = any (ids);
  get diagnostics n = row_count; removed := removed || jsonb_build_object('tags', n);
  delete from person_facts where person_id = any (ids);
  get diagnostics n = row_count; removed := removed || jsonb_build_object('facts', n);
  delete from identity_links where person_id = any (ids);
  delete from lookup_runs where person_id = any (ids);
  delete from enrichment_records where person_id = any (ids);
  delete from update_proposals where person_id = any (ids);
  delete from person_snapshots where person_id = any (ids);
  delete from enrichment_jobs where person_id = any (ids);
  delete from debriefs where person_id = any (ids);
  delete from outreach_messages where person_id = any (ids);
  delete from candidate_emails where person_id = any (ids);
  get diagnostics n = row_count; removed := removed || jsonb_build_object('emails', n);
  delete from custom_field_values where person_id = any (ids);
  get diagnostics n = row_count; removed := removed || jsonb_build_object('custom_field_values', n);
  delete from pool_memberships where person_id = any (ids);
  get diagnostics n = row_count; removed := removed || jsonb_build_object('pool_memberships', n);
  -- What they typed into a job post's form, and the post's rate-limit rows
  -- keyed by an md5 of their address.
  delete from application_answers where application_id = any (apps);
  get diagnostics n = row_count; removed := removed || jsonb_build_object('application_answers', n);
  delete from job_post_attempts where org_id = my_org and email_digest = any (digests);
  delete from candidate_messages where id = any (msgs);
  get diagnostics n = row_count; removed := removed || jsonb_build_object('messages', n);
  delete from people_merges where primary_id = any (ids);
  -- Their approval requests and decisions (with reasons) and their custom
  -- field values go with them (cascades; no delete trigger refuses).
  delete from offers where application_id = any (apps);
  get diagnostics n = row_count; removed := removed || jsonb_build_object('offers', n);
  delete from nudges where application_id = any (apps);
  delete from invite_prefills where person_id = any (ids);
  delete from scheduling_cursors where person_id = any (ids);
  delete from slack_meeting_posts where person_id = any (ids);

  -- Kept for reporting, with their free text blanked.
  update applications set next_action = null, rejection_note = null, source_detail = null where id = any (apps);
  update application_events set detail = null where application_id = any (apps);
  update interviews set location_or_link = null, google_event_link = null where id = any (ints);
  update interview_feedback set notes = '' where id = any (feedback);
  update interview_feedback_ratings set note = null where feedback_id = any (feedback);
  update person_funnel_events set detail = null where person_id = any (ids);
  -- Someone else's debrief that mentions them keeps the mention, not the name.
  update debrief_mentions set mentioned_person_id = null, name = 'Anonymized candidate'
    where mentioned_person_id = any (ids);
  -- Tacit's rolodex rows are Tacit's own records of the person: unlinked here.
  update linkedin_connections set person_id = null where person_id = any (ids);
  update instagram_connections set person_id = null where person_id = any (ids);
  update instagram_follow_edges set follower_person_id = null where follower_person_id = any (ids);
  update instagram_follow_edges set followee_person_id = null where followee_person_id = any (ids);
  update network_people set person_id = null where person_id = any (ids);

  -- Audit rows about any of it keep who did what and when, not what it said.
  -- after stays non-null: a null after is an open claim (client_finish_write).
  update audit_log set before = null, after = '{"anonymized": true}'::jsonb
  where org_id = my_org
    and entity_id = any (ids || apps || ints || offs || feedback || file_ids || msgs || note_ids);

  return jsonb_build_object('anonymized', cardinality(ids), 'removed', removed, 'storage_paths', to_jsonb(paths));
end;
$_$;


--
-- Name: client_claim_write(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_claim_write(p_source text, p_action text, p_entity text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  me uuid := current_actor_id();
  n int;
  claimed uuid;
begin
  if me is null then
    raise exception 'not a signed-in member of an org' using errcode = '42501';
  end if;
  if p_source is null or p_source not in ('claude', 'chatgpt', 'cli', 'dashboard') then
    raise exception 'unknown source' using errcode = '22023';
  end if;
  if p_action is null or p_action !~ '^[a-z_]+\.[a-z_]+$' or p_entity is null or p_entity !~ '^[a-z_]+$' then
    raise exception 'malformed action or entity' using errcode = '22023';
  end if;
  if p_source <> 'dashboard'
     and not (p_action = 'org.connector_access' and current_access_level() = 'admin')
     and exists (select 1 from orgs o where o.id = current_org_id() and o.connector_access = 'read_only') then
    raise exception 'the client connector is read-only for this org' using errcode = '42501';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('client-writes:' || me::text, 0));
  select count(*) into n from audit_log a where a.actor_id = me and a.created_at > now() - interval '1 hour';
  if n >= 300 then
    return null;
  end if;
  insert into audit_log (actor_id, source, action, entity)
  values (me, p_source, p_action, p_entity)
  returning id into claimed;
  return claimed;
end;
$_$;


--
-- Name: client_connect_calendar(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_connect_calendar(p_provider text, p_account_email text, p_refresh_token text, p_scopes text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := current_actor_id();
  my_org uuid := current_org_id();
begin
  if me is null then
    raise exception 'not a signed-in member' using errcode = '42501';
  end if;
  if p_provider is distinct from 'google' then
    raise exception 'only Google Calendar can be connected' using errcode = '22023';
  end if;
  if coalesce(btrim(p_refresh_token), '') = '' then
    raise exception 'no refresh token' using errcode = '22023';
  end if;
  insert into calendar_connections (actor_id, org_id, provider, account_email, refresh_token, scopes, connected_at)
  values (me, my_org, p_provider, lower(btrim(p_account_email)), p_refresh_token, coalesce(p_scopes, ''), now())
  on conflict (actor_id) do update set
    provider = excluded.provider, account_email = excluded.account_email, refresh_token = excluded.refresh_token,
    scopes = excluded.scopes, connected_at = excluded.connected_at;
end;
$$;


--
-- Name: client_connect_granola(text, text, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_connect_granola(p_oauth_client_id text, p_refresh_token text, p_access_token text, p_access_token_expires_at timestamp with time zone, p_account_email text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := current_actor_id();
  my_org uuid := current_org_id();
  email text := nullif(lower(btrim(coalesce(p_account_email, ''))), '');
begin
  if me is null then
    raise exception 'not a signed-in member' using errcode = '42501';
  end if;
  if coalesce(btrim(p_oauth_client_id), '') = '' or coalesce(btrim(p_refresh_token), '') = '' then
    raise exception 'no Granola grant' using errcode = '22023';
  end if;
  insert into granola_connections
    (actor_id, org_id, oauth_client_id, refresh_token, access_token, access_token_expires_at, account_email, connected_at)
  values
    (me, my_org, btrim(p_oauth_client_id), btrim(p_refresh_token), nullif(btrim(coalesce(p_access_token, '')), ''),
     p_access_token_expires_at, email, now())
  on conflict (actor_id) do update set
    oauth_client_id = excluded.oauth_client_id,
    refresh_token = excluded.refresh_token,
    access_token = excluded.access_token,
    access_token_expires_at = excluded.access_token_expires_at,
    account_email = excluded.account_email,
    connected_at = excluded.connected_at;
end;
$$;


--
-- Name: client_connect_mailbox(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_connect_mailbox(p_provider text, p_account_email text, p_refresh_token text, p_scopes text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := current_actor_id();
  my_org uuid := current_org_id();
begin
  if me is null then
    raise exception 'not a signed-in member' using errcode = '42501';
  end if;
  if p_provider is distinct from 'google' then
    raise exception 'only Gmail can be connected' using errcode = '22023';
  end if;
  if coalesce(btrim(p_refresh_token), '') = '' then
    raise exception 'no refresh token' using errcode = '22023';
  end if;
  insert into mailbox_connections (actor_id, org_id, provider, account_email, refresh_token, scopes, connected_at)
  values (me, my_org, p_provider, lower(btrim(p_account_email)), p_refresh_token, coalesce(p_scopes, ''), now())
  on conflict (actor_id) do update set
    provider = excluded.provider, account_email = excluded.account_email, refresh_token = excluded.refresh_token,
    scopes = excluded.scopes, connected_at = excluded.connected_at;
  -- Another account is another mailbox: the sync starts over.
  delete from mailbox_sync_state where actor_id = me;
end;
$$;


--
-- Name: client_connect_workspace(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_connect_workspace(p_domain text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := current_actor_id();
  my_org uuid := current_org_id();
  mine text;
begin
  if me is null then
    raise exception 'not a signed-in member' using errcode = '42501';
  end if;
  if current_access_level() is distinct from 'admin' then
    raise exception 'only an admin connects the company''s Google Workspace' using errcode = '42501';
  end if;
  select lower(split_part(btrim(email), '@', 2)) into mine from actors where id = me;
  if mine is null or mine = '' or lower(btrim(p_domain)) is distinct from mine then
    raise exception 'connect the domain of your own address' using errcode = '22023';
  end if;
  insert into google_workspace_connections (org_id, domain, connected_by_actor_id, verified_at)
  values (my_org, mine, me, now())
  on conflict (org_id) do update set domain = excluded.domain, connected_by_actor_id = excluded.connected_by_actor_id, verified_at = excluded.verified_at;
end;
$$;


