--
-- Name: client_enable_agent_destination(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_enable_agent_destination(p_enabled boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := current_actor_id();
  my_org uuid := current_org_id();
begin
  if me is null or current_access_level() is distinct from 'admin' then
    raise exception 'only an admin can change the company''s bot' using errcode = '42501';
  end if;
  update agent_destinations set enabled = coalesce(p_enabled, false), updated_at = now()
  where org_id = my_org and channel = 'grok_bot_webhook';
  if not found then
    return false;
  end if;
  insert into audit_log (org_id, actor_id, source, action, entity, after)
  values (my_org, me, 'dashboard', 'agent_destination.enable', 'agent_destinations', jsonb_build_object('enabled', coalesce(p_enabled, false)));
  return true;
end;
$$;


--
-- Name: client_finish_write(uuid, uuid, jsonb, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_finish_write(p_audit uuid, p_entity_id uuid, p_before jsonb, p_after jsonb, p_keep boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := current_actor_id();
begin
  if me is null then
    raise exception 'not a signed-in member of an org' using errcode = '42501';
  end if;
  if p_keep then
    update audit_log
    set entity_id = p_entity_id, before = p_before, after = coalesce(p_after, '{}'::jsonb)
    where id = p_audit and actor_id = me and after is null;
  else
    delete from audit_log where id = p_audit and actor_id = me and after is null;
  end if;
end;
$$;


--
-- Name: client_merge_candidates(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_merge_candidates(p_keep uuid, p_merge uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  me uuid := current_actor_id();
  my_org uuid := current_org_id();
  keep_row people%rowtype;
  merge_row people%rowtype;
  unhandled text[];
  -- How far along an application is: an open one beats a closed one.
  stage_rank constant text[] := array['withdrawn', 'rejected', 'sourced', 'contacted', 'screening', 'interviewing', 'offer', 'hired'];
  pair record;
  winner uuid;
  loser uuid;
  merged_apps int := 0;
  moved jsonb := '{}'::jsonb;
  left_behind jsonb := '{}'::jsonb;
  step jsonb;
  fk text;
  n int;
  fill text[];
begin
  if me is null or current_access_level() is distinct from 'admin' then
    raise exception 'only an admin can merge candidates' using errcode = '42501';
  end if;
  if p_keep is null or p_merge is null or p_keep = p_merge then
    raise exception 'pick two different candidates' using errcode = '22023';
  end if;

  -- Both rows, locked in a fixed order so two merges of the same pair cannot deadlock.
  perform 1 from people where id in (p_keep, p_merge) and org_id = my_org order by id for update;
  select * into keep_row from people where id = p_keep and org_id = my_org;
  if not found then
    raise exception 'no such candidate (keep)' using errcode = 'P0002';
  end if;
  select * into merge_row from people where id = p_merge and org_id = my_org;
  if not found then
    raise exception 'no such candidate (merge)' using errcode = 'P0002';
  end if;
  if keep_row.merged_into_id is not null or merge_row.merged_into_id is not null then
    raise exception 'candidate already merged' using errcode = '55000';
  end if;
  if keep_row.anonymized_at is not null or merge_row.anonymized_at is not null then
    raise exception 'candidate anonymized' using errcode = '55000';
  end if;
  unhandled := client_person_fks_unhandled();
  if cardinality(unhandled) > 0 then
    raise exception 'merge does not know %', array_to_string(unhandled, ', ') using errcode = '0A000';
  end if;

  -- The snapshot the field fill below triggers (people_snapshot_before_change).
  perform set_config('tacit.reason', 'identity_link', true);
  perform set_config('tacit.actor_id', me::text, true);

  -- A team member's identity: never two at once; follow the duplicate's.
  if exists (select 1 from actors where person_id = p_merge) then
    if exists (select 1 from actors where person_id = p_keep) then
      raise exception 'both candidates are linked to team members' using errcode = '55000';
    end if;
    update actors set person_id = p_keep where person_id = p_merge;
  end if;

  -- The same job twice: keep the more advanced application (keep's on a tie),
  -- mark the other merged into it, and move its interviews where they fit.
  for pair in
    select k.id as keep_app, k.stage as keep_stage, m.id as merge_app, m.stage as merge_stage
    from applications k
    join applications m on m.role_id = k.role_id
    where k.person_id = p_keep and m.person_id = p_merge
      and k.merged_into_id is null and m.merged_into_id is null
    for update of k, m
  loop
    if coalesce(array_position(stage_rank, pair.merge_stage), 0) > coalesce(array_position(stage_rank, pair.keep_stage), 0) then
      winner := pair.merge_app;
      loser := pair.keep_app;
    else
      winner := pair.keep_app;
      loser := pair.merge_app;
    end if;
    update applications set merged_into_id = winner where id = loser;
    update applications set merged_into_id = winner where merged_into_id = loser;
    perform client_merge_move('public.interviews'::regclass, 'application_id', loser, winner);
    insert into application_events (application_id, actor_id, kind, detail)
    values (winner, me, 'note', 'A duplicate candidate''s application to this job was merged into this one.');
    merged_apps := merged_apps + 1;
  end loop;
  -- Every live application of merge is now alone in its job on keep.
  update applications set person_id = p_keep where person_id = p_merge;
  get diagnostics n = row_count;
  if n > 0 then
    moved := moved || jsonb_build_object('applications.person_id', n);
  end if;

  -- Everything else that names merge.
  perform set_config('tacit.merging', 'on', true);
  foreach fk in array client_merge_person_fks() loop
    continue when fk in ('actors.person_id', 'applications.person_id');
    if fk in ('custom_field_values.person_id', 'pool_memberships.person_id') then
      step := client_merge_rehome(split_part(fk, '.', 1)::regclass, split_part(fk, '.', 2), p_merge, p_keep);
    else
      step := client_merge_move(split_part(fk, '.', 1)::regclass, split_part(fk, '.', 2), p_merge, p_keep);
    end if;
    if (step ->> 'moved')::int > 0 then
      moved := moved || jsonb_build_object(fk, (step ->> 'moved')::int);
    end if;
    if (step ->> 'kept')::int > 0 then
      left_behind := left_behind || jsonb_build_object(fk, (step ->> 'kept')::int);
    end if;
  end loop;
  perform set_config('tacit.merging', 'off', true);

  -- Fill keep's blank fields from merge, never overwriting. Every nullable
  -- column but the structural and unique ones, so a column added later is
  -- filled by default. Blank: null, an empty or whitespace string, [] or {}.
  select coalesce(array_agg(c.column_name::text order by c.ordinal_position), '{}'::text[]) into fill
  from information_schema.columns c
  cross join lateral (
    select to_jsonb(keep_row) -> c.column_name::text as k, to_jsonb(merge_row) -> c.column_name::text as m
  ) v
  where c.table_schema = 'public' and c.table_name = 'people'
    and c.is_nullable = 'YES' and c.is_generated = 'NEVER'
    and c.column_name::text not in (
      'id', 'org_id', 'created_at', 'updated_at', 'merged_into_id', 'merged_at', 'merged_by_actor_id',
      'anonymized_at', 'anonymized_by_actor_id', 'auth_user_id', 'portal_token_digest', 'portal_token_rotated_at',
      'funnel_stage_at', 'added_by_actor_id')
    and (v.k is null or v.k in ('null'::jsonb, '""'::jsonb, '[]'::jsonb, '{}'::jsonb)
         or (jsonb_typeof(v.k) = 'string' and btrim(v.k #>> '{}') = ''))
    and not (v.m is null or v.m in ('null'::jsonb, '""'::jsonb, '[]'::jsonb, '{}'::jsonb)
             or (jsonb_typeof(v.m) = 'string' and btrim(v.m #>> '{}') = ''));
  if cardinality(fill) > 0 then
    execute format('update people k set %s from people m where k.id = $1 and m.id = $2',
                   (select string_agg(format('%I = m.%I', f, f), ', ') from unnest(fill) f))
      using p_keep, p_merge;
  end if;

  update people set merged_into_id = p_keep, merged_at = now(), merged_by_actor_id = me where id = p_merge;

  return jsonb_build_object(
    'keep_id', p_keep,
    'merged_id', p_merge,
    'applications_merged', merged_apps,
    'moved', moved,
    'left_behind', left_behind,
    'filled', to_jsonb(fill)
  );
end;
$_$;


--
-- Name: client_merge_move(regclass, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_merge_move(p_table regclass, p_column text, p_from uuid, p_to uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
declare
  r record;
  n int;
  moved int := 0;
  kept int := 0;
begin
  begin
    execute format('update %s set %I = $1 where %I = $2', p_table, p_column, p_column) using p_to, p_from;
    get diagnostics n = row_count;
    return jsonb_build_object('moved', n, 'kept', 0);
  exception when unique_violation then
    null;
  end;
  for r in execute format('select ctid from %s where %I = $1', p_table, p_column) using p_from loop
    begin
      execute format('update %s set %I = $1 where ctid = $2', p_table, p_column) using p_to, r.ctid;
      moved := moved + 1;
    exception when unique_violation then
      kept := kept + 1;
    end;
  end loop;
  return jsonb_build_object('moved', moved, 'kept', kept);
end;
$_$;


--
-- Name: client_merge_person_fks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_merge_person_fks() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select array[
    -- Tenant tables: (org_id, column) -> people (org_id, id).
    'actors.person_id',
    'applications.person_id',
    'candidate_emails.person_id',
    'candidate_messages.person_id',
    'custom_field_values.person_id',
    'debrief_mentions.mentioned_person_id',
    'debriefs.person_id',
    'enrichment_jobs.person_id',
    'enrichment_records.person_id',
    'identity_links.person_id',
    'lookup_runs.person_id',
    'outreach_messages.person_id',
    'people.merged_into_id',
    'people_merges.primary_id',
    'person_facts.person_id',
    'person_files.person_id',
    'person_funnel_events.person_id',
    'person_identifiers.person_id',
    'person_notes.person_id',
    'person_snapshots.person_id',
    'person_tags.person_id',
    'pool_memberships.person_id',
    'transcript_entries.person_id',
    'update_proposals.person_id',
    -- Tacit's platform tables (no org_id): in practice only ever Tacit's people.
    'instagram_connections.person_id',
    'instagram_follow_edges.followee_person_id',
    'instagram_follow_edges.follower_person_id',
    'invite_prefills.person_id',
    'linkedin_connections.person_id',
    'network_people.person_id',
    'scheduling_cursors.person_id',
    'slack_meeting_posts.person_id',
    -- 20261017130000_tacit_submissions: Tacit's link to a client's copy. A
    -- client merge repoints client_person_id to the record kept; erasure leaves
    -- it on the anonymized row, which carries nothing personal. tacit_person_id
    -- is only ever Tacit's.
    'tacit_submissions.client_person_id',
    'tacit_submissions.tacit_person_id',
    -- 20261019180000_tacit_interviews: Tacit's own interviews, on the person
    -- (a client's interviews hang off an application and leave it null).
    -- merge_people moves it; a client merge or erasure never reaches Tacit's
    -- org, so nothing there has one to move.
    'interviews.person_id',
    -- This migration: whom the company's bot is waiting on. A client merge
    -- moves it to the record kept; erasure clears it (people_erase_bot_tasks).
    -- Tacit's own merge_people deletes the duplicate, and the FK's set null
    -- leaves the task waiting on no one.
    'bot_tasks.waiting_on_person_id',
    -- 20261106120000_client_mailbox: synced email with the candidate. A client
    -- merge moves it to the record kept; erasure deletes it
    -- (people_erase_candidate_mail).
    'candidate_mail.person_id'
  ]::text[]
$$;


--
-- Name: client_merge_rehome(regclass, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_merge_rehome(p_table regclass, p_column text, p_from uuid, p_to uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
declare
  r record;
  moved int := 0;
  kept int := 0;
begin
  for r in execute format('select to_jsonb(t) as j from %s t where %I = $1', p_table, p_column) using p_from loop
    begin
      execute format('delete from %s where id = $1', p_table) using (r.j ->> 'id')::uuid;
      execute format('insert into %s select * from jsonb_populate_record(null::%s, $1)', p_table, p_table)
        using jsonb_set(r.j, array[p_column], to_jsonb(p_to));
      moved := moved + 1;
    exception when unique_violation or invalid_parameter_value then
      kept := kept + 1;
    end;
  end loop;
  return jsonb_build_object('moved', moved, 'kept', kept);
end;
$_$;


--
-- Name: client_person_fks_unhandled(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_person_fks_unhandled() RETURNS text[]
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select coalesce(array_agg(f.fk order by f.fk), '{}'::text[])
  from (
    select distinct c.conrelid::regclass::text || '.' || a.attname as fk
    from pg_constraint c
    cross join lateral unnest(c.conkey) as k(attnum)
    join pg_attribute a on a.attrelid = c.conrelid and a.attnum = k.attnum
    where c.contype = 'f' and c.confrelid = 'public.people'::regclass and a.attname <> 'org_id'
  ) f
  where f.fk <> all (public.client_merge_person_fks())
$$;


--
-- Name: client_remove_agent_destination(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_remove_agent_destination() RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := current_actor_id();
  my_org uuid := current_org_id();
  before_url text;
begin
  if me is null or current_access_level() is distinct from 'admin' then
    raise exception 'only an admin can change the company''s bot' using errcode = '42501';
  end if;
  delete from agent_destinations where org_id = my_org and channel = 'grok_bot_webhook' returning url into before_url;
  if before_url is null then
    return false;
  end if;
  insert into audit_log (org_id, actor_id, source, action, entity, before)
  values (my_org, me, 'dashboard', 'agent_destination.remove', 'agent_destinations', jsonb_build_object('url', before_url));
  return true;
end;
$$;


--
-- Name: client_rotate_agent_secret(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_rotate_agent_secret(p_key text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := current_actor_id();
  my_org uuid := current_org_id();
  v_key text := nullif(btrim(coalesce(p_key, '')), '');
  v_secret text;
begin
  if me is null or current_access_level() is distinct from 'admin' then
    raise exception 'only an admin can change the company''s bot' using errcode = '42501';
  end if;
  if v_key is not null and not agent_key_valid(v_key) then
    raise exception 'the bot''s key must be 16 to 512 characters with no spaces' using errcode = '22023';
  end if;
  v_secret := coalesce(v_key, new_agent_secret());
  update agent_destinations set secret = v_secret, verified_at = null, updated_at = now()
  where org_id = my_org and channel = 'grok_bot_webhook';
  if not found then
    raise exception 'the company has no bot set' using errcode = 'P0002';
  end if;
  insert into audit_log (org_id, actor_id, source, action, entity, after)
  values (my_org, me, 'dashboard', 'agent_destination.rotate_secret', 'agent_destinations',
    jsonb_build_object('key', case when v_key is null then 'generated' else 'provided' end));
  return case when v_key is null then v_secret else null end;
end;
$$;


--
-- Name: client_set_agent_destination(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_set_agent_destination(p_url text, p_key text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  me uuid := current_actor_id();
  my_org uuid := current_org_id();
  v_url text := btrim(coalesce(p_url, ''));
  v_key text := nullif(btrim(coalesce(p_key, '')), '');
  v_secret text;
  before_url text;
begin
  if me is null or current_access_level() is distinct from 'admin' then
    raise exception 'only an admin can set the company''s bot' using errcode = '42501';
  end if;
  if v_url !~ '^https://[^\s/?#@]+(/[^\s]*)?$' or length(v_url) > 2000 then
    raise exception 'the bot''s address must be an https URL' using errcode = '22023';
  end if;
  if v_key is not null and not agent_key_valid(v_key) then
    raise exception 'the bot''s key must be 16 to 512 characters with no spaces' using errcode = '22023';
  end if;
  v_secret := coalesce(v_key, new_agent_secret());
  select d.url into before_url from agent_destinations d where d.org_id = my_org and d.channel = 'grok_bot_webhook';
  insert into agent_destinations (org_id, channel, url, secret, enabled, verified_at, created_by_actor_id)
  values (my_org, 'grok_bot_webhook', v_url, v_secret, true, null, me)
  on conflict (org_id, channel) do update set
    url = excluded.url, secret = excluded.secret, enabled = true, verified_at = null, updated_at = now();
  insert into audit_log (org_id, actor_id, source, action, entity, before, after)
  values (my_org, me, 'dashboard', 'agent_destination.set', 'agent_destinations',
    case when before_url is null then null else jsonb_build_object('url', before_url) end,
    jsonb_build_object('url', v_url, 'key', case when v_key is null then 'generated' else 'provided' end));
  return case when v_key is null then v_secret else null end;
end;
$_$;


--
-- Name: client_set_mailbox_sync(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_set_mailbox_sync(p_on boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := current_actor_id();
begin
  if me is null then
    raise exception 'not a signed-in member' using errcode = '42501';
  end if;
  if p_on then
    delete from mailbox_sync_optouts where actor_id = me;
  else
    insert into mailbox_sync_optouts (actor_id, org_id) values (me, current_org_id()) on conflict (actor_id) do nothing;
  end if;
end;
$$;


--
-- Name: tacit_org_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tacit_org_id() RETURNS uuid
    LANGUAGE sql IMMUTABLE
    AS $$ select '7ac17000-0000-4000-8000-000000000001'::uuid $$;


--
-- Name: connector_add_person(text, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connector_add_person(p_name text, p_email text, p_linkedin_url text DEFAULT NULL::text, p_showcase_links text DEFAULT NULL::text, p_org_id uuid DEFAULT public.tacit_org_id()) RETURNS TABLE(candidate_id uuid, created boolean)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_email text := lower(btrim(p_email));
  found uuid;
begin
  perform pg_advisory_xact_lock(hashtextextended('connector-person-email:' || p_org_id || ':' || v_email, 0));
  select pi.person_id into found
  from person_identifiers pi
  where pi.org_id = p_org_id and pi.kind = 'email' and pi.value = v_email;
  if found is null then
    select p.id into found
    from people p
    where p.org_id = p_org_id and lower(p.email) = v_email
    order by p.created_at
    limit 1;
  end if;
  if found is not null then
    return query select found, false;
    return;
  end if;
  -- people_attach_identifiers_ins indexes the address in person_identifiers.
  return query
    insert into people (display_name, email, linkedin_url, showcase_links, org_id)
    values (p_name, v_email, p_linkedin_url, p_showcase_links, p_org_id)
    returning id, true;
end;
$$;


--
-- Name: current_access_level(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_access_level() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select a.access_level
  from actors a
  join orgs o on o.id = a.org_id
  where a.auth_subject = auth.jwt() ->> 'sub'
    and a.archived_at is null
    and o.workos_org_id = auth.jwt() ->> 'org_id'
$$;


--
-- Name: current_actor_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_actor_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select a.id
  from actors a
  join orgs o on o.id = a.org_id
  where a.auth_subject = auth.jwt() ->> 'sub'
    and a.archived_at is null
    and o.workos_org_id = auth.jwt() ->> 'org_id'
$$;


--
-- Name: current_org_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_org_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select a.org_id
  from actors a
  join orgs o on o.id = a.org_id
  where a.auth_subject = auth.jwt() ->> 'sub'
    and a.archived_at is null
    and o.workos_org_id = auth.jwt() ->> 'org_id'
$$;


--
-- Name: custom_field_options_validate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.custom_field_options_validate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'UPDATE' and new.field_id <> old.field_id then
    raise exception 'an option stays on its field' using errcode = '22023';
  end if;
  if not exists (select 1 from custom_fields f
                 where f.id = new.field_id and f.org_id = new.org_id
                   and f.field_type in ('single_select', 'multi_select')) then
    raise exception 'only a single_select or multi_select field has options' using errcode = '22023';
  end if;
  return new;
end;
$$;


--
-- Name: custom_field_values_validate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.custom_field_values_validate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  f custom_fields%rowtype;
  v jsonb := new.value;
  kept jsonb := case when tg_op = 'UPDATE' then old.value end;
  opt text;
  s text;
  offer_status text;
begin
  if tg_op = 'UPDATE' then
    if new.field_id <> old.field_id or new.org_id <> old.org_id
       or new.person_id is distinct from old.person_id or new.role_id is distinct from old.role_id
       or new.offer_id is distinct from old.offer_id then
      raise exception 'a value stays on its field and its object' using errcode = '22023';
    end if;
    new.created_at := old.created_at;
    -- The value did not change: keep the stamps, except the actor FK nulling updated_by.
    if new.value = old.value then
      new.updated_by_actor_id := case when new.updated_by_actor_id is null then null else old.updated_by_actor_id end;
      new.updated_at := old.updated_at;
      return new;
    end if;
  end if;

  select * into f from custom_fields where id = new.field_id and org_id = new.org_id;
  if not found then
    raise exception 'no such field' using errcode = '22023';
  end if;
  if (f.object = 'candidate' and new.person_id is null) or (f.object = 'job' and new.role_id is null)
     or (f.object = 'offer' and new.offer_id is null) then
    raise exception 'that field is for a %', f.object using errcode = '22023';
  end if;
  if f.archived_at is not null then
    raise exception 'that field is archived and takes no new value' using errcode = '22023';
  end if;
  if new.offer_id is not null then
    select o.status into offer_status from offers o where o.id = new.offer_id;
    if offer_status is distinct from 'draft' then
      raise exception 'only a draft offer''s fields change: withdraw it and draft a new one' using errcode = '22023';
    end if;
  end if;

  case f.field_type
    when 'short_text', 'long_text', 'url', 'date' then
      if jsonb_typeof(v) <> 'string' then
        raise exception 'a % value is a string', f.field_type using errcode = '22023';
      end if;
      s := v #>> '{}';
      if s <> btrim(s) or length(s) = 0 then
        raise exception 'a % value is trimmed and not empty', f.field_type using errcode = '22023';
      end if;
      if f.field_type = 'short_text' and length(s) > 255 then
        raise exception 'a short_text value is at most 255 characters' using errcode = '22023';
      elsif f.field_type = 'long_text' and length(s) > 10000 then
        raise exception 'a long_text value is at most 10000 characters' using errcode = '22023';
      elsif f.field_type = 'url' and (length(s) > 2000 or s !~* '^https?://[^[:space:]]+$') then
        raise exception 'a url value is an http or https address of at most 2000 characters' using errcode = '22023';
      elsif f.field_type = 'date' then
        if s !~ '^\d{4}-\d{2}-\d{2}$' then
          raise exception 'a date value is YYYY-MM-DD' using errcode = '22023';
        end if;
        begin
          perform s::date;
        exception when others then
          raise exception 'a date value is a real date' using errcode = '22023';
        end;
      end if;
    when 'number' then
      if jsonb_typeof(v) <> 'number' then
        raise exception 'a number value is a number' using errcode = '22023';
      end if;
      if abs(v::text::numeric) >= 1e15 then
        raise exception 'a number value is below a quadrillion' using errcode = '22023';
      end if;
    when 'yes_no' then
      if jsonb_typeof(v) <> 'boolean' then
        raise exception 'a yes_no value is true or false' using errcode = '22023';
      end if;
    when 'single_select', 'multi_select' then
      if f.field_type = 'single_select' then
        if jsonb_typeof(v) <> 'string' then
          raise exception 'a single_select value is one option id' using errcode = '22023';
        end if;
        v := jsonb_build_array(v);
        if kept is not null then kept := jsonb_build_array(kept); end if;
      else
        if jsonb_typeof(v) <> 'array' then
          raise exception 'a multi_select value is a list of option ids' using errcode = '22023';
        end if;
        if jsonb_array_length(v) not between 1 and 50 then
          raise exception 'a multi_select value is a list of one to 50 option ids' using errcode = '22023';
        end if;
        if (select count(distinct e) from jsonb_array_elements(v) e) <> jsonb_array_length(v) then
          raise exception 'a multi_select value names each option once' using errcode = '22023';
        end if;
      end if;
      for opt in select e from jsonb_array_elements_text(v) e loop
        -- An option archived after it was chosen stays; a new choice must be live.
        if not exists (
          select 1 from custom_field_options o
          where o.field_id = f.id and o.id::text = opt
            and (o.archived_at is null or (kept is not null and kept ? opt))
        ) then
          raise exception 'that is not a live option of this field' using errcode = '22023';
        end if;
      end loop;
  end case;

  new.updated_by_actor_id := coalesce(current_actor_id(), new.updated_by_actor_id);
  new.updated_at := now();
  return new;
end;
$_$;


--
-- Name: custom_fields_validate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.custom_fields_validate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.object <> old.object or new.field_type <> old.field_type or new.org_id <> old.org_id then
    raise exception 'a field keeps its object and type: archive it and make another' using errcode = '22023';
  end if;
  new.updated_at := now();
  return new;
end;
$$;


--
-- Name: decide_approval(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decide_approval(p_request uuid, p_approve boolean, p_reason text DEFAULT NULL::text) RETURNS TABLE(request_status text, waiting_step smallint, outcome text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := current_actor_id();
  v_reason text := nullif(btrim(p_reason), '');
  v_req approval_requests%rowtype;
  v_next smallint;
begin
  if me is null then
    raise exception 'not a signed-in member' using errcode = '42501';
  end if;
  if p_approve is null then
    raise exception 'approve or reject' using errcode = '22023';
  end if;
  if v_reason is not null and length(v_reason) > 2000 then
    raise exception 'a reason is at most 2000 characters' using errcode = '22023';
  end if;
  if not p_approve and v_reason is null then
    raise exception 'a rejection needs a reason' using errcode = '22023';
  end if;

  select * into v_req from approval_requests r where r.id = p_request and r.org_id = current_org_id() for update;
  if not found then
    raise exception 'no such approval request' using errcode = '22023';
  end if;
  if v_req.status <> 'pending' then
    return query select v_req.status, v_req.current_step, 'not_pending'::text;
    return;
  end if;
  if not exists (
    select 1 from approval_flow_approvers a join approval_flows f on f.id = a.flow_id
    where f.role_id = v_req.role_id and f.kind = v_req.kind and a.step = v_req.current_step and a.actor_id = me
  ) then
    raise exception 'you are not an approver at the step this request waits on' using errcode = '42501';
  end if;

  insert into approval_decisions (org_id, request_id, step, actor_id, decision, reason)
  values (v_req.org_id, v_req.id, v_req.current_step, me, case when p_approve then 'approved' else 'rejected' end, v_reason);

  if not p_approve then
    update approval_requests set status = 'rejected', resolved_at = now(), current_step = null where id = v_req.id;
    return query select 'rejected'::text, null::smallint, 'rejected'::text;
    return;
  end if;

  select min(a.step) into v_next
  from approval_flow_approvers a join approval_flows f on f.id = a.flow_id
  where f.role_id = v_req.role_id and f.kind = v_req.kind and a.step > v_req.current_step;
  if v_next is null then
    update approval_requests set status = 'approved', resolved_at = now(), current_step = null where id = v_req.id;
    return query select 'approved'::text, null::smallint, 'approved'::text;
  else
    update approval_requests set current_step = v_next where id = v_req.id;
    return query select 'pending'::text, v_next, 'advanced'::text;
  end if;
end;
$$;


--
-- Name: department_members_validate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.department_members_validate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.org_id <> old.org_id or new.department_id <> old.department_id or new.actor_id <> old.actor_id then
    raise exception 'a membership stays with its department and member' using errcode = '22023';
  end if;
  return new;
end;
$$;


--
-- Name: departments_validate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.departments_validate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.parent_id is null then
    return new;
  end if;
  if new.parent_id = new.id or exists (
    with recursive up (id, parent_id) as (
      select d.id, d.parent_id from departments d where d.id = new.parent_id
      union
      select d.id, d.parent_id from departments d join up on d.id = up.parent_id
    )
    select 1 from up where up.id = new.id
  ) then
    raise exception 'a department cannot sit inside itself' using errcode = '22023';
  end if;
  return new;
end;
$$;


--
-- Name: email_templates_validate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.email_templates_validate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'UPDATE' then
    if new.org_id <> old.org_id or new.created_at <> old.created_at
       or (new.created_by_actor_id is distinct from old.created_by_actor_id and new.created_by_actor_id is not null) then
      raise exception 'a template stays who made it, where it was made' using errcode = '22023';
    end if;
  end if;
  new.updated_at := now();
  return new;
end;
$$;


--
-- Name: hiring_team_sync_access(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hiring_team_sync_access() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'DELETE' then
    -- The job or the actor may be going with it; then there is nothing to keep in step.
    if exists (select 1 from roles where id = old.role_id) and exists (select 1 from actors where id = old.actor_id) then
      perform sync_job_access(old.role_id, old.actor_id);
    end if;
    return old;
  end if;
  perform sync_job_access(new.role_id, new.actor_id);
  return new;
end;
$$;


--
-- Name: home_targets_validate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.home_targets_validate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'UPDATE' and (new.org_id <> old.org_id or new.metric <> old.metric) then
    raise exception 'a target stays with its org and metric' using errcode = '22023';
  end if;
  new.updated_at := now();
  return new;
end;
$$;


--
-- Name: interview_feedback_ratings_validate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.interview_feedback_ratings_validate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  job uuid;
  attr scorecard_attributes%rowtype;
begin
  if tg_op = 'UPDATE' then
    if new.feedback_id <> old.feedback_id or new.attribute_id <> old.attribute_id or new.org_id <> old.org_id then
      raise exception 'a rating stays on its feedback and attribute' using errcode = '22023';
    end if;
    return new;
  end if;
  select a.role_id into job
  from interview_feedback f
  join interviews i on i.id = f.interview_id
  join applications a on a.id = i.application_id
  where f.id = new.feedback_id and f.org_id = new.org_id;
  select s.* into attr from scorecard_attributes s where s.id = new.attribute_id and s.org_id = new.org_id;
  if attr.id is null or job is null or attr.role_id <> job then
    raise exception 'that attribute is not on this interview''s job' using errcode = '22023';
  end if;
  if attr.archived_at is not null then
    raise exception 'that attribute is archived' using errcode = '22023';
  end if;
  return new;
end;
$$;


--
-- Name: interview_processes_validate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.interview_processes_validate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'UPDATE' and new.org_id <> old.org_id then
    raise exception 'a process stays with its org' using errcode = '22023';
  end if;
  if jsonb_typeof(new.graph) is distinct from 'object'
     or jsonb_typeof(new.graph -> 'nodes') is distinct from 'array'
     or jsonb_typeof(new.graph -> 'edges') is distinct from 'array' then
    raise exception 'a graph is an object with a nodes array and an edges array' using errcode = '22023';
  end if;
  if octet_length(new.graph::text) > 262144 then
    raise exception 'a graph is at most 256 KiB' using errcode = '22023';
  end if;
  if tg_op = 'UPDATE' and new.updated_by_actor_id is null and old.updated_by_actor_id is not null then
    return new;
  end if;
  new.updated_by_actor_id := coalesce(current_actor_id(), new.updated_by_actor_id);
  new.updated_at := now();
  return new;
end;
$$;


--
-- Name: interview_types_validate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.interview_types_validate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'UPDATE' and (new.org_id <> old.org_id or new.id <> old.id) then
    raise exception 'an interview type stays with its org' using errcode = '22023';
  end if;
  new.updated_at := now();
  return new;
end;
$$;


--
-- Name: interviewer_interview_types_validate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.interviewer_interview_types_validate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.org_id <> old.org_id or new.actor_id <> old.actor_id or new.type_id <> old.type_id then
