  return new;
end;
$$;


--
-- Name: interviewer_profiles_validate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.interviewer_profiles_validate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
declare
  edge constant text := '[[:cntrl:] \u0085 ­  -‏ -  -⁯　﻿]';
  inline constant text := '[[:cntrl:]\u0085 -‮⁦-⁩]';
  area text;
  folded text;
  seen text[] := '{}';
begin
  if tg_op = 'UPDATE' and (new.actor_id <> old.actor_id or new.org_id <> old.org_id) then
    raise exception 'a profile stays with its member' using errcode = '22023';
  end if;
  if cardinality(new.focus_areas) > 20 then
    raise exception 'at most 20 focus areas' using errcode = '23514';
  end if;
  foreach area in array coalesce(new.focus_areas, '{}') loop
    if area is null or length(area) not between 1 and 60
       or area ~ ('^' || edge) or area ~ (edge || '$') or area ~ inline then
      raise exception 'a focus area is one trimmed line of 1 to 60 characters' using errcode = '22023';
    end if;
    folded := normalize(lower(area), nfc);
    if folded = any (seen) then
      raise exception 'a focus area appears twice' using errcode = '22023';
    end if;
    seen := seen || folded;
  end loop;
  new.updated_at := now();
  return new;
end;
$_$;


--
-- Name: interviews_calendar_validate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.interviews_calendar_validate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  me uuid := current_actor_id();
  holder_changed boolean := tg_op = 'INSERT' or new.calendar_actor_id is distinct from old.calendar_actor_id;
  event_changed boolean := tg_op = 'INSERT' or new.google_event_id is distinct from old.google_event_id or new.id <> old.id;
begin
  if me is null or new.calendar_actor_id = me or not (holder_changed or event_changed) then
    return new;
  end if;
  if new.calendar_actor_id is null then
    if event_changed and new.google_event_id is not null then
      raise exception 'a calendar event goes on your own calendar' using errcode = '42501';
    end if;
    return new;
  end if;
  -- Someone else's calendar: one of the interview's interviewers, holding only Tacit's event for it.
  if holder_changed and not (new.calendar_actor_id = any (new.interviewer_actor_ids)) then
    raise exception 'an interview''s calendar is the booker''s own or an interviewer''s' using errcode = '42501';
  end if;
  if new.google_event_id is not null
     and (new.google_event_id <> replace(new.id::text, '-', '') or not (new.calendar_actor_id = any (new.interviewer_actor_ids))) then
    raise exception 'a calendar event on someone else''s calendar is the one Tacit made for the interview' using errcode = '42501';
  end if;
  return new;
end;
$$;


--
-- Name: interviews_candidate(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.interviews_candidate(p_person uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from interviews i join applications a on a.id = i.application_id
    where a.person_id = p_person
      and i.org_id = (select current_org_id())
      and (select current_actor_id()) = any (i.interviewer_actor_ids)
  )
$$;


--
-- Name: invite_org_member(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invite_org_member(p_email text, p_display_name text, p_access_level text) RETURNS TABLE(actor_id uuid, resent boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  me uuid := current_actor_id();
  my_org uuid := current_org_id();
  e text := lower(regexp_replace(coalesce(p_email, ''), '^\s+|\s+$', '', 'g'));
  n text := regexp_replace(coalesce(p_display_name, ''), '^\s+|\s+$', '', 'g');
  o record;
  existing record;
  new_id uuid;
begin
  if me is null or current_access_level() is distinct from 'admin' then
    raise exception 'only an admin of the org may invite' using errcode = '42501';
  end if;
  if length(e) > 254 or e !~ '^[^\s@<>"'',;]+@[^\s@<>"'',;]+\.[^\s@<>"'',;]+$' then
    raise exception 'that is not an email address' using errcode = '22023';
  end if;
  if n = '' or length(n) > 120 then
    raise exception 'the person needs a name of at most 120 characters' using errcode = '22023';
  end if;
  if p_access_level is null or p_access_level not in ('limited', 'elevated', 'admin') then
    raise exception 'unknown access level' using errcode = '22023';
  end if;

  select id, slug, kind, workos_org_id into o from orgs where id = my_org;
  -- Tacit's own teammates are never invited this way.
  if o.kind is distinct from 'client' or o.workos_org_id is null then
    raise exception 'only a client org takes invitations' using errcode = '42501';
  end if;

  select a.id, a.auth_subject, a.archived_at into existing
  from actors a where a.org_id = my_org and lower(a.email) = e;
  if found then
    if existing.auth_subject is not null or existing.archived_at is not null then
      raise exception 'that address is already a member of the org' using errcode = '23505';
    end if;
    return query select existing.id, true;
    return;
  end if;

  insert into actors (org_id, slug, display_name, email, access_level)
  values (my_org, 'c-' || o.slug || '-' || substr(md5(gen_random_uuid()::text), 1, 8), n, e, p_access_level)
  returning id into new_id;
  return query select new_id, false;
end;
$_$;


--
-- Name: job_access_raise_level(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.job_access_raise_level() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update actors set access_level = 'elevated' where id = new.actor_id and access_level = 'limited';
  return new;
end;
$$;


--
-- Name: job_board_department(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.job_board_department(p_org uuid, p_department uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with recursive up as (
    select d.name, d.parent_id, d.archived_at, 0 as depth
    from departments d
    where d.org_id = p_org and d.id = p_department
    union all
    select d.name, d.parent_id, d.archived_at, up.depth + 1
    from departments d
    join up on d.org_id = p_org and d.id = up.parent_id
    where up.depth < 32
  )
  select up.name from up where up.archived_at is null order by up.depth desc limit 1
$$;


--
-- Name: job_board_public(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.job_board_public(p_org text) RETURNS TABLE(company text, slug text, title text, location text, department text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select o.name, jp.slug, jp.title, jp.location, public.job_board_department(jp.org_id, r.department_id)
  from orgs o
  join job_posts jp on jp.org_id = o.id
  join roles r on r.org_id = jp.org_id and r.id = jp.role_id
  where o.slug = p_org
    and o.kind = 'client'
    and jp.status = 'live'
    and r.status = 'open'
  order by jp.title, jp.slug
$$;


--
-- Name: job_post_page(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.job_post_page(p_slug text) RETURNS TABLE(title text, description text, location text, company text, questions jsonb, org_slug text, department text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
  select
    jp.title, jp.description, jp.location, o.name, jp.questions,
    case when o.kind = 'client' then o.slug end,
    public.job_board_department(jp.org_id, r.department_id)
  from job_posts jp
  join roles r on r.org_id = jp.org_id and r.id = jp.role_id
  join orgs o on o.id = jp.org_id
  where p_slug ~ '^[a-z0-9]{24,64}$'
    and jp.slug = p_slug
    and jp.status = 'live'
    and r.status = 'open'
$_$;


--
-- Name: job_post_public(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.job_post_public(p_slug text) RETURNS TABLE(title text, description text, location text, company text, questions jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
  select jp.title, jp.description, jp.location, o.name, jp.questions
  from job_posts jp
  join roles r on r.org_id = jp.org_id and r.id = jp.role_id
  join orgs o on o.id = jp.org_id
  where p_slug ~ '^[a-z0-9]{24,64}$'
    and jp.slug = p_slug
    and jp.status = 'live'
    and r.status = 'open'
$_$;


--
-- Name: job_posts_validate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.job_posts_validate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
declare
  q jsonb;
  opt jsonb;
  ids text[] := '{}';
  opts text[];
  qid text;
  qtype text;
  qlabel text;
begin
  if tg_op = 'INSERT' then
    if new.status <> 'draft' then
      raise exception 'a job post starts as a draft' using errcode = '22023';
    end if;
    new.published_at := null;
    new.closed_at := null;
  else
    if new.slug <> old.slug or new.role_id <> old.role_id or new.org_id <> old.org_id or new.created_at <> old.created_at
       or (new.created_by_actor_id is distinct from old.created_by_actor_id and new.created_by_actor_id is not null) then
      raise exception 'a job post keeps its job, its link and its author' using errcode = '22023';
    end if;
    new.published_at := old.published_at;
    new.closed_at := old.closed_at;
    if new.status <> old.status then
      if not ((old.status = 'draft' and new.status in ('live', 'closed'))
              or (old.status = 'live' and new.status = 'closed')
              or (old.status = 'closed' and new.status = 'live')) then
        raise exception 'a job post cannot go from % to %', old.status, new.status using errcode = '22023';
      end if;
      if new.status = 'live' then
        new.published_at := coalesce(old.published_at, now());
        new.closed_at := null;
      else
        new.closed_at := now();
      end if;
    end if;
    new.updated_at := now();
  end if;

  -- Each check its own if: an or is not evaluated in order, and the length of a non-array raises.
  if jsonb_typeof(new.questions) is distinct from 'array' then
    raise exception 'questions are a list' using errcode = '22023';
  end if;
  if jsonb_array_length(new.questions) > 40 then
    raise exception 'a job post asks at most 40 questions' using errcode = '22023';
  end if;
  for q in select value from jsonb_array_elements(new.questions) loop
    if jsonb_typeof(q) <> 'object' then
      raise exception 'a question is an object' using errcode = '22023';
    end if;
    if exists (select 1 from jsonb_object_keys(q) k where k not in ('id', 'type', 'label', 'required', 'options')) then
      raise exception 'a question has an id, a type, a label, required and (for select) options' using errcode = '22023';
    end if;
    if jsonb_typeof(q -> 'id') is distinct from 'string' or jsonb_typeof(q -> 'type') is distinct from 'string' then
      raise exception 'a question has an id and a type' using errcode = '22023';
    end if;
    qid := q ->> 'id';
    qtype := q ->> 'type';
    if qtype in ('name', 'email', 'phone', 'linkedin', 'resume') then
      if qid <> qtype then
        raise exception 'a built-in question''s id is its type' using errcode = '22023';
      end if;
    elsif qtype in ('short_text', 'long_text', 'yes_no', 'select') then
      if qid !~ '^q_[a-z0-9]{4,32}$' then
        raise exception 'a custom question''s id is q_ and 4 to 32 lowercase letters or digits' using errcode = '22023';
      end if;
    else
      raise exception 'unknown question type' using errcode = '22023';
    end if;
    if qid = any (ids) then
      raise exception 'a question appears once' using errcode = '22023';
    end if;
    ids := ids || qid;
    qlabel := q ->> 'label';
    if jsonb_typeof(q -> 'label') is distinct from 'string' or qlabel <> btrim(qlabel) or length(qlabel) not between 1 and 300 then
      raise exception 'a question''s label is 1 to 300 characters, trimmed' using errcode = '22023';
    end if;
    if jsonb_typeof(q -> 'required') is distinct from 'boolean' then
      raise exception 'a question''s required is true or false' using errcode = '22023';
    end if;
    if qtype in ('name', 'email') and (q ->> 'required')::boolean is not true then
      raise exception 'name and email are always required' using errcode = '22023';
    end if;
    if qtype = 'select' then
      if jsonb_typeof(q -> 'options') is distinct from 'array' then
        raise exception 'a select question has 2 to 50 options' using errcode = '22023';
      end if;
      if jsonb_array_length(q -> 'options') not between 2 and 50 then
        raise exception 'a select question has 2 to 50 options' using errcode = '22023';
      end if;
      opts := '{}';
      for opt in select value from jsonb_array_elements(q -> 'options') loop
        if jsonb_typeof(opt) <> 'string' or (opt #>> '{}') <> btrim(opt #>> '{}')
           or length(opt #>> '{}') not between 1 and 200 or (opt #>> '{}') = any (opts) then
          raise exception 'a select question''s options are distinct, trimmed and 1 to 200 characters' using errcode = '22023';
        end if;
        opts := opts || (opt #>> '{}');
      end loop;
    elsif q ? 'options' then
      raise exception 'only a select question has options' using errcode = '22023';
    end if;
  end loop;
  if not ('name' = any (ids) and 'email' = any (ids)) then
    raise exception 'a job post always asks for a name and an email' using errcode = '22023';
  end if;
  return new;
end;
$_$;


--
-- Name: merge_people(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merge_people(primary_id uuid, duplicate_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  dup people%rowtype;
  prim_funnel text;
  dup_funnel_wins boolean;
  funnel_order constant text[] := array['new','met','interviewing','ready','in_process','placed'];
begin
  if primary_id = duplicate_id then
    raise exception 'merge_people: primary and duplicate are the same row (%)', primary_id;
  end if;

  select * into dup from people where id = duplicate_id for update;
  if not found then
    raise exception 'merge_people: duplicate row % not found', duplicate_id;
  end if;

  select funnel_stage into prim_funnel from people where id = primary_id for update;
  if not found then
    raise exception 'merge_people: primary row % not found', primary_id;
  end if;

  -- Tenancy: two orgs' candidates are never one person, even when every
  -- handle matches. The same-org composite FKs on the child tables would
  -- also refuse the reparent below; this says so first, and covers a
  -- duplicate with no children at all, whose columns would otherwise fold
  -- straight into another org's row.
  if dup.org_id is distinct from (select p.org_id from people p where p.id = primary_id) then
    raise exception 'merge_people: % and % belong to different orgs', primary_id, duplicate_id;
  end if;

  -- tacit_internal (the apps' role, 20261012240000) merges Tacit's people only.
  -- This function is security definer, so RLS does not stop it; the caller's
  -- JWT role does.
  if coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role', '') = 'tacit_internal'
     and dup.org_id is distinct from tacit_org_id() then
    raise exception 'merge_people: % is not in Tacit''s org', duplicate_id;
  end if;

  -- The Tacit funnel stage: the survivor keeps whichever row is further
  -- along. An outcome (passed / inactive) on the primary is a decision the
  -- team made about the row they kept, so it stands; an outcome on the
  -- duplicate only carries over when the primary was never worked ('new').
  dup_funnel_wins := case
    when prim_funnel in ('passed', 'inactive') then false
    when dup.funnel_stage in ('passed', 'inactive') then prim_funnel = 'new'
    else array_position(funnel_order, dup.funnel_stage) > array_position(funnel_order, prim_funnel)
  end;

  -- Label the snapshot the profile-column fold below will trigger
  -- (people_snapshot_before_change). Over an RPC the tacit.* GUCs are otherwise
  -- unset, so without this the merge-time snapshot is indistinguishable from any
  -- unlabelled write. 'identity_link' is an allowed reason.
  perform set_config('tacit.reason', 'identity_link', true);

  -- Actor guard: refuse when BOTH rows are a team-member identity; repoint when
  -- only the duplicate is.
  if exists (select 1 from actors where person_id = duplicate_id) then
    if exists (select 1 from actors where person_id = primary_id) then
      raise exception 'merge_people: both rows have linked actors (%, %)', primary_id, duplicate_id;
    end if;
    update actors set person_id = primary_id where person_id = duplicate_id;
  end if;

  -- Fold null-fill primary <- duplicate (never overwrite a non-null primary
  -- value): EVERY nullable column that carries signal -- identity, the profile
  -- columns extraction/enrichment write, AND the /apply signup + assignment
  -- columns -- so the survivor keeps everything the loser had that it lacked.
  -- The realistic loss without this: a candidate texts first (phone row), then
  -- signs up via /apply (email row with essays/verticals/stage); the phone row
  -- is usually the merge target, so its /apply data would vanish from the live
  -- row. auth_user_id is unique, so it's folded AFTER the delete (below) to
  -- avoid a transient two-rows-same-value collision. array/jsonb columns use a
  -- cardinality guard, not coalesce: extraction writes []/{} as "evidence"
  -- (packages/core CLAUDE.md), and an empty [] is not-null, so plain coalesce
  -- would let an evidence-free [] block the loser's real values.
  -- The profile-column change trips people_snapshot_before_change (labelled above).
  update people p set
    display_name     = coalesce(p.display_name, dup.display_name),
    email            = coalesce(p.email, dup.email),
    phone            = coalesce(p.phone, dup.phone),
    imessage_handle  = coalesce(p.imessage_handle, dup.imessage_handle),
    linkedin_url     = coalesce(p.linkedin_url, dup.linkedin_url),
    x_handle         = coalesce(p.x_handle, dup.x_handle),
    x_user_id        = coalesce(p.x_user_id, dup.x_user_id),
    github_username  = coalesce(p.github_username, dup.github_username),
    current_title    = coalesce(p.current_title, dup.current_title),
    current_company  = coalesce(p.current_company, dup.current_company),
    location         = coalesce(p.location, dup.location),
    summary          = coalesce(p.summary, dup.summary),
    past             = coalesce(p.past, dup.past),
    present          = coalesce(p.present, dup.present),
    future           = coalesce(p.future, dup.future),
    profile_updated_at = coalesce(p.profile_updated_at, dup.profile_updated_at),
    referred_by      = coalesce(p.referred_by, dup.referred_by),
    stage            = coalesce(p.stage, dup.stage),
    unique_about     = coalesce(p.unique_about, dup.unique_about),
    company_specific = coalesce(p.company_specific, dup.company_specific),
    writeup          = coalesce(p.writeup, dup.writeup),
    rubric_id        = coalesce(p.rubric_id, dup.rubric_id),
    admired_people   = coalesce(p.admired_people, dup.admired_people),
    deep_concept     = coalesce(p.deep_concept, dup.deep_concept),
    showcase_links   = coalesce(p.showcase_links, dup.showcase_links),
    based_in         = coalesce(p.based_in, dup.based_in),
    games_played     = coalesce(p.games_played, dup.games_played),
    applicant_phone  = coalesce(p.applicant_phone, dup.applicant_phone),
    applicant_status = coalesce(p.applicant_status, dup.applicant_status),
    funnel_stage     = case when dup_funnel_wins then dup.funnel_stage else p.funnel_stage end,
    funnel_stage_at  = case when dup_funnel_wins then dup.funnel_stage_at else p.funnel_stage_at end,
    portal_token_rotated_at = coalesce(p.portal_token_rotated_at, dup.portal_token_rotated_at),
    willing_to_work = case when p.willing_to_work is not null and cardinality(p.willing_to_work) > 0
                           then p.willing_to_work else dup.willing_to_work end,
    education = case when p.education is not null and jsonb_array_length(p.education) > 0
                    then p.education else dup.education end,
    skills = case when p.skills is not null and cardinality(p.skills) > 0
                  then p.skills else dup.skills end,
    interested_verticals = case when p.interested_verticals is not null and cardinality(p.interested_verticals) > 0
                                then p.interested_verticals else dup.interested_verticals end,
    interested_roles = case when p.interested_roles is not null and cardinality(p.interested_roles) > 0
                            then p.interested_roles else dup.interested_roles end,
    healthcare_interests = case when p.healthcare_interests is not null and cardinality(p.healthcare_interests) > 0
                                then p.healthcare_interests else dup.healthcare_interests end
  where p.id = primary_id;

  -- Free reparents (no unique that can collide on person_id).
  update person_funnel_events set person_id = primary_id where person_id = duplicate_id;
  update person_notes      set person_id = primary_id where person_id = duplicate_id;
  -- candidate_messages: the email history moves with the person (connector).
  update candidate_messages set person_id = primary_id where person_id = duplicate_id;
  -- interviews: when both rows are in the same role's pipeline, the duplicate's
  -- application is the one dropped below; its interviews move to the survivor's.
  -- 20261016160000: only onto the survivor's live application.
  update interviews i set application_id = q.id
    from applications a
    join applications q on q.role_id = a.role_id and q.person_id = primary_id and q.merged_into_id is null
    where i.application_id = a.id and a.person_id = duplicate_id;
  -- 20261019180000: Tacit's own interviews hang off the person. 20261020210000:
  -- a person may have several, one per start time, so only a duplicate's
  -- interview at the same start as one of the primary's is cancelled (the
  -- primary's stands), not dropped.
  update interviews i set status = 'cancelled', updated_at = now()
    where i.person_id = duplicate_id and i.status = 'scheduled'
      and exists (select 1 from interviews q
                  where q.person_id = primary_id and q.status = 'scheduled' and q.starts_at = i.starts_at);
  update interviews set person_id = primary_id where person_id = duplicate_id;
  update person_snapshots  set person_id = primary_id where person_id = duplicate_id;
  update update_proposals  set person_id = primary_id where person_id = duplicate_id;
  update enrichment_records set person_id = primary_id where person_id = duplicate_id;
  -- 20261016160000: files move (their storage path keeps the duplicate's id,
  -- which is still that row's own object), and a row a client merged into
  -- the duplicate follows it.
  update person_files      set person_id = primary_id where person_id = duplicate_id;
  update people            set merged_into_id = primary_id where merged_into_id = duplicate_id and id <> primary_id;

  -- 20261016160000: person_tags move unless the primary has that tag already.
  update person_tags t set person_id = primary_id
  where t.person_id = duplicate_id
    and not exists (select 1 from person_tags q where q.person_id = primary_id and q.tag_id = t.tag_id);

  -- transcript_entries: move only rows that won't collide on (person_id,source,source_ref).
  -- Colliding rows are byte-identical dupes -> left on duplicate, cascade-deleted below.
  update transcript_entries e set person_id = primary_id
  where e.person_id = duplicate_id
    and not exists (
      select 1 from transcript_entries q
      where q.person_id = primary_id and q.source = e.source and q.source_ref = e.source_ref
    );

  -- debriefs: same shape as transcript_entries. A collision on
  -- (person_id, note_id, actor_id) means the primary already has this actor's
  -- debrief for this meeting -- the duplicate's copy is the same logical
  -- answer filed against the doomed row, left behind and cascade-deleted.
  update debriefs d set person_id = primary_id
  where d.person_id = duplicate_id
    and not exists (
      select 1 from debriefs q
      where q.person_id = primary_id and q.note_id = d.note_id
        and q.actor_id is not distinct from d.actor_id
    );

  -- Mentions OF the duplicate become mentions of the primary (no unique to
  -- collide). Without this the delete below would set them null and the
  -- "mentioned by" trail on the survivor would quietly thin out.
  update debrief_mentions set mentioned_person_id = primary_id
  where mentioned_person_id = duplicate_id;

  -- applications: move unless the primary is already in that role's pipeline
  -- (unique (person_id, role_id)). On a collision the primary's row is the one
  -- the team has been working; the duplicate's is cascade-deleted below.
  -- 20261016160000: the unique counts live applications only, so a merged
  -- one always moves, and only a live one on the primary is a collision.
  update applications a set person_id = primary_id
  where a.person_id = duplicate_id
    and (a.merged_into_id is not null
         or not exists (
           select 1 from applications q
           where q.person_id = primary_id and q.role_id = a.role_id and q.merged_into_id is null
         ));

  -- enrichment_jobs: the partial unique index is on person_id where status in
  -- (pending,running) -- ONE active job per person, regardless of which active
  -- status. So a dup active job collides with ANY primary active job, not just
  -- one of the same status. Move a dup job unless it's active AND primary
  -- already has an active job; the leftover active dup job is redundant and
  -- cascade-deleted with the duplicate below.
  update enrichment_jobs j set person_id = primary_id
  where j.person_id = duplicate_id
    and not (
      j.status in ('pending','running')
      and exists (
        select 1 from enrichment_jobs k
        where k.person_id = primary_id and k.status in ('pending','running')
      )
    );

  -- person_identifiers: plain move. unique(kind,value) is GLOBAL, so primary and
  -- duplicate can never share an identifier -- the move never collides (a
  -- per-person "not exists" guard here would wrongly match each row against
  -- itself and move nothing).
  update person_identifiers set person_id = primary_id where person_id = duplicate_id;

  -- Belt-and-braces: any identity column primary just ABSORBED that isn't yet an
  -- identifier becomes one (canonicalized the same way the seed + normalizeIdentifier
  -- do). Covers all five kinds so a legacy row whose handle lost the seed's
  -- distinct-on tiebreak still gets indexed. Skip conflicts.
  insert into person_identifiers (person_id, kind, value)
  select primary_id, v.kind, v.value from (
    select 'email'::text as kind, lower(trim(p.email)) as value
      from people p where p.id = primary_id and p.email is not null and trim(p.email) <> ''
    union all
    select 'phone', tacit_canon_phone(p.phone)
      from people p where p.id = primary_id and tacit_canon_phone(p.phone) is not null
    union all
    select 'imessage',
           case when p.imessage_handle like '%@%' then lower(trim(p.imessage_handle))
                else tacit_canon_phone(p.imessage_handle) end
      from people p where p.id = primary_id and p.imessage_handle is not null and trim(p.imessage_handle) <> ''
    union all
    select 'x_handle', lower(ltrim(trim(p.x_handle), '@'))
      from people p where p.id = primary_id and p.x_handle is not null and trim(p.x_handle) <> ''
    union all
    select 'x_user_id', trim(p.x_user_id)
      from people p where p.id = primary_id and p.x_user_id is not null and trim(p.x_user_id) <> ''
  ) v
  where v.value is not null and v.value <> ''
  on conflict (org_id, kind, value) do nothing;

  -- Reparent the audit trail itself: people_merges.primary_id is ON DELETE
  -- CASCADE, so a chained merge (A<-B then C<-A) would cascade-delete the (A,B)
  -- audit row -- and B's snapshot with it -- when A is deleted below. Repoint
  -- any earlier merge that named the duplicate as its primary onto the new
  -- primary first, so no snapshot is ever lost.
  update people_merges m set primary_id = merge_people.primary_id
  where m.primary_id = merge_people.duplicate_id;

  -- Audit the whole duplicate row before deletion.
  insert into people_merges (primary_id, duplicate_id, duplicate_snapshot)
  values (primary_id, duplicate_id, to_jsonb(dup));

  -- Delete duplicate; cascade cleans every leftover child (colliding dupes).
  delete from people where id = duplicate_id;

  -- auth_user_id is UNIQUE, so it can only be folded once the duplicate row (and
  -- its value) is gone -- doing it in the pre-delete fold would transiently put
  -- the same value on two rows. dup is a value copy, so dup.auth_user_id survives.
  if dup.auth_user_id is not null then
    update people set auth_user_id = dup.auth_user_id
    where id = primary_id and auth_user_id is null;
  end if;

  -- portal_token_digest is UNIQUE too: folded post-delete like auth_user_id.
  -- NEWEST WINS, not null-fill (changed 20260911040000): the duplicate is by
  -- construction the newer row -- a fresh /apply submission whose token was
  -- JUST handed to the applicant in the portal redirect -- while the
  -- primary's older digest belongs to a link nobody may hold anymore (no
  -- confirmation emails since 2026-09-10). Keeping the old digest stranded
  -- the person on a portal page that died minutes later when the daemon
  -- merged their re-application. Same semantics as every rotation: the
  -- latest interaction holds the live link.
  if dup.portal_token_digest is not null then
    update people set portal_token_digest = dup.portal_token_digest,
                      portal_token_rotated_at = coalesce(dup.portal_token_rotated_at, portal_token_rotated_at)
    where id = primary_id;
  end if;

  return primary_id;
end;
$$;


--
-- Name: my_approvals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_approvals() RETURNS TABLE(request_id uuid, kind text, waiting_step smallint, steps integer, job_id uuid, job_title text, job_status text, offer_id uuid, application_id uuid, candidate_id uuid, candidate_name text, salary bigint, currency text, bonus text, equity text, start_date date, expires_on date, requested_by_actor_id uuid, requested_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select r.id, r.kind, r.current_step,
         (select count(distinct a2.step) from approval_flow_approvers a2 where a2.flow_id = f.id)::integer,
         ro.id, ro.title, ro.status,
         o.id, ap.id, p.id, p.display_name,
         o.salary, o.currency, o.bonus, o.equity, o.start_date, o.expires_on,
         r.requested_by_actor_id, r.created_at
  from approval_requests r
  join approval_flows f on f.role_id = r.role_id and f.kind = r.kind
  join approval_flow_approvers a on a.flow_id = f.id and a.step = r.current_step
                                 and a.actor_id = (select current_actor_id())
  join roles ro on ro.id = r.role_id
  left join offers o on o.id = r.offer_id
  left join applications ap on ap.id = o.application_id
  left join people p on p.id = ap.person_id
  where r.org_id = (select current_org_id()) and r.status = 'pending'
  order by r.created_at
$$;


--
-- Name: my_interview_candidates(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_interview_candidates() RETURNS TABLE(person_id uuid, display_name text, current_title text, current_company text, linkedin_url text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select distinct p.id, p.display_name, p.current_title, p.current_company, p.linkedin_url
  from interviews i
  join applications a on a.id = i.application_id
  join people p on p.id = a.person_id
  where i.org_id = (select current_org_id())
    and (select current_actor_id()) = any (i.interviewer_actor_ids)
$$;


--
-- Name: my_interviews(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_interviews() RETURNS TABLE(interview_id uuid, application_id uuid, person_id uuid, candidate_name text, job_id uuid, job_title text, starts_at timestamp with time zone, ends_at timestamp with time zone, status text, step text, location_or_link text, feedback_filed boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select i.id, a.id, p.id, p.display_name, r.id, r.title, i.starts_at, i.ends_at, i.status, i.step,
         i.location_or_link,
         exists (select 1 from interview_feedback f
                 where f.interview_id = i.id and f.interviewer_actor_id = (select current_actor_id()))
  from interviews i
  join applications a on a.id = i.application_id
  join people p on p.id = a.person_id
  join roles r on r.id = a.role_id
  where i.org_id = (select current_org_id())
    and (select current_actor_id()) = any (i.interviewer_actor_ids)
  order by i.starts_at
$$;


--
-- Name: new_agent_secret(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.new_agent_secret() RETURNS text
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$
  select 'tbs_' || encode(extensions.gen_random_bytes(32), 'hex')
$$;


--
-- Name: offers_follow_approvals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.offers_follow_approvals() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if old.status = 'draft' and new.status = 'extended' then
    update approval_requests set used_at = now()
    where offer_id = new.id and status = 'approved' and used_at is null;
  elsif new.status = 'withdrawn' and old.status <> 'withdrawn' then
    update approval_requests set status = 'cancelled', resolved_at = now(), current_step = null
    where offer_id = new.id and (status = 'pending' or (status = 'approved' and used_at is null));
  elsif new.status = 'draft' and (
       new.salary is distinct from old.salary or new.currency is distinct from old.currency
       or new.bonus is distinct from old.bonus or new.equity is distinct from old.equity
       or new.start_date is distinct from old.start_date or new.expires_on is distinct from old.expires_on) then
    update approval_requests set status = 'reset', resolved_at = now(), current_step = null
    where offer_id = new.id and (status = 'pending' or (status = 'approved' and used_at is null));
  end if;
  return null;
end;
$$;


--
-- Name: offers_validate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.offers_validate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.status <> 'draft' then
      raise exception 'an offer starts as a draft' using errcode = '22023';
    end if;
    new.extended_at := null;
    new.resolved_at := null;
    return new;
  end if;

  -- Deleting the actor who drafted it nulls created_by (the FK's set null),
  -- on a closed offer too.
  if new.created_by_actor_id is null
     and (to_jsonb(new) - 'created_by_actor_id') = (to_jsonb(old) - 'created_by_actor_id') then
    return new;
  end if;
  if new.application_id <> old.application_id or new.org_id <> old.org_id
     or new.created_by_actor_id is distinct from old.created_by_actor_id or new.created_at <> old.created_at then
    raise exception 'an offer stays on its application' using errcode = '22023';
  end if;
  if old.status in ('accepted', 'declined', 'withdrawn') then
    raise exception 'that offer is closed' using errcode = '22023';
  end if;
  if old.status <> 'draft' and (
       new.salary is distinct from old.salary or new.currency is distinct from old.currency
       or new.bonus is distinct from old.bonus or new.equity is distinct from old.equity
       or new.start_date is distinct from old.start_date or new.expires_on is distinct from old.expires_on) then
    raise exception 'only a draft offer''s terms change: withdraw it and draft a new one' using errcode = '22023';
  end if;

  new.extended_at := old.extended_at;
  new.resolved_at := old.resolved_at;
  if new.status <> old.status then
    if not ((old.status = 'draft' and new.status in ('extended', 'withdrawn'))
            or (old.status = 'extended' and new.status in ('accepted', 'declined', 'withdrawn'))) then
      raise exception 'an offer cannot go from % to %', old.status, new.status using errcode = '22023';
    end if;
    if new.status = 'extended' then
      new.extended_at := now();
    else
      new.resolved_at := now();
    end if;
  end if;
  new.updated_at := now();
  return new;
end;
$$;


--
-- Name: offers_validate_approval(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.offers_validate_approval() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_role uuid;
begin
  if not (old.status = 'draft' and new.status = 'extended') then
    return new;
  end if;
  select a.role_id into v_role from applications a where a.id = new.application_id;
  if not exists (
    select 1 from approval_flow_approvers a join approval_flows f on f.id = a.flow_id
    where f.role_id = v_role and f.kind = 'offer'
  ) then
    return new;
  end if;
  if new.salary is distinct from old.salary or new.currency is distinct from old.currency
     or new.bonus is distinct from old.bonus or new.equity is distinct from old.equity
     or new.start_date is distinct from old.start_date or new.expires_on is distinct from old.expires_on then
    raise exception 'this offer needs approval, so it is extended with the terms that were approved: save the new terms and have them approved first'
      using errcode = '22023';
  end if;
  if not exists (select 1 from approval_requests where offer_id = new.id and status = 'approved' and used_at is null) then
    if exists (select 1 from approval_requests where offer_id = new.id and status = 'pending') then
      raise exception 'this offer is still waiting on approval and cannot be extended yet' using errcode = '22023';
    end if;
    raise exception 'offers on this job need approval before they are extended, and this one is not approved' using errcode = '22023';
  end if;
  return new;
end;
$$;


--
-- Name: openings_validate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openings_validate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.status <> 'open' or new.filled_by_application_id is not null or new.close_reason is not null then
      raise exception 'an opening starts open' using errcode = '22023';
    end if;
    -- One numbering per job at a time, so two adds never take the same number.
    perform pg_advisory_xact_lock(hashtextextended('openings:' || new.role_id::text, 0));
    select coalesce(max(o.number), 0) + 1 into new.number from openings o where o.role_id = new.role_id;
    new.filled_at := null;
    new.closed_at := null;
    new.updated_at := now();
    return new;
  end if;

  -- Deleting the hired application or the actor who added it nulls the
  -- reference (the FKs' set null): let that through untouched.
  if (to_jsonb(new) - 'filled_by_application_id' - 'created_by_actor_id')
       = (to_jsonb(old) - 'filled_by_application_id' - 'created_by_actor_id')
     and (new.filled_by_application_id is null or new.filled_by_application_id = old.filled_by_application_id)
     and (new.created_by_actor_id is null or new.created_by_actor_id = old.created_by_actor_id) then
    return new;
  end if;
  if new.role_id <> old.role_id or new.org_id <> old.org_id or new.number <> old.number
     or new.created_at <> old.created_at or new.created_by_actor_id is distinct from old.created_by_actor_id then
    raise exception 'an opening stays on its job' using errcode = '22023';
  end if;

  new.filled_at := old.filled_at;
  new.closed_at := old.closed_at;
  if new.status <> old.status then
    if old.status = 'open' and new.status = 'closed' then
      if new.close_reason is null then
        raise exception 'closing an opening needs a reason' using errcode = '22023';
      end if;
      new.closed_at := now();
    elsif old.status = 'closed' and new.status = 'open' then
      new.close_reason := null;
      new.closed_at := null;
    elsif old.status = 'open' and new.status = 'filled' then
      if new.filled_by_application_id is null or not exists (
        select 1 from applications a
        where a.id = new.filled_by_application_id and a.role_id = new.role_id and a.stage = 'hired'
      ) then
        raise exception 'an opening is filled by someone hired into its job' using errcode = '22023';
      end if;
      new.filled_at := now();
    elsif old.status = 'filled' and new.status = 'open' then
      new.filled_by_application_id := null;
      new.filled_at := null;
    else
      raise exception 'an opening cannot go from % to %', old.status, new.status using errcode = '22023';
    end if;
  elsif new.filled_by_application_id is distinct from old.filled_by_application_id then
    raise exception 'who filled an opening changes only by filling or reopening it' using errcode = '22023';
  end if;
  if new.status <> 'closed' and new.close_reason is not null then
    raise exception 'a close reason is only for a closed opening' using errcode = '22023';
  end if;
  new.updated_at := now();
  return new;
end;
$$;


--
-- Name: org_brand_public(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.org_brand_public(p_org text) RETURNS TABLE(accent text, logo_url text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select o.brand_accent, o.brand_logo_url
  from orgs o
  where o.slug = p_org
    and o.kind = 'client'
    and exists (
      select 1
      from job_posts jp
      join roles r on r.org_id = jp.org_id and r.id = jp.role_id
      where jp.org_id = o.id and jp.status = 'live' and r.status = 'open'
    )
$$;


--
-- Name: org_id_set_by_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.org_id_set_by_trigger() RETURNS uuid
    LANGUAGE sql IMMUTABLE
    AS $$ select null::uuid $$;


--
-- Name: org_pending_invites(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.org_pending_invites() RETURNS TABLE(actor_id uuid, display_name text, email text, access_level text, invited_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select a.id, a.display_name, a.email, a.access_level, a.created_at
  from actors a
  where a.org_id = (select current_org_id())
    and (select current_access_level()) = 'admin'
    and a.auth_subject is null
    and a.archived_at is null
    and not a.tacit_agency
  order by a.created_at
$$;


--
-- Name: own_candidates_only(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.own_candidates_only(p_role uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce((select current_access_level()) <> 'admin', true)
    and coalesce((
      select ar.own_candidates_only
      from job_access ja join access_roles ar on ar.id = ja.access_role_id
      where ja.actor_id = (select current_actor_id()) and ja.role_id = p_role
    ), false)
$$;


--
-- Name: people_erase_bot_tasks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.people_erase_bot_tasks() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  erased uuid[];
begin
  with hit as (
    update bot_tasks t
    set steps = '[]'::jsonb,
        error = null,
        needs_you = false,
        waiting_on_person_id = null,
        waiting_channel = null,
        status = case when t.status in ('running', 'waiting', 'failed') then 'cancelled' else t.status end,
        updated_at = now()
    where t.waiting_on_person_id = new.id
       or t.application_id in (select a.id from applications a where a.person_id = new.id)
       or t.interview_id in (
         select i.id from interviews i left join applications a on a.id = i.application_id
         where new.id in (i.person_id, a.person_id))
    returning t.id
  )
  select coalesce(array_agg(id), '{}') into erased from hit;
  -- A statement of its own, with a snapshot of its own: a command that held
  -- the task's row until now has only just committed, and one statement's
  -- snapshot would miss it.
  update bot_task_commands c
  set status = 'cancelled'
  where c.task_id = any (erased) and c.status = 'pending';
  return null;
end;
$$;


--
-- Name: people_erase_candidate_mail(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.people_erase_candidate_mail() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
