    AS $$
begin
  delete from candidate_mail where person_id = new.id;
  return null;
end;
$$;


--
-- Name: people_erase_eeoc(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.people_erase_eeoc() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  delete from eeoc_responses r
  using applications a
  where a.id = r.application_id and a.person_id = new.id;
  return null;
end;
$$;


--
-- Name: people_guard_added_by(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.people_guard_added_by() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.added_by_actor_id is distinct from old.added_by_actor_id then
    if current_actor_id() is not null and current_access_level() <> 'admin' then
      raise exception 'only an admin may change who added a person'
        using errcode = 'insufficient_privilege';
    end if;
  end if;
  return new;
end;
$$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: people; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.people (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    display_name text,
    email text,
    phone text,
    linkedin_url text,
    imessage_handle text,
    current_title text,
    current_company text,
    location text,
    education jsonb,
    skills text[],
    summary text,
    profile_updated_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    github_username text,
    auth_user_id uuid,
    referred_by text,
    stage text,
    past text,
    present text,
    future text,
    interested_verticals text[],
    interested_roles text[],
    unique_about text,
    company_specific text,
    x_handle text,
    x_user_id text,
    rubric_id uuid,
    healthcare_interests text[],
    admired_people text,
    deep_concept text,
    games_played text,
    showcase_links text,
    based_in text,
    willing_to_work text[],
    applicant_status text,
    portal_token_digest text,
    portal_token_rotated_at timestamp with time zone,
    applicant_phone text,
    writeup jsonb,
    funnel_stage text DEFAULT 'new'::text NOT NULL,
    funnel_stage_at timestamp with time zone,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    added_by_actor_id uuid,
    prospect_source text,
    prospect_source_detail text,
    merged_into_id uuid,
    merged_at timestamp with time zone,
    merged_by_actor_id uuid,
    anonymized_at timestamp with time zone,
    anonymized_by_actor_id uuid,
    CONSTRAINT people_applicant_status_check CHECK ((applicant_status = ANY (ARRAY['received'::text, 'in_review'::text, 'interview_1'::text, 'interview_2'::text, 'matched'::text, 'closed'::text]))),
    CONSTRAINT people_funnel_stage_check CHECK ((funnel_stage = ANY (ARRAY['new'::text, 'met'::text, 'interviewing'::text, 'ready'::text, 'in_process'::text, 'placed'::text, 'passed'::text, 'inactive'::text]))),
    CONSTRAINT people_not_merged_into_self CHECK ((merged_into_id IS DISTINCT FROM id)),
    CONSTRAINT people_prospect_source_check CHECK (((prospect_source IS NULL) OR (prospect_source = ANY (ARRAY['sourced'::text, 'suggested'::text, 'applicant'::text, 'referral'::text, 'agency'::text, 'job_board'::text, 'event'::text, 'other'::text])))),
    CONSTRAINT people_prospect_source_detail_check CHECK (((prospect_source_detail IS NULL) OR ((prospect_source_detail = btrim(prospect_source_detail)) AND ((length(prospect_source_detail) >= 1) AND (length(prospect_source_detail) <= 200))))),
    CONSTRAINT people_stage_check CHECK ((stage = ANY (ARRAY['interview_1'::text, 'interview_2'::text])))
);


--
-- Name: COLUMN people.x_handle; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.people.x_handle IS 'X/Twitter username, normalized lowercase without @. Matching hint only; filled by sixtyfour twitter_url parsing (>=0.7 confidence) or manually.';


--
-- Name: COLUMN people.x_user_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.people.x_user_id IS 'Immutable numeric X user id, pinned by the DM reader on first handle match. Once set, DM ingestion requires id equality (recycled-handle guard).';


--
-- Name: COLUMN people.games_played; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.people.games_played IS 'Esports-club /apply extra: one bullet list of games with peak rank and account handle (see ESPORTS_CLUBS in apps/landing''s apply-config).';


--
-- Name: COLUMN people.showcase_links; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.people.showcase_links IS '"Please share any links that showcase what you built or written" -- one bullet list from /apply, stored as-is.';


--
-- Name: COLUMN people.based_in; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.people.based_in IS 'Where the applicant is based -- single choice from /apply, with "In school: <school>" / "Other: <city>" carrying the write-ins.';


--
-- Name: COLUMN people.willing_to_work; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.people.willing_to_work IS 'Where the applicant is willing to work -- multi-select from /apply, same shape as interested_verticals.';


--
-- Name: COLUMN people.applicant_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.people.applicant_status IS 'Applicant-facing pipeline stage shown on /portal. Null = not an applicant. Curated separately from `stage`; advanced by the internal team.';


--
-- Name: COLUMN people.portal_token_digest; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.people.portal_token_digest IS 'sha256 hex digest of the /portal access token minted at /apply submit. Plaintext is never stored; a lost token means minting a new one by hand.';


--
-- Name: COLUMN people.portal_token_rotated_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.people.portal_token_rotated_at IS 'Last portal-link rotation (resend flow throttle watermark). Null for rows whose token has only ever been minted at /apply submit.';


--
-- Name: COLUMN people.applicant_phone; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.people.applicant_phone IS 'Phone number the applicant typed into /apply. Self-reported and unverified; deliberately separate from `phone` so the anon insert path never feeds person_identifiers directly.';


--
-- Name: COLUMN people.funnel_stage; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.people.funnel_stage IS 'Where this person stands with Tacit, independent of any role: new, met, interviewing, ready, in_process, placed, or the outcomes passed / inactive. Not `stage` (the interview round) and not `applicant_status` (the /apply portal). Written only through core''s funnel module.';


--
-- Name: COLUMN people.funnel_stage_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.people.funnel_stage_at IS 'When the person entered their current funnel_stage. Null until the first move.';


--
-- Name: COLUMN people.added_by_actor_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.people.added_by_actor_id IS 'The member who made this row (set_current_actor). A prospect (no application) is editable by them and admins.';


--
-- Name: COLUMN people.prospect_source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.people.prospect_source IS 'How a prospect came in (applications.source values); copied onto the application when they join a job.';


--
-- Name: COLUMN people.merged_into_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.people.merged_into_id IS 'Set when this row was merged into another (client_merge_candidates): the row is kept, hidden from members.';


--
-- Name: COLUMN people.anonymized_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.people.anonymized_at IS 'Set when this person''s personal data was erased (client_anonymize_candidate).';


--
-- Name: people_search_tsv(public.people); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.people_search_tsv(p public.people) RETURNS tsvector
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select
    setweight(to_tsvector('english'::regconfig, coalesce(p.display_name, '')), 'A') ||
    setweight(to_tsvector('simple'::regconfig, coalesce(p.email, '')), 'A') ||
    setweight(to_tsvector('english'::regconfig,
      coalesce(p.current_title, '') || ' ' || coalesce(p.current_company, '')), 'B') ||
    setweight(coalesce(jsonb_to_tsvector('english'::regconfig, p.education, '["string"]'), ''::tsvector), 'B') ||
    setweight(to_tsvector('english'::regconfig, coalesce(array_to_string(p.skills, ' '), '')), 'C') ||
    setweight(to_tsvector('english'::regconfig,
      coalesce(p.summary, '') || ' ' || coalesce(p.past, '') || ' ' || coalesce(p.present, '')), 'D')
$$;


--
-- Name: person_in_no_pipeline(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.person_in_no_pipeline(p_person uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (select 1 from people p where p.id = p_person and p.org_id = (select current_org_id()))
    and not exists (select 1 from applications a where a.person_id = p_person)
$$;


--
-- Name: pool_memberships_validate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pool_memberships_validate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'UPDATE' then
    if new.pool_id <> old.pool_id or new.person_id <> old.person_id or new.org_id <> old.org_id then
      raise exception 'a pool membership stays on its pool and person' using errcode = '22023';
    end if;
    new.created_at := old.created_at;
    new.added_by_actor_id := old.added_by_actor_id;
    new.updated_at := now();
  end if;
  return new;
end;
$$;


--
-- Name: record_eeoc(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_eeoc(p_application uuid, p_gender text DEFAULT NULL::text, p_race_ethnicity text DEFAULT NULL::text, p_veteran_status text DEFAULT NULL::text, p_disability_status text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := current_actor_id();
  job uuid;
  prior text;
  n integer;
begin
  if me is null then
    raise exception 'not a member of this organization' using errcode = '42501';
  end if;
  job := application_role(p_application);
  if job is null then
    raise exception 'no such application' using errcode = 'P0002';
  end if;
  if not can_on_role(job, 'can_manage_job') then
    raise exception 'only the people who manage this job record its EEO forms' using errcode = '42501';
  end if;
  if num_nonnulls(p_gender, p_race_ethnicity, p_veteran_status, p_disability_status) = 0 then
    raise exception 'nothing to record: every question is unanswered' using errcode = '22023';
  end if;
  if p_gender is not null and p_gender not in ('male', 'female', 'decline_to_self_identify') then
    raise exception 'gender is not one of the EEO-1 categories' using errcode = '22023';
  end if;
  if p_race_ethnicity is not null and p_race_ethnicity not in (
       'hispanic_or_latino', 'white', 'black_or_african_american', 'native_hawaiian_or_other_pacific_islander',
       'asian', 'american_indian_or_alaska_native', 'two_or_more_races', 'decline_to_self_identify') then
    raise exception 'race_ethnicity is not one of the EEO-1 categories' using errcode = '22023';
  end if;
  if p_veteran_status is not null and p_veteran_status not in ('protected_veteran', 'not_a_protected_veteran', 'decline_to_self_identify') then
    raise exception 'veteran_status is not one of the categories' using errcode = '22023';
  end if;
  if p_disability_status is not null and p_disability_status not in ('has_disability', 'no_disability', 'decline_to_self_identify') then
    raise exception 'disability_status is not one of the categories' using errcode = '22023';
  end if;

  select r.source into prior from eeoc_responses r where r.application_id = p_application for update;
  if prior = 'candidate' then
    raise exception 'the candidate answered for themselves' using errcode = '23505';
  end if;

  insert into eeoc_responses (application_id, gender, race_ethnicity, veteran_status, disability_status, source, recorded_by_actor_id)
  values (p_application, p_gender, p_race_ethnicity, p_veteran_status, p_disability_status, 'paper', me)
  on conflict (application_id) do update
    set gender = excluded.gender,
        race_ethnicity = excluded.race_ethnicity,
        veteran_status = excluded.veteran_status,
        disability_status = excluded.disability_status,
        recorded_by_actor_id = excluded.recorded_by_actor_id,
        updated_at = now()
    where eeoc_responses.source = 'paper';
  get diagnostics n = row_count;
  if n = 0 then
    -- The candidate's own answer landed between the read and the write.
    raise exception 'the candidate answered for themselves' using errcode = '23505';
  end if;
  return case when prior is null then 'recorded' else 'replaced' end;
end;
$$;


--
-- Name: record_job_post_view(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_job_post_view(p_slug text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  day_cap constant integer := 100000;
  minute_cap constant integer := 300;
  v_day date := (now() at time zone 'utc')::date;
  v_minute timestamptz := date_trunc('minute', now());
  post record;
begin
  -- PostgREST runs a GET read-only. Without this the insert would answer a live
  -- post with an error and every other slug with nothing.
  if current_setting('transaction_read_only') = 'on' then
    return;
  end if;

  -- A wrong slug, a draft, a closed post and a job that is not open all answer alike.
  select jp.id, jp.org_id into post
  from job_posts jp
  join roles r on r.org_id = jp.org_id and r.id = jp.role_id
  where p_slug ~ '^[a-z0-9]{24,64}$'
    and jp.slug = p_slug
    and jp.status = 'live'
    and r.status = 'open';
  if not found then
    return;
  end if;

  -- Over a limit: not counted, and nothing written, so a flood stops at a read.
  if exists (
    select 1 from job_post_views v
    where v.job_post_id = post.id and v.day = v_day
      and (v.views >= day_cap or (v.minute_at >= v_minute and v.minute_views >= minute_cap))
  ) then
    return;
  end if;

  -- The same limits on the locked row, for the calls that raced past the check.
  -- A transaction's now() can trail the row's minute by a moment at the turn of
  -- one: >= keeps that call in the newer minute rather than rewinding it.
  insert into job_post_views (org_id, job_post_id, day, views, minute_at, minute_views)
  values (post.org_id, post.id, v_day, 1, v_minute, 1)
  on conflict (job_post_id, day) do update
    set views = job_post_views.views + 1,
        minute_at = greatest(job_post_views.minute_at, excluded.minute_at),
        minute_views = case when job_post_views.minute_at >= excluded.minute_at
                            then job_post_views.minute_views + 1 else 1 end
    where job_post_views.views < day_cap
      and (job_post_views.minute_at < excluded.minute_at or job_post_views.minute_views < minute_cap);
end;
$_$;


--
-- Name: request_approval(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_approval(p_kind text, p_target uuid) RETURNS TABLE(request_id uuid, request_status text, outcome text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := current_actor_id();
  my_org uuid := current_org_id();
  v_role uuid;
  v_offer uuid;
  v_state text;
  v_first smallint;
  v_live approval_requests%rowtype;
  v_id uuid;
begin
  if me is null then
    raise exception 'not a signed-in member' using errcode = '42501';
  end if;
  if p_kind = 'offer' then
    select a.role_id, o.id, o.status into v_role, v_offer, v_state
    from offers o join applications a on a.id = o.application_id
    where o.id = p_target and o.org_id = my_org;
    if not found then
      raise exception 'no such offer' using errcode = '22023';
    end if;
  elsif p_kind = 'job_open' then
    select r.id, r.status into v_role, v_state from roles r where r.id = p_target and r.org_id = my_org;
    if not found then
      raise exception 'no such job' using errcode = '22023';
    end if;
  else
    raise exception 'an approval is for offer or job_open' using errcode = '22023';
  end if;
  if not can_on_role(v_role, 'can_manage_job') then
    raise exception 'only someone who manages the job asks for its approvals' using errcode = '42501';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('approvals:' || v_role::text || ':' || p_kind, 0));
  if p_kind = 'offer' then
    select status into v_state from offers where id = v_offer for update;
    if v_state <> 'draft' then
      raise exception 'only a draft offer goes for approval' using errcode = '22023';
    end if;
  else
    select status into v_state from roles where id = v_role for update;
    if v_state = 'open' then
      raise exception 'that job is already open' using errcode = '22023';
    end if;
  end if;

  select min(a.step) into v_first
  from approval_flow_approvers a join approval_flows f on f.id = a.flow_id
  where f.role_id = v_role and f.kind = p_kind;
  if v_first is null then
    raise exception 'that job has no approval flow for this' using errcode = '22023';
  end if;

  select * into v_live from approval_requests r
  where r.role_id = v_role and r.kind = p_kind and r.offer_id is not distinct from v_offer
    and (r.status = 'pending' or (r.status = 'approved' and r.used_at is null))
  order by r.created_at desc
  limit 1;
  if found then
    return query select v_live.id, v_live.status,
      case v_live.status when 'pending' then 'already_pending' else 'already_approved' end;
    return;
  end if;

  v_id := gen_random_uuid();
  insert into approval_requests (id, org_id, role_id, kind, offer_id, current_step, requested_by_actor_id)
  values (v_id, my_org, v_role, p_kind, v_offer, v_first, me);
  return query select v_id, 'pending'::text, 'requested'::text;
end;
$$;


--
-- Name: roles_follow_approvals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.roles_follow_approvals() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.status = 'open' and old.status <> 'open' then
    update approval_requests set used_at = now()
    where role_id = new.id and kind = 'job_open' and status = 'approved' and used_at is null;
  end if;
  return null;
end;
$$;


--
-- Name: roles_validate_approval(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.roles_validate_approval() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.status <> 'open' or old.status = 'open' then
    return new;
  end if;
  if not exists (
    select 1 from approval_flow_approvers a join approval_flows f on f.id = a.flow_id
    where f.role_id = new.id and f.kind = 'job_open'
  ) then
    return new;
  end if;
  if exists (select 1 from approval_requests where role_id = new.id and kind = 'job_open' and status = 'approved' and used_at is null) then
    return new;
  end if;
  -- Picking a paused job back up does not need its opening approved again.
  if old.status = 'paused' and exists (
    select 1 from approval_requests where role_id = new.id and kind = 'job_open' and status = 'approved' and used_at is not null
  ) then
    return new;
  end if;
  if exists (select 1 from approval_requests where role_id = new.id and kind = 'job_open' and status = 'pending') then
    raise exception 'this job is still waiting on approval to open' using errcode = '22023';
  end if;
  raise exception 'this job needs approval before it opens, and its opening is not approved' using errcode = '22023';
end;
$$;


--
-- Name: scorecard_attributes_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scorecard_attributes_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.role_id <> old.role_id or new.org_id <> old.org_id then
    raise exception 'a scorecard attribute stays on its job' using errcode = '22023';
  end if;
  new.created_at := old.created_at;
  new.updated_at := now();
  return new;
end;
$$;


--
-- Name: seed_org_access(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seed_org_access(p_org uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  insert into access_roles (org_id, name, is_builtin, can_view_candidates, can_edit_pipeline, can_email,
                            can_schedule, can_view_feedback, can_view_private, can_manage_job, own_candidates_only)
  values
    (p_org, 'Admin',               true, true,  true,  true,  true,  true,  false, true,  false),
    (p_org, 'Admin - Private',     true, true,  true,  true,  true,  true,  true,  true,  false),
    (p_org, 'Hiring Manager',      true, true,  true,  true,  true,  true,  false, true,  false),
    (p_org, 'Hiring Team Member',  true, true,  false, false, false, true,  false, false, false),
    (p_org, 'External Recruiter',  true, true,  true,  false, false, false, false, false, true),
    (p_org, 'No Access',           true, false, false, false, false, false, false, false, false)
  on conflict (org_id, name) do nothing;

  insert into hiring_team_role_access (org_id, team_role, access_role_id)
  select p_org, m.team_role, ar.id
  from (values ('hiring_manager', 'Hiring Manager'), ('recruiter', 'Admin'),
               ('coordinator', 'Hiring Team Member'), ('sourcer', 'Hiring Team Member'),
               ('interviewer', null)) as m (team_role, access_role_name)
  left join access_roles ar on ar.org_id = p_org and ar.name = m.access_role_name
  on conflict (org_id, team_role) do nothing;
$$;


--
-- Name: seed_org_access_on_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seed_org_access_on_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform seed_org_access(new.id);
  return new;
end;
$$;


