--
-- Name: set_approval_flow(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_approval_flow(p_role uuid, p_kind text, p_steps jsonb) RETURNS TABLE(changed boolean, requests_reset integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := current_actor_id();
  my_org uuid := current_org_id();
  v_flow uuid;
  v_group jsonb;
  v_ids uuid[];
  v_all uuid[] := '{}';
  v_new jsonb := '[]'::jsonb;
  v_old jsonb;
  v_step smallint := 0;
  v_reset integer := 0;
begin
  if me is null then
    raise exception 'not a signed-in member' using errcode = '42501';
  end if;
  if p_kind is null or p_kind not in ('offer', 'job_open') then
    raise exception 'an approval flow is for offer or job_open' using errcode = '22023';
  end if;
  if not exists (select 1 from roles where id = p_role and org_id = my_org) or not can_on_role(p_role, 'can_manage_job') then
    raise exception 'only someone who manages the job sets its approvals' using errcode = '42501';
  end if;
  if p_steps is null or jsonb_typeof(p_steps) <> 'array' or jsonb_array_length(p_steps) > 10 then
    raise exception 'an approval flow is a list of at most 10 steps' using errcode = '22023';
  end if;

  for v_group in select e from jsonb_array_elements(p_steps) with ordinality as t(e, i) order by i loop
    if jsonb_typeof(v_group) <> 'array' or jsonb_array_length(v_group) not between 1 and 10 then
      raise exception 'each step names 1 to 10 approvers' using errcode = '22023';
    end if;
    begin
      v_ids := array(select distinct x::uuid from jsonb_array_elements_text(v_group) x order by 1);
    exception when invalid_text_representation then
      raise exception 'an approver is a member id' using errcode = '22023';
    end;
    if cardinality(v_ids) <> jsonb_array_length(v_group) or v_ids && v_all then
      raise exception 'each approver appears once in a flow' using errcode = '22023';
    end if;
    if (select count(*) from actors where id = any (v_ids) and org_id = my_org and archived_at is null) <> cardinality(v_ids) then
      raise exception 'every approver must be an active member of the company' using errcode = '22023';
    end if;
    v_all := v_all || v_ids;
    v_new := v_new || jsonb_build_array(to_jsonb(v_ids));
  end loop;

  -- One change to one job's approvals of a kind at a time, and none while a
  -- request is being made (request_approval takes the same lock).
  perform pg_advisory_xact_lock(hashtextextended('approvals:' || p_role::text || ':' || p_kind, 0));

  select coalesce(jsonb_agg(s.ids order by s.step), '[]'::jsonb) into v_old
  from (
    select a.step, to_jsonb(array_agg(a.actor_id order by a.actor_id)) as ids
    from approval_flow_approvers a join approval_flows f on f.id = a.flow_id
    where f.role_id = p_role and f.kind = p_kind
    group by a.step
  ) s;
  if v_old = v_new then
    return query select false, 0;
    return;
  end if;

  select id into v_flow from approval_flows where role_id = p_role and kind = p_kind;
  if jsonb_array_length(v_new) = 0 then
    delete from approval_flows where id = v_flow;
  else
    if v_flow is null then
      v_flow := gen_random_uuid();
      insert into approval_flows (id, org_id, role_id, kind, updated_by_actor_id) values (v_flow, my_org, p_role, p_kind, me);
    else
      update approval_flows set updated_by_actor_id = me, updated_at = now() where id = v_flow;
      delete from approval_flow_approvers where flow_id = v_flow;
    end if;
    for v_group in select e from jsonb_array_elements(v_new) with ordinality as t(e, i) order by i loop
      v_step := v_step + 1;
      insert into approval_flow_approvers (org_id, flow_id, step, actor_id)
      select my_org, v_flow, v_step, x::uuid from jsonb_array_elements_text(v_group) x;
    end loop;
  end if;

  update approval_requests
  set status = 'reset', resolved_at = now(), current_step = null
  where role_id = p_role and kind = p_kind and (status = 'pending' or (status = 'approved' and used_at is null));
  get diagnostics v_reset = row_count;
  return query select true, v_reset;
end;
$$;


--
-- Name: set_connector_access(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_connector_access(p_access text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := current_actor_id();
  org uuid := current_org_id();
  previous text;
begin
  if me is null or current_access_level() is distinct from 'admin' then
    raise exception 'only an admin can change the connector''s access' using errcode = '42501';
  end if;
  if p_access is null or p_access not in ('read_write', 'read_only') then
    raise exception 'access is read_write or read_only' using errcode = '22023';
  end if;
  select o.connector_access into previous from orgs o where o.id = org for update;
  if previous is distinct from p_access then
    update orgs
    set connector_access = p_access, connector_access_set_by_actor_id = me, connector_access_set_at = now()
    where id = org;
  end if;
  return previous;
end;
$$;


--
-- Name: set_current_actor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_current_actor() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := current_actor_id();
begin
  if me is not null and (to_jsonb(new) ->> tg_argv[0]) is null then
    new := jsonb_populate_record(new, jsonb_build_object(tg_argv[0], me));
  end if;
  return new;
end;
$$;


--
-- Name: set_org_member_access(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_org_member_access(p_actor uuid, p_access_level text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := current_actor_id();
  my_org uuid;
  previous text;
begin
  if me is null or (select access_level from actors where id = me) <> 'admin' then
    raise exception 'only an admin can change access' using errcode = '42501';
  end if;
  if p_access_level is null or p_access_level not in ('limited', 'elevated', 'admin') then
    raise exception 'unknown access level' using errcode = '22023';
  end if;
  select org_id into my_org from actors where id = me;

  -- One change to one org's admins at a time, so two admins demoting each
  -- other cannot both pass the last-admin check.
  perform pg_advisory_xact_lock(hashtextextended('org-admins:' || my_org::text, 0));

  select access_level into previous
  from actors
  where id = p_actor and org_id = my_org and archived_at is null
  for update;
  if not found then
    raise exception 'no such member' using errcode = '22023';
  end if;
  if previous = p_access_level then
    return previous;
  end if;
  if previous = 'admin' and not exists (
    select 1 from actors
    where org_id = my_org and archived_at is null and access_level = 'admin' and id <> p_actor
      and auth_subject is not null
  ) then
    raise exception 'the org would have no admin' using errcode = '23514';
  end if;

  update actors set access_level = p_access_level where id = p_actor;
  return previous;
end;
$$;


