-- Name: submit_job_application(text, jsonb, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_job_application(p_slug text, p_answers jsonb, p_honeypot text DEFAULT NULL::text, p_eeoc jsonb DEFAULT NULL::jsonb) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.submit_job_application(p_slug, p_answers, p_honeypot, p_eeoc, null::text)
$$;


--
-- Name: submit_job_application(text, jsonb, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_job_application(p_slug text, p_answers jsonb, p_honeypot text, p_eeoc jsonb, p_channel text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform public.submit_job_application(p_slug, p_answers, p_honeypot, p_eeoc, p_channel, null::jsonb);
  return true;
end;
$$;


--
-- Name: submit_job_application(text, jsonb, text, jsonb, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_job_application(p_slug text, p_answers jsonb, p_honeypot text, p_eeoc jsonb, p_channel text, p_resume jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  post record;
  q jsonb;
  v jsonb;
  k text;
  s text;
  qid text;
  qtype text;
  recorded jsonb := '[]'::jsonb;
  v_name text;
  v_email text;
  v_phone text;
  v_linkedin text;
  v_person uuid;
  v_app uuid;
  e_gender text;
  e_race text;
  e_veteran text;
  e_disability text;
  -- 20261108120000: the uploaded resume's details.
  r_filename text;
  r_type text;
  r_size bigint;
  r_file uuid;
  r_path text;
begin
  -- A wrong slug, a draft, a closed post and a job that is not open all answer alike.
  select jp.id, jp.org_id, jp.role_id, jp.title, jp.questions into post
  from job_posts jp
  join roles r on r.org_id = jp.org_id and r.id = jp.role_id
  where p_slug ~ '^[a-z0-9]{24,64}$'
    and jp.slug = p_slug
    and jp.status = 'live'
    and r.status = 'open';
  if not found then
    raise exception 'job post not found' using errcode = 'P0002';
  end if;

  -- The form's hidden field: a person never fills it. Answered as a success, with no file.
  if coalesce(btrim(p_honeypot), '') <> '' then
    return null;
  end if;

  if p_answers is null or jsonb_typeof(p_answers) <> 'object' then
    raise exception 'answers: invalid' using errcode = '22023';
  end if;
  if length(p_answers::text) > 100000 then
    raise exception 'answers: too_long' using errcode = '22023';
  end if;
  for k in select jsonb_object_keys(p_answers) loop
    -- The key is the caller's text: never echoed.
    if not exists (select 1 from jsonb_array_elements(post.questions) e where e ->> 'id' = k) then
      raise exception 'answers: unknown' using errcode = '22023';
    end if;
  end loop;

  -- 20261108120000: the file, checked before the questions so a resume
  -- question can count it. Nothing in it is echoed.
  if p_resume is not null and jsonb_typeof(p_resume) <> 'null' then
    if jsonb_typeof(p_resume) <> 'object'
       or exists (select 1 from jsonb_object_keys(p_resume) rk where rk not in ('filename', 'content_type', 'size_bytes'))
       or jsonb_typeof(p_resume -> 'filename') is distinct from 'string'
       or jsonb_typeof(p_resume -> 'content_type') is distinct from 'string'
       or jsonb_typeof(p_resume -> 'size_bytes') is distinct from 'number' then
      raise exception 'resume: invalid' using errcode = '22023';
    end if;
    if not exists (select 1 from jsonb_array_elements(post.questions) e where e ->> 'type' = 'resume') then
      raise exception 'resume: invalid' using errcode = '22023';
    end if;
    r_filename := btrim(p_resume ->> 'filename');
    r_type := p_resume ->> 'content_type';
    if length(r_filename) not between 1 and 200 or r_filename ~ '[/\\[:cntrl:]]' then
      raise exception 'resume: invalid' using errcode = '22023';
    end if;
    if r_type not in ('application/pdf', 'application/msword',
                      'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
                      'text/plain', 'image/png', 'image/jpeg') then
      raise exception 'resume: invalid' using errcode = '22023';
    end if;
    if (p_resume ->> 'size_bytes') !~ '^[0-9]{1,8}$' then
      raise exception 'resume: invalid' using errcode = '22023';
    end if;
    r_size := (p_resume ->> 'size_bytes')::bigint;
    if r_size < 1 then
      raise exception 'resume: invalid' using errcode = '22023';
    end if;
    if r_size > 3 * 1024 * 1024 then
      raise exception 'resume: too_long' using errcode = '22023';
    end if;
  end if;

  for q in select value from jsonb_array_elements(post.questions) loop
    qid := q ->> 'id';
    qtype := q ->> 'type';
    v := p_answers -> qid;
    s := null;
    if v is not null and jsonb_typeof(v) <> 'null' then
      if qtype = 'yes_no' and jsonb_typeof(v) = 'boolean' then
        s := case when v = 'true'::jsonb then 'yes' else 'no' end;
      elsif jsonb_typeof(v) <> 'string' then
        raise exception '%: invalid', qid using errcode = '22023';
      else
        s := nullif(btrim(v #>> '{}'), '');
      end if;
    end if;
    -- 20261108120000: a file answers a resume question, and a link with it is one answer too many.
    if qtype = 'resume' and r_filename is not null then
      if s is not null then
        raise exception '%: invalid', qid using errcode = '22023';
      end if;
      recorded := recorded || jsonb_build_array(
        jsonb_build_object('id', qid, 'type', qtype, 'label', q ->> 'label', 'value', r_filename, 'file', true));
      continue;
    end if;
    if s is null then
      if (q ->> 'required')::boolean then
        raise exception '%: required', qid using errcode = '22023';
      end if;
      continue;
    end if;

    case qtype
      when 'name' then
        if length(s) > 200 then raise exception '%: too_long', qid using errcode = '22023'; end if;
        v_name := s;
      when 'email' then
        s := lower(s);
        if length(s) > 254 then raise exception '%: too_long', qid using errcode = '22023'; end if;
        if s !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
          raise exception '%: invalid', qid using errcode = '22023';
        end if;
        v_email := s;
      when 'phone' then
        if length(s) > 40 then raise exception '%: too_long', qid using errcode = '22023'; end if;
        if s !~ '^\+?[0-9 ().-]{5,40}$' then raise exception '%: invalid', qid using errcode = '22023'; end if;
        v_phone := s;
      when 'linkedin' then
        if length(s) > 300 then raise exception '%: too_long', qid using errcode = '22023'; end if;
        if s !~* '^https?://([a-z]{2,3}\.)?linkedin\.com/[^[:space:]]*$' then
          raise exception '%: invalid', qid using errcode = '22023';
        end if;
        v_linkedin := s;
      when 'resume' then
        -- A link: the five-argument call's way, unchanged.
        if length(s) > 500 then raise exception '%: too_long', qid using errcode = '22023'; end if;
        if s !~* '^https?://[^[:space:]/]+\.[^[:space:]/]+[^[:space:]]*$' then
          raise exception '%: invalid', qid using errcode = '22023';
        end if;
      when 'short_text' then
        if length(s) > 300 then raise exception '%: too_long', qid using errcode = '22023'; end if;
      when 'long_text' then
        if length(s) > 5000 then raise exception '%: too_long', qid using errcode = '22023'; end if;
      when 'yes_no' then
        s := lower(s);
        if s not in ('yes', 'no') then raise exception '%: invalid', qid using errcode = '22023'; end if;
      when 'select' then
        if not exists (select 1 from jsonb_array_elements_text(q -> 'options') o where o = s) then
          raise exception '%: invalid', qid using errcode = '22023';
        end if;
      else
        raise exception '%: invalid', qid using errcode = '22023';
    end case;
    recorded := recorded || jsonb_build_array(
      jsonb_build_object('id', qid, 'type', qtype, 'label', q ->> 'label', 'value', s));
  end loop;

  -- Voluntary self-identification, apart from the form's questions
  -- (20261016170000). Every key optional, every value one of the categories or
  -- empty; nothing answered writes nothing. A bad one is 'eeoc: invalid'.
  if p_eeoc is not null and jsonb_typeof(p_eeoc) <> 'null' then
    if jsonb_typeof(p_eeoc) <> 'object' then
      raise exception 'eeoc: invalid' using errcode = '22023';
    end if;
    for k in select jsonb_object_keys(p_eeoc) loop
      if k not in ('gender', 'race_ethnicity', 'veteran_status', 'disability_status')
         or jsonb_typeof(p_eeoc -> k) not in ('string', 'null') then
        raise exception 'eeoc: invalid' using errcode = '22023';
      end if;
    end loop;
    e_gender := nullif(btrim(p_eeoc ->> 'gender'), '');
    e_race := nullif(btrim(p_eeoc ->> 'race_ethnicity'), '');
    e_veteran := nullif(btrim(p_eeoc ->> 'veteran_status'), '');
    e_disability := nullif(btrim(p_eeoc ->> 'disability_status'), '');
    if (e_gender is not null and e_gender not in ('male', 'female', 'decline_to_self_identify'))
       or (e_race is not null and e_race not in (
            'hispanic_or_latino', 'white', 'black_or_african_american', 'native_hawaiian_or_other_pacific_islander',
            'asian', 'american_indian_or_alaska_native', 'two_or_more_races', 'decline_to_self_identify'))
       or (e_veteran is not null and e_veteran not in ('protected_veteran', 'not_a_protected_veteran', 'decline_to_self_identify'))
       or (e_disability is not null and e_disability not in ('has_disability', 'no_disability', 'decline_to_self_identify')) then
      raise exception 'eeoc: invalid' using errcode = '22023';
    end if;
  end if;

  -- Where the applicant came from (20261030180000, widened by 20261030240000), one of the listed values or null.
  if p_channel is not null and p_channel not in ('linkedin', 'hackernews', 'indeed', 'wellfound', 'x', 'blind', 'google', 'direct', 'other') then
    raise exception 'channel: invalid' using errcode = '22023';
  end if;

  -- The rate limit, under a per-post lock so the count and the row are one step.
  perform pg_advisory_xact_lock(hashtextextended('job-post-apply:' || post.id::text, 0));
  delete from job_post_attempts
  where (job_post_id = post.id or email_digest = md5(v_email)) and created_at < now() - interval '1 day';
  if (select count(*) from job_post_attempts
      where job_post_id = post.id and created_at > now() - interval '1 hour') >= 300
     or (select count(*) from job_post_attempts
         where email_digest = md5(v_email) and created_at > now() - interval '1 hour') >= 5 then
    raise exception 'too many applications: try again later' using errcode = 'PT429';
  end if;
  insert into job_post_attempts (org_id, job_post_id, email_digest) values (post.org_id, post.id, md5(v_email));

  -- Find or add the person inside the post's org, as connector_add_person
  -- does and under its lock, so the two never make one address twice.
  perform pg_advisory_xact_lock(hashtextextended('connector-person-email:' || post.org_id || ':' || v_email, 0));
  select pi.person_id into v_person
  from person_identifiers pi
  where pi.org_id = post.org_id and pi.kind = 'email' and pi.value = v_email;
  if v_person is null then
    select p.id into v_person
    from people p
    where p.org_id = post.org_id and lower(p.email) = v_email
    order by p.created_at
    limit 1;
  end if;
  if v_person is null then
    v_person := gen_random_uuid();
    -- people_attach_identifiers_ins indexes the address (and phone, link) in this org.
    insert into people (id, display_name, email, phone, linkedin_url, org_id)
    values (v_person, v_name, v_email, v_phone, v_linkedin, post.org_id);
  end if;

  -- Already in this job: left where they are, file and all, and the caller is told nothing different.
  if exists (select 1 from applications a where a.person_id = v_person and a.role_id = post.role_id) then
    return null;
  end if;

  v_app := gen_random_uuid();
  insert into applications (id, person_id, role_id, org_id, stage, source, source_detail, channel)
  values (v_app, v_person, post.role_id, post.org_id, 'sourced', 'job_board', post.title, p_channel);
  insert into application_events (application_id, org_id, kind, to_stage, detail)
  values (v_app, post.org_id, 'added', 'sourced', 'job_board');
  insert into application_answers (application_id, org_id, job_post_id, answers)
  values (v_app, post.org_id, post.id, recorded);
  if num_nonnulls(e_gender, e_race, e_veteran, e_disability) > 0 then
    insert into eeoc_responses (application_id, org_id, gender, race_ethnicity, veteran_status, disability_status, source)
    values (v_app, post.org_id, e_gender, e_race, e_veteran, e_disability, 'candidate');
  end if;

  -- 20261108120000: the file's row, on the person, at the path every file row has.
  if r_filename is not null then
    r_file := gen_random_uuid();
    r_path := post.org_id::text || '/' || v_person::text || '/' || r_file::text;
    insert into person_files (id, org_id, person_id, kind, storage_path, filename, content_type, size_bytes)
    values (r_file, post.org_id, v_person, 'resume', r_path, r_filename, r_type, r_size);
  end if;
  return r_path;
end;
$_$;


--
-- Name: sync_job_access(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_job_access(p_role uuid, p_actor uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  best uuid;
begin
  if exists (select 1 from job_access where role_id = p_role and actor_id = p_actor and source = 'manual') then
    return;
  end if;

  select ar.id into best
  from hiring_team ht
  join hiring_team_role_access m on m.org_id = ht.org_id and m.team_role = ht.team_role
  join access_roles ar on ar.id = m.access_role_id
  where ht.role_id = p_role and ht.actor_id = p_actor
  order by (ar.can_view_candidates::int + ar.can_edit_pipeline::int + ar.can_email::int + ar.can_schedule::int
            + ar.can_view_feedback::int + ar.can_view_private::int + ar.can_manage_job::int) desc, ar.name
  limit 1;

  if best is null then
    delete from job_access where role_id = p_role and actor_id = p_actor and source = 'hiring_team';
  else
    insert into job_access (role_id, actor_id, access_role_id, source)
    values (p_role, p_actor, best, 'hiring_team')
    on conflict (actor_id, role_id) do update set access_role_id = excluded.access_role_id;
  end if;
end;
$$;


--
-- Name: tacit_attach_person_identifiers(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tacit_attach_person_identifiers() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into person_identifiers (person_id, kind, value)
  select new.id, v.kind, v.value from tacit_person_identifier_rows(new) v
  on conflict (org_id, kind, value) do nothing;
  return null;
end;
$$;


--
-- Name: tacit_canon_phone(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tacit_canon_phone(raw text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case
    when d = '' then null
    when length(d) = 11 and left(d, 1) = '1' then substr(d, 2)
    else d
  end
  from (select regexp_replace(coalesce(raw, ''), '\D', '', 'g') as d) x
$$;


--
-- Name: tacit_person_identifier_rows(public.people); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tacit_person_identifier_rows(p public.people) RETURNS TABLE(kind text, value text)
    LANGUAGE sql IMMUTABLE
    AS $_$
  with v (kind, value) as materialized (
    select 'email'::text, lower(regexp_replace(p.email, '^\s+|\s+$', '', 'g'))
    union all select 'phone', tacit_canon_phone(p.phone)
    union all select 'imessage',
      case when p.imessage_handle like '%@%' then lower(regexp_replace(p.imessage_handle, '^\s+|\s+$', '', 'g'))
           else tacit_canon_phone(p.imessage_handle) end
    union all select 'x_handle', lower(ltrim(regexp_replace(p.x_handle, '^\s+|\s+$', '', 'g'), '@'))
    union all select 'x_user_id', regexp_replace(p.x_user_id, '^\s+|\s+$', '', 'g')
  )
  select v.kind, v.value from v
  where v.value is not null and v.value <> ''
$_$;


--
-- Name: tacit_snapshot_person(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tacit_snapshot_person() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_reason text;
  v_actor  uuid;
begin
  v_reason := coalesce(nullif(current_setting('tacit.reason', true), ''), 'unknown');
  begin
    v_actor := nullif(current_setting('tacit.actor_id', true), '')::uuid;
  exception when others then
    v_actor := null;
  end;

  insert into person_snapshots (person_id, reason, actor_id, data, data_columns, user_reply)
  values (
    old.id,
    v_reason,
    v_actor,
    to_jsonb(old),
    array(select jsonb_object_keys(to_jsonb(old))),
    nullif(current_setting('tacit.user_reply', true), '')
  );
  return new;
end;
$$;


--
-- Name: tenant_set_org_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_set_org_id() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  ref text;
  found_org uuid;
  i int := 0;
begin
  if new.org_id is not null then
    return new;
  end if;
  while i < tg_nargs loop
    ref := to_jsonb(new) ->> tg_argv[i];
    if ref is not null then
      execute format('select org_id from public.%I where id = $1', tg_argv[i + 1])
        into found_org using ref::uuid;
      if found_org is not null then
        new.org_id := found_org;
        return new;
      end if;
    end if;
    i := i + 2;
  end loop;
  new.org_id := coalesce(current_org_id(), tacit_org_id());
  return new;
end;
$_$;


--
-- Name: withdraw_org_invite(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.withdraw_org_invite(p_actor uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if current_actor_id() is null or current_access_level() is distinct from 'admin' then
    raise exception 'only an admin of the org may withdraw an invitation' using errcode = '42501';
  end if;
  delete from actors
  where id = p_actor
    and org_id = current_org_id()
    and auth_subject is null
    and archived_at is null;
  return found;
end;
$$;


