    can_schedule boolean DEFAULT false NOT NULL,
    can_view_feedback boolean DEFAULT false NOT NULL,
    can_view_private boolean DEFAULT false NOT NULL,
    can_manage_job boolean DEFAULT false NOT NULL,
    own_candidates_only boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE access_roles; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.access_roles IS 'A named bundle of permissions an actor can hold on a job (job_access). Six are built in per org.';


--
-- Name: actors; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.actors (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    slug text NOT NULL,
    display_name text NOT NULL,
    person_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    granola_api_key text,
    granola_last_synced_at timestamp with time zone,
    granola_sync_started_at timestamp with time zone,
    granola_last_sync_result text,
    granola_webhook_secret text,
    granola_webhook_endpoint_id text,
    granola_webhook_registered_at timestamp with time zone,
    gmail_refresh_token text,
    gmail_address text,
    gmail_connected_at timestamp with time zone,
    outreach_verticals text[] DEFAULT '{}'::text[] NOT NULL,
    ntfy_topic text,
    scheduling_prefs jsonb,
    archived_at timestamp with time zone,
    slack_user_id text,
    email text,
    auth_subject text,
    email_signature text,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    access_level text DEFAULT 'limited'::text NOT NULL,
    can_view_all_confidential boolean DEFAULT false NOT NULL,
    can_view_private boolean DEFAULT false NOT NULL,
    tacit_agency boolean DEFAULT false NOT NULL,
    CONSTRAINT actors_access_level_check CHECK ((access_level = ANY (ARRAY['limited'::text, 'elevated'::text, 'admin'::text])))
);


--
-- Name: COLUMN actors.granola_api_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.actors.granola_api_key IS 'Granola API key for self-serve polling from apps/internal. Plaintext by necessity (sent outbound); table is service-role-only.';


--
-- Name: COLUMN actors.granola_last_synced_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.actors.granola_last_synced_at IS 'When the last self-serve Granola poll for this actor finished (webhook ingests do not update this).';


--
-- Name: COLUMN actors.granola_sync_started_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.actors.granola_sync_started_at IS 'Set when a self-serve poll kicks off, cleared when it finishes (success or failure). Stale after ~15min = assume crashed.';


--
-- Name: COLUMN actors.granola_last_sync_result; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.actors.granola_last_sync_result IS 'Human-readable outcome of the last finished self-serve poll, rendered under the sync button.';


--
-- Name: COLUMN actors.granola_webhook_secret; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.actors.granola_webhook_secret IS 'Standard Webhooks signing secret for this actor''s Granola webhook registration, captured from the creation response when apps/internal auto-registers it. Fallback for GRANOLA_WEBHOOK_SIGNING_SECRET_<SLUG> (env wins). Plaintext by necessity; table is service-role-only.';


--
-- Name: COLUMN actors.granola_webhook_endpoint_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.actors.granola_webhook_endpoint_id IS 'Granola webhook endpoint id (whe_...) created by the self-serve registration, so re-registration can detect/replace its own endpoint instead of stacking duplicates.';


--
-- Name: COLUMN actors.granola_webhook_registered_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.actors.granola_webhook_registered_at IS 'When the self-serve webhook registration last succeeded for this actor.';


--
-- Name: COLUMN actors.gmail_refresh_token; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.actors.gmail_refresh_token IS 'Google OAuth refresh token scoped to gmail.send, captured by apps/internal''s /connect Gmail step. Plaintext by necessity (exchanged for an access token on every send); table is service-role-only.';


--
-- Name: COLUMN actors.gmail_address; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.actors.gmail_address IS 'The Gmail address the refresh token is bound to (from the consent flow''s ID token), i.e. the From address outreach sends as.';


--
-- Name: COLUMN actors.gmail_connected_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.actors.gmail_connected_at IS 'When the Gmail consent last succeeded for this actor.';


--
-- Name: COLUMN actors.outreach_verticals; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.actors.outreach_verticals IS 'Verticals this teammate owns for cold outreach (from the fixed VERTICALS list in @tacit/core). A send whose chosen vertical is in this array routes to this actor''s Gmail. Set self-serve on apps/internal /connect.';


--
-- Name: COLUMN actors.ntfy_topic; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.actors.ntfy_topic IS 'ntfy topic this actor''s scheduling drafts are pushed to (the notification tap opens Messages with the draft prefilled). Null disables the scheduling agent for this actor -- an ntfy topic being set is itself the on switch. Self-serve config; actors is service-role-only.';


--
-- Name: COLUMN actors.scheduling_prefs; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.actors.scheduling_prefs IS 'Scheduling preferences the drafter grounds proposals in (timezone, meeting length, earliest/latest hour, video vs in person). jsonb-as-working-value, validated in @tacit/scheduling; no db-level shape constraint, same stance as person_facts.value.';


--
-- Name: COLUMN actors.archived_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.actors.archived_at IS 'Set when the actor is no longer a current teammate (or is a duplicate row). Kept for its history; hidden from current-teammate rosters such as listUploadOwners. Null = active.';


--
-- Name: COLUMN actors.email; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.actors.email IS 'The teammate''s Tacit address. The connector matches a first sign-in to an actor by it, and sends candidate email From it.';


--
-- Name: COLUMN actors.auth_subject; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.actors.auth_subject IS 'WorkOS user id (the access token''s sub). Null until the teammate first signs in to the connector.';


--
-- Name: COLUMN actors.email_signature; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.actors.email_signature IS 'Plain-text signature the connector appends to an email draft. Optional.';


--
-- Name: COLUMN actors.org_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.actors.org_id IS 'The org this user belongs to. A Tacit teammate working inside a client''s ATS is a second actor in that org, as in Ashby.';


--
-- Name: COLUMN actors.access_level; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.actors.access_level IS 'limited: own interviews and a fixed candidate card only. elevated: what job_access grants. admin: the org, except confidential roles (can_view_all_confidential) and private data (can_view_private).';


--
-- Name: COLUMN actors.tacit_agency; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.actors.tacit_agency IS 'A Tacit teammate''s actor in a client org, made by tacit_submit_to_client: they submit as the agency and are never invited.';


--
-- Name: agent_destinations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.agent_destinations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    channel text DEFAULT 'grok_bot_webhook'::text NOT NULL,
    url text NOT NULL,
    secret text NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    verified_at timestamp with time zone,
    created_by_actor_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT agent_destinations_channel_check CHECK ((channel = 'grok_bot_webhook'::text)),
    CONSTRAINT agent_destinations_secret_check CHECK ((((length(secret) >= 16) AND (length(secret) <= 512)) AND (secret !~ '[[:space:][:cntrl:]]'::text))),
    CONSTRAINT agent_destinations_url_check CHECK (((url ~ '^https://[^\s/?#@]+(/[^\s]*)?$'::text) AND (length(url) <= 2000)))
);


--
-- Name: TABLE agent_destinations; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.agent_destinations IS 'A company''s own bot (its Grok team bot): where its interview events go. secret is never granted to authenticated; read by the notifier with the service role.';


--
-- Name: COLUMN agent_destinations.secret; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.agent_destinations.secret IS 'Signs every event to the bot and authenticates the bot''s callbacks. Shown to the admin once, when set or rotated.';


