--
-- Name: applications; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.applications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    person_id uuid NOT NULL,
    role_id uuid NOT NULL,
    stage text DEFAULT 'sourced'::text NOT NULL,
    source text DEFAULT 'sourced'::text NOT NULL,
    owner_actor_id uuid,
    added_by_actor_id uuid,
    last_touch_at timestamp with time zone DEFAULT now() NOT NULL,
    next_action text,
    next_action_due date,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    next_action_owner_actor_id uuid,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    rejection_reason_id uuid,
    rejection_note text,
    source_detail text,
    merged_into_id uuid,
    channel text,
    CONSTRAINT applications_channel_check CHECK ((channel = ANY (ARRAY['linkedin'::text, 'hackernews'::text, 'indeed'::text, 'wellfound'::text, 'x'::text, 'blind'::text, 'google'::text, 'direct'::text, 'other'::text]))),
    CONSTRAINT applications_not_merged_into_self CHECK ((merged_into_id IS DISTINCT FROM id)),
    CONSTRAINT applications_rejection_note_check CHECK (((rejection_note IS NULL) OR (length(rejection_note) <= 2000))),
    CONSTRAINT applications_source_check CHECK ((source = ANY (ARRAY['sourced'::text, 'suggested'::text, 'applicant'::text, 'referral'::text, 'agency'::text, 'job_board'::text, 'event'::text, 'other'::text]))),
    CONSTRAINT applications_source_detail_check CHECK (((source_detail IS NULL) OR ((source_detail = btrim(source_detail)) AND ((length(source_detail) >= 1) AND (length(source_detail) <= 200))))),
    CONSTRAINT applications_stage_check CHECK ((stage = ANY (ARRAY['sourced'::text, 'contacted'::text, 'screening'::text, 'interviewing'::text, 'offer'::text, 'hired'::text, 'rejected'::text, 'withdrawn'::text])))
);


--
-- Name: TABLE applications; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.applications IS 'One person being considered for one role: current stage, owner, last touch, next action and its deadline. Written only through core''s pipeline module, which appends an application_events row with every change.';


--
-- Name: COLUMN applications.next_action_owner_actor_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.applications.next_action_owner_actor_id IS 'Who the next action is waiting on. Null = the application''s owner. Cleared with the next action.';


--
-- Name: COLUMN applications.merged_into_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.applications.merged_into_id IS 'Set when a merge found the same person twice in this job: the more advanced application is kept, this one points at it.';


--
-- Name: COLUMN applications.channel; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.applications.channel IS 'Where a public job post''s applicant came from: linkedin, hackernews, indeed, wellfound, x, blind, google, direct or other. Null is not recorded. Set by submit_job_application only.';


--
-- Name: approval_decisions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.approval_decisions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    request_id uuid NOT NULL,
    step smallint NOT NULL,
    actor_id uuid,
    decision text NOT NULL,
    reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT approval_decisions_decision_check CHECK ((decision = ANY (ARRAY['approved'::text, 'rejected'::text]))),
    CONSTRAINT approval_decisions_reason_check CHECK (((reason IS NULL) OR ((length(reason) >= 1) AND (length(reason) <= 2000))))
);


--
-- Name: TABLE approval_decisions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.approval_decisions IS 'One decision per step of a request: who approved or rejected it, when, and why.';


--
-- Name: approval_flow_approvers; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.approval_flow_approvers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    flow_id uuid NOT NULL,
    step smallint NOT NULL,
    actor_id uuid NOT NULL,
    CONSTRAINT approval_flow_approvers_step_check CHECK (((step >= 1) AND (step <= 10)))
);


--
-- Name: TABLE approval_flow_approvers; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.approval_flow_approvers IS 'A flow''s steps: steps run in ascending order, and any one approver of a step passes it.';


--
-- Name: approval_flows; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.approval_flows (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    role_id uuid NOT NULL,
    kind text NOT NULL,
    updated_by_actor_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT approval_flows_kind_check CHECK ((kind = ANY (ARRAY['offer'::text, 'job_open'::text])))
);


--
-- Name: TABLE approval_flows; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.approval_flows IS 'Per job and kind (offer | job_open): the approval chain that gates extending an offer or opening the job. Written by set_approval_flow.';


--
-- Name: approval_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.approval_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    role_id uuid NOT NULL,
    kind text NOT NULL,
    offer_id uuid,
    status text DEFAULT 'pending'::text NOT NULL,
    current_step smallint,
    requested_by_actor_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    resolved_at timestamp with time zone,
    used_at timestamp with time zone,
    CONSTRAINT approval_requests_current_step_check CHECK (((status = 'pending'::text) = (current_step IS NOT NULL))),
    CONSTRAINT approval_requests_kind_check CHECK ((kind = ANY (ARRAY['offer'::text, 'job_open'::text]))),
    CONSTRAINT approval_requests_kind_offer_check CHECK (((kind = 'offer'::text) = (offer_id IS NOT NULL))),
    CONSTRAINT approval_requests_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text, 'reset'::text, 'cancelled'::text]))),
    CONSTRAINT approval_requests_used_at_check CHECK (((used_at IS NULL) OR (status = 'approved'::text)))
);


--
-- Name: TABLE approval_requests; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.approval_requests IS 'A request for approval of one offer or of opening one job. pending -> approved | rejected; reset or cancelled when what it approved changes. used_at = the approval was spent.';


--
-- Name: approvals; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.approvals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    draft_id uuid NOT NULL,
    reviewer_actor_id uuid,
    decision text NOT NULL,
    note text,
    decided_at timestamp with time zone DEFAULT now() NOT NULL,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    CONSTRAINT approvals_decision_check CHECK ((decision = ANY (ARRAY['approve'::text, 'reject'::text])))
);


--
-- Name: TABLE approvals; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.approvals IS 'A reviewer''s decision on a draft that needed review (offer, rejection, intro). Written after the draft''s status has moved out of pending_review, which is the claim: two decisions on one draft cannot both land.';


--
-- Name: audit_log; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.audit_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    actor_id uuid,
    source text NOT NULL,
    action text NOT NULL,
    entity text NOT NULL,
    entity_id uuid,
    before jsonb,
    after jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    CONSTRAINT audit_log_source_check CHECK ((source = ANY (ARRAY['claude'::text, 'chatgpt'::text, 'slack'::text, 'dashboard'::text, 'script'::text, 'cli'::text])))
);


--
-- Name: TABLE audit_log; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.audit_log IS 'One row per write made through the connector: who, from which client, and the row before and after. A row is claimed (connector_claim_write) BEFORE its write and completed after, so a write cannot happen unrecorded; a row whose `after` is null was claimed and did not complete. Also what the hourly write and send limits count.';


--
-- Name: bot_task_commands; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bot_task_commands (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    task_id uuid NOT NULL,
    command text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    error text,
    created_by_actor_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    sent_at timestamp with time zone,
    CONSTRAINT bot_task_commands_command_check CHECK ((command = ANY (ARRAY['retry'::text, 'nudge'::text, 'send_invite'::text, 'cancel'::text]))),
    CONSTRAINT bot_task_commands_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'sent'::text, 'failed'::text, 'cancelled'::text])))
);


--
-- Name: TABLE bot_task_commands; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.bot_task_commands IS 'A member''s commands to the company''s bot on one of its tasks: queued here by bot_task_command, delivered to the bot by the notify tick as a signed bot_task.command event (cmd_<id> is the bot''s dedupe key).';


--
-- Name: bot_tasks; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bot_tasks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    agent_destination_id uuid NOT NULL,
    kind text NOT NULL,
    application_id uuid,
    interview_id uuid,
    actor_id uuid,
    status text DEFAULT 'running'::text NOT NULL,
    waiting_on_actor_id uuid,
    waiting_on_person_id uuid,
    waiting_channel text,
    steps jsonb DEFAULT '[]'::jsonb NOT NULL,
    error text,
    needs_you boolean DEFAULT false NOT NULL,
    ref text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT bot_tasks_check CHECK (((waiting_on_actor_id IS NULL) OR (waiting_on_person_id IS NULL))),
    CONSTRAINT bot_tasks_kind_check CHECK ((kind = ANY (ARRAY['find_interviewer'::text, 'ask_interviewer'::text, 'schedule_interview'::text, 'get_read'::text, 'send_testbench'::text, 'send_rejection'::text, 'send_invite'::text, 'other'::text]))),
    CONSTRAINT bot_tasks_ref_check CHECK (((length(ref) >= 1) AND (length(ref) <= 200))),
    CONSTRAINT bot_tasks_status_check CHECK ((status = ANY (ARRAY['running'::text, 'waiting'::text, 'done'::text, 'failed'::text, 'cancelled'::text]))),
    CONSTRAINT bot_tasks_steps_check CHECK ((jsonb_typeof(steps) = 'array'::text)),
    CONSTRAINT bot_tasks_waiting_channel_check CHECK ((waiting_channel = ANY (ARRAY['slack'::text, 'imessage'::text, 'email'::text, 'other'::text])))
);


--
-- Name: TABLE bot_tasks; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.bot_tasks IS 'What a company''s bot is doing, one row per task, reported by the bot through its callback and upserted on its ref. Members read it under pipeline visibility; steps are opaque labels, never message text.';


--
-- Name: COLUMN bot_tasks.needs_you; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.bot_tasks.needs_you IS 'The Inbox''s needs-you flag: set by the bot when it is stuck, or by the tick on a task that has not moved in a day.';


--
-- Name: calendar_connections; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.calendar_connections (
    actor_id uuid NOT NULL,
    org_id uuid NOT NULL,
    provider text DEFAULT 'google'::text NOT NULL,
    account_email text NOT NULL,
    refresh_token text NOT NULL,
    scopes text DEFAULT ''::text NOT NULL,
    connected_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT calendar_connections_account_email_check CHECK (((account_email = lower(btrim(account_email))) AND ((length(account_email) >= 3) AND (length(account_email) <= 320)) AND (account_email ~~ '%@%'::text))),
    CONSTRAINT calendar_connections_provider_check CHECK ((provider = 'google'::text)),
    CONSTRAINT calendar_connections_refresh_token_check CHECK (((length(refresh_token) >= 1) AND (length(refresh_token) <= 4096))),
    CONSTRAINT calendar_connections_scopes_check CHECK ((length(scopes) <= 2000))
);


--
-- Name: TABLE calendar_connections; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.calendar_connections IS 'A client member''s connected calendar (Google): the grant the client connector books interviews with. refresh_token is never granted to authenticated.';


--
-- Name: COLUMN calendar_connections.refresh_token; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.calendar_connections.refresh_token IS 'The provider''s refresh token. Read only by the service role (tacit-ats apps/mcp client/calendar.ts); written only by client_connect_calendar.';


--
-- Name: candidate_email_replies; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.candidate_email_replies (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    email_id uuid NOT NULL,
    from_email text NOT NULL,
    subject text DEFAULT ''::text NOT NULL,
    body text DEFAULT ''::text NOT NULL,
    provider_id text NOT NULL,
    received_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT candidate_email_replies_body_check CHECK ((length(body) <= 20000)),
    CONSTRAINT candidate_email_replies_from_email_check CHECK (((length(from_email) >= 3) AND (length(from_email) <= 320))),
    CONSTRAINT candidate_email_replies_provider_id_check CHECK (((length(provider_id) >= 1) AND (length(provider_id) <= 200))),
    CONSTRAINT candidate_email_replies_subject_check CHECK (((length(subject) <= 300) AND (subject !~ '[\r\n]'::text)))
);


--
-- Name: TABLE candidate_email_replies; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.candidate_email_replies IS 'A candidate''s reply to a client member''s email: received by Resend at the email''s reply+<id>@ address, or synced from the Gmail thread the email started. Written with the service role; read with the email it answers.';


--
-- Name: candidate_emails; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.candidate_emails (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    person_id uuid NOT NULL,
    application_id uuid,
    template_id uuid,
    author_actor_id uuid,
    to_email text NOT NULL,
    subject text NOT NULL,
    body text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    provider_id text,
    error text,
    sending_at timestamp with time zone,
    sent_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    sent_via text,
    thread_id text,
    CONSTRAINT candidate_emails_body_check CHECK (((length(btrim(body)) >= 1) AND (length(btrim(body)) <= 20000))),
    CONSTRAINT candidate_emails_error_check CHECK (((error IS NULL) OR (length(error) <= 1000))),
    CONSTRAINT candidate_emails_provider_id_check CHECK (((provider_id IS NULL) OR (length(provider_id) <= 200))),
    CONSTRAINT candidate_emails_sent_via_check CHECK (((sent_via IS NULL) OR (sent_via = ANY (ARRAY['resend'::text, 'gmail'::text])))),
    CONSTRAINT candidate_emails_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'sending'::text, 'sent'::text, 'failed'::text]))),
    CONSTRAINT candidate_emails_subject_check CHECK ((((length(btrim(subject)) >= 1) AND (length(btrim(subject)) <= 300)) AND (subject !~ '[\r\n]'::text))),
    CONSTRAINT candidate_emails_thread_id_check CHECK (((thread_id IS NULL) OR ((length(thread_id) >= 1) AND (length(thread_id) <= 200)))),
    CONSTRAINT candidate_emails_to_email_check CHECK (((to_email = lower(btrim(to_email))) AND (length(to_email) <= 320) AND (to_email ~ '^[a-z0-9._%+-]+@[a-z0-9-]+(\.[a-z0-9-]+)+$'::text)))
);


--
-- Name: TABLE candidate_emails; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.candidate_emails IS 'A client member''s email to a candidate: draft -> sending -> sent | failed. Only the author sends it; what was drafted never changes.';


--
-- Name: COLUMN candidate_emails.sent_via; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.candidate_emails.sent_via IS 'How it went out: resend (From Tacit''s address) or gmail (From the author''s own mailbox). Set on sending -> sent only.';


--
-- Name: COLUMN candidate_emails.thread_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.candidate_emails.thread_id IS 'The Gmail thread a gmail email started, in its author''s mailbox: where tacit-ats reads the candidate''s replies. Set on sending -> sent only.';


--
-- Name: candidate_mail; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.candidate_mail (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    person_id uuid NOT NULL,
    actor_id uuid,
    direction text NOT NULL,
    from_email text NOT NULL,
    to_emails text[] DEFAULT '{}'::text[] NOT NULL,
    subject text DEFAULT ''::text NOT NULL,
    body text DEFAULT ''::text NOT NULL,
    provider_id text NOT NULL,
    thread_id text,
    sent_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT candidate_mail_body_check CHECK ((length(body) <= 20000)),
    CONSTRAINT candidate_mail_direction_check CHECK ((direction = ANY (ARRAY['in'::text, 'out'::text]))),
    CONSTRAINT candidate_mail_from_email_check CHECK (((length(from_email) >= 3) AND (length(from_email) <= 320))),
    CONSTRAINT candidate_mail_provider_id_check CHECK (((length(provider_id) >= 1) AND (length(provider_id) <= 200))),
    CONSTRAINT candidate_mail_subject_check CHECK (((length(subject) <= 300) AND (subject !~ '[\r\n]'::text))),
    CONSTRAINT candidate_mail_thread_id_check CHECK (((thread_id IS NULL) OR (length(thread_id) <= 200))),
    CONSTRAINT candidate_mail_to_emails_check CHECK ((cardinality(to_emails) <= 100))
);


--
-- Name: TABLE candidate_mail; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.candidate_mail IS 'An email between a member and a candidate, synced from the member''s Gmail by tacit-ats with the service role. Read where the candidate is read, never by an interviewer.';


--
-- Name: candidate_messages; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.candidate_messages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    person_id uuid,
    to_email text NOT NULL,
    subject text NOT NULL,
    body text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    provider_id text,
    error text,
    sent_by_actor_id uuid,
    sent_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    application_id uuid,
    message_type text DEFAULT 'other'::text NOT NULL,
    reason text,
    version integer DEFAULT 1 NOT NULL,
    superseded_by uuid,
    gmail_thread_id text,
    in_reply_to text,
    company_contact_id uuid,
    reviewer_actor_id uuid,
    review_requested_at timestamp with time zone,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    CONSTRAINT candidate_messages_message_type_check CHECK ((message_type = ANY (ARRAY['follow_up'::text, 'status_update'::text, 'scheduling'::text, 'offer'::text, 'rejection'::text, 'intro'::text, 'other'::text]))),
    CONSTRAINT candidate_messages_one_recipient CHECK ((num_nonnulls(person_id, company_contact_id) <= 1)),
    CONSTRAINT candidate_messages_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'pending_review'::text, 'approved'::text, 'rejected'::text, 'sending'::text, 'sent'::text, 'failed'::text, 'superseded'::text, 'skipped'::text])))
);


--
-- Name: TABLE candidate_messages; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.candidate_messages IS 'Emails to a candidate drafted through the connector. draft = shown to the teammate, nothing sent; sent = delivered to the provider (provider_id). Only the author can send a draft, and only to the person''s email on file.';


--
-- Name: COLUMN candidate_messages.application_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.candidate_messages.application_id IS 'The application (person + role) this message is about, when the drafter knew. Decides the card''s role title and whose DM it goes to.';


--
-- Name: COLUMN candidate_messages.message_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.candidate_messages.message_type IS 'What kind of message this is. offer, rejection and intro need a review before they can be sent from a Slack card.';


--
-- Name: COLUMN candidate_messages.superseded_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.candidate_messages.superseded_by IS 'The newer version of this draft. A draft with one is never sent.';


--
-- Name: COLUMN candidate_messages.gmail_thread_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.candidate_messages.gmail_thread_id IS 'The Gmail thread this message started, when it was sent from the author''s own mailbox. What the card-replies cron reads for answers.';


--
-- Name: COLUMN candidate_messages.in_reply_to; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.candidate_messages.in_reply_to IS 'Message-ID of the email this draft answers, for a reply written from a card''s Slack thread. Null for an email that starts a conversation.';


--
-- Name: COLUMN candidate_messages.company_contact_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.candidate_messages.company_contact_id IS 'The client contact this message is to, when it is not to a candidate. Exactly one of this and person_id is set.';


--
-- Name: COLUMN candidate_messages.reviewer_actor_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.candidate_messages.reviewer_actor_id IS 'The teammate a draft was sent to for review through the connector: the owner of the client company, else the configured fallback. Never the author.';


--
-- Name: companies; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.companies (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    website_url text,
    description text,
    "values" text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    owner_actor_id uuid,
    private_context text,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL
);


--
-- Name: COLUMN companies.owner_actor_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.companies.owner_actor_id IS 'The teammate who owns this client relationship. Reviews offer / rejection / intro emails to candidates for its roles before they are sent from a Slack card.';


--
-- Name: COLUMN companies.private_context; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.companies.private_context IS 'Internal notes on a client: how they decide, what they pay, who to go through. Returned to Tacit teammates only; never put in anything a candidate or the client reads.';


--
-- Name: company_contacts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.company_contacts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    name text NOT NULL,
    email text,
    title text,
    is_hiring_owner boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL
);


--
-- Name: TABLE company_contacts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.company_contacts IS 'People at a client company Tacit deals with. is_hiring_owner marks who owns the hire on their side.';


--
-- Name: connection_imports; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.connection_imports (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    source text NOT NULL,
    actor_id uuid NOT NULL,
    imported_by uuid,
    total integer DEFAULT 0 NOT NULL,
    created_count integer DEFAULT 0 NOT NULL,
    refreshed_count integer DEFAULT 0 NOT NULL,
    matched integer DEFAULT 0 NOT NULL,
    skipped integer DEFAULT 0 NOT NULL,
    undone_at timestamp with time zone,
    undone_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT connection_imports_source_check CHECK ((source = ANY (ARRAY['linkedin'::text, 'instagram'::text])))
);


--
-- Name: TABLE connection_imports; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.connection_imports IS 'One rolodex upload (LinkedIn CSV or Instagram export). Written by core''s recordConnectionImport via apps/internal''s /connections; rows it CREATED point back through <table>.created_by_import, which is what undoConnectionImport deletes. Refreshed rows are not reversible -- the overwritten values are kept nowhere.';


--
-- Name: COLUMN connection_imports.actor_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.connection_imports.actor_id IS 'Whose rolodex the rows joined (the upload card''s owner picker), not necessarily who uploaded -- see imported_by.';


--
-- Name: COLUMN connection_imports.undone_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.connection_imports.undone_at IS 'Set when the import was reversed. The row survives the undo on purpose; an audit record that disappears with its subject audits nothing.';


