    CONSTRAINT eeoc_responses_disability_status_check CHECK ((disability_status = ANY (ARRAY['has_disability'::text, 'no_disability'::text, 'decline_to_self_identify'::text]))),
    CONSTRAINT eeoc_responses_gender_check CHECK ((gender = ANY (ARRAY['male'::text, 'female'::text, 'decline_to_self_identify'::text]))),
    CONSTRAINT eeoc_responses_race_ethnicity_check CHECK ((race_ethnicity = ANY (ARRAY['hispanic_or_latino'::text, 'white'::text, 'black_or_african_american'::text, 'native_hawaiian_or_other_pacific_islander'::text, 'asian'::text, 'american_indian_or_alaska_native'::text, 'two_or_more_races'::text, 'decline_to_self_identify'::text]))),
    CONSTRAINT eeoc_responses_source_check CHECK ((source = ANY (ARRAY['candidate'::text, 'paper'::text]))),
    CONSTRAINT eeoc_responses_veteran_status_check CHECK ((veteran_status = ANY (ARRAY['protected_veteran'::text, 'not_a_protected_veteran'::text, 'decline_to_self_identify'::text])))
);


--
-- Name: TABLE eeoc_responses; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.eeoc_responses IS 'Voluntary EEO self-identification, one per application. Org admins read rows; everyone else nothing. Written by the candidate path or record_eeoc only.';


