    CONSTRAINT email_templates_name_check CHECK (((name = btrim(name)) AND ((length(name) >= 1) AND (length(name) <= 100)))),
    CONSTRAINT email_templates_subject_check CHECK ((((length(btrim(subject)) >= 1) AND (length(btrim(subject)) <= 300)) AND (subject !~ '[\r\n]'::text)))
);


