    CONSTRAINT google_workspace_connections_domain_check CHECK (((domain = lower(btrim(domain))) AND (domain ~ '^[a-z0-9-]+(\.[a-z0-9-]+)+$'::text) AND (length(domain) <= 253)))
);


--
-- Name: TABLE google_workspace_connections; Type: COMMENT; Schema: public; Owner: -
