COMMENT ON TABLE public.google_workspace_connections IS 'A client company whose Google Workspace admin delegated Gmail to Tacit''s service account, verified by one of its admins. Written only by client_connect_workspace.';


--
-- Name: granola_connections; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.granola_connections (
    actor_id uuid NOT NULL,
    org_id uuid NOT NULL,
    account_email text,
    connected_at timestamp with time zone DEFAULT now() NOT NULL,
    oauth_client_id text NOT NULL,
    refresh_token text NOT NULL,
    access_token text,
    access_token_expires_at timestamp with time zone,
    CONSTRAINT granola_connections_access_token_check CHECK (((access_token IS NULL) OR ((length(access_token) >= 1) AND (length(access_token) <= 8192)))),
    CONSTRAINT granola_connections_account_email_check CHECK (((account_email IS NULL) OR ((account_email = lower(btrim(account_email))) AND ((length(account_email) >= 3) AND (length(account_email) <= 320)) AND (account_email ~~ '%@%'::text)))),
    CONSTRAINT granola_connections_oauth_client_id_check CHECK (((length(oauth_client_id) >= 1) AND (length(oauth_client_id) <= 512))),
    CONSTRAINT granola_connections_refresh_token_check CHECK (((length(refresh_token) >= 1) AND (length(refresh_token) <= 4096)))
);


--
-- Name: TABLE granola_connections; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.granola_connections IS 'A client member''s connected Granola account: the OAuth grant (Granola''s MCP server) the client connector reads their interview notes with. The tokens are never granted to authenticated.';


--
-- Name: COLUMN granola_connections.oauth_client_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.granola_connections.oauth_client_id IS 'The OAuth client tacit-ats registered with Granola for this connection (dynamic client registration). Refreshes use it.';


--
-- Name: COLUMN granola_connections.refresh_token; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.granola_connections.refresh_token IS 'The member''s Granola refresh token. Plaintext by necessity (sent outbound); read and rotated only by the service role; first written by client_connect_granola.';


--
-- Name: COLUMN granola_connections.access_token; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.granola_connections.access_token IS 'The member''s current Granola access token, cached until access_token_expires_at. Service role only.';


--
-- Name: granola_notes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.granola_notes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    note_id text NOT NULL,
    title text,
    category text,
    rationale text,
    synced boolean NOT NULL,
    classified_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    owner_name text,
    owner_email text
);


--
-- Name: TABLE granola_notes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.granola_notes IS 'Classification record for every Granola note seen by ingestion. Only notes whose category qualifies (see core''s SYNC_CATEGORIES) have their transcripts synced into transcript_entries; everything else is recorded here and skipped.';


--
-- Name: COLUMN granola_notes.category; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.granola_notes.category IS 'Conversation category assigned by core''s LLM classification pass -- a pass that has not landed yet, so null today. Taxonomy enforced in code when it does, not by a DB constraint.';


--
-- Name: COLUMN granola_notes.synced; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.granola_notes.synced IS 'Whether the gate passed and the note''s transcript was handed to identity resolution + sync. False for non-qualifying categories AND for qualifying notes seen in a context where syncing was impossible (should not happen in practice -- writers classify and sync in the same pass).';


--
-- Name: COLUMN granola_notes.owner_name; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.granola_notes.owner_name IS 'Granola note owner (whose meeting/account this is) at ingestion time -- NOT necessarily who ingested it; shared notes can sync through another teammate''s path.';


--
-- Name: hiring_team; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hiring_team (
