    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT hiring_team_team_role_check CHECK ((team_role = ANY (ARRAY['hiring_manager'::text, 'recruiter'::text, 'coordinator'::text, 'sourcer'::text, 'interviewer'::text])))
);


--
-- Name: TABLE hiring_team; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.hiring_team IS 'Who works a job, and as what. job_access follows it through hiring_team_role_access.';


--
-- Name: hiring_team_role_access; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hiring_team_role_access (
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    team_role text NOT NULL,
    access_role_id uuid,
    CONSTRAINT hiring_team_role_access_team_role_check CHECK ((team_role = ANY (ARRAY['hiring_manager'::text, 'recruiter'::text, 'coordinator'::text, 'sourcer'::text, 'interviewer'::text])))
);


--
-- Name: TABLE hiring_team_role_access; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.hiring_team_role_access IS 'Per org: the access role a hiring-team role grants on its job.';


--
-- Name: home_targets; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.home_targets (
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    metric text NOT NULL,
    value numeric(10,2) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT home_targets_metric_check CHECK ((metric = ANY (ARRAY['new_applications'::text, 'review'::text, 'schedule'::text, 'feedback'::text, 'workload'::text]))),
    CONSTRAINT home_targets_value_check CHECK (((value >= (0)::numeric) AND (value <= (1000000)::numeric)))
);


--
-- Name: TABLE home_targets; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.home_targets IS 'What a company has chosen as the target for each of Home''s cards, at most one row per org and metric. No row means no target; none is assumed. Written by the org''s admins; read by its admins and elevated members.';


--
-- Name: COLUMN home_targets.metric; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.home_targets.metric IS 'Which card: new_applications (a count, flag below), review, schedule and feedback (typical hours, flag over), workload (hours in the period, flag over).';


--
-- Name: COLUMN home_targets.value; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.home_targets.value IS 'The number chosen, in the metric''s unit: a count for new_applications, hours for the rest. 0 to 1000000, to two decimal places. 0 is a target; a missing one is no row.';


--
-- Name: identity_links; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.identity_links (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    person_id uuid NOT NULL,
    platform text NOT NULL,
    handle text NOT NULL,
    status text DEFAULT 'candidate'::text NOT NULL,
    basis jsonb NOT NULL,
    source text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    CONSTRAINT identity_links_status_check CHECK ((status = ANY (ARRAY['candidate'::text, 'confirmed'::text, 'rejected'::text])))
);


--
-- Name: COLUMN identity_links.handle; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.identity_links.handle IS 'Normalized handle, or a bare domain. STORED LOWERCASE on every platform: case is not identity (github logins, hn, bluesky and domains are all case-insensitive), and unique (person_id, platform, handle) is what keeps a rejected link sticky, so a mixed-case duplicate would defeat it. Writers MUST lower() before inserting and before comparing.';


--
-- Name: inbox_dismissals; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.inbox_dismissals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    actor_id uuid DEFAULT public.current_actor_id() NOT NULL,
    issue_key text NOT NULL,
    reason text NOT NULL,
    issue_at timestamp with time zone NOT NULL,
    how text DEFAULT 'dismissed'::text NOT NULL,
    dismissed_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT inbox_dismissals_how_check CHECK ((how = ANY (ARRAY['dismissed'::text, 'resolved'::text]))),
    CONSTRAINT inbox_dismissals_issue_at_check CHECK (((issue_at >= '0001-01-01 00:00:00+00'::timestamp with time zone) AND (issue_at < '10000-01-01 00:00:00+00'::timestamp with time zone))),
    CONSTRAINT inbox_dismissals_issue_key_check CHECK ((issue_key ~ '^[a-z]{1,16}-[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text)),
    CONSTRAINT inbox_dismissals_reason_check CHECK ((reason ~ '^[a-z]{1,20}$'::text))
);


--
-- Name: TABLE inbox_dismissals; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.inbox_dismissals IS 'A member setting a computed Inbox issue aside: it leaves their queue and shows on Done. Own rows only. Ids and timestamps, never the issue''s wording.';


--
-- Name: COLUMN inbox_dismissals.issue_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.inbox_dismissals.issue_key IS 'Issue.key from tacit-ats lib/client/inbox-issues.ts: a short lowercase prefix and a uuid (app-, appr-, draft-), so there is no room for wording. The same for every issue on one application.';


--
-- Name: COLUMN inbox_dismissals.reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.inbox_dismissals.reason IS 'Issue.reason (draft, feedback, overdue, quiet, decide, approval). A format, not a list: the reasons live in tacit-ats, and a new one should not fail here, but one short lowercase word.';


--
-- Name: COLUMN inbox_dismissals.issue_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.inbox_dismissals.issue_at IS 'What tells this instance from the next one on the same key: the same value must be computed to match. Compare as instants, not strings: a timestamp comes back from Postgres in its own format. Years 1 to 9999 only: Date.parse cannot read infinity, BC or a five-digit year, and one such row would throw on the Done tab.';


--
-- Name: COLUMN inbox_dismissals.how; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.inbox_dismissals.how IS 'How it left: dismissed (set aside) or resolved (the member ran its fix from the Inbox). Done says which.';


