);


--
-- Name: TABLE instagram_connections; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.instagram_connections IS 'One Instagram follow-edge of one teammate (actors row), from their uploaded "Download your information" export. Written by core''s importInstagramConnections via apps/internal''s /connections page; upserts on (actor_id, username), each upload touching only the flag columns its file proves.';


--
-- Name: COLUMN instagram_connections.username; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.instagram_connections.username IS 'Canonical handle (lowercase, no @) -- the dedup key and the identity_links platform ''instagram'' match key.';


--
-- Name: COLUMN instagram_connections.follows; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.instagram_connections.follows IS 'The owning teammate follows this account (proven by a following.json upload).';


--
-- Name: COLUMN instagram_connections.followed_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.instagram_connections.followed_by IS 'This account follows the owning teammate (proven by a followers file upload). Mutual = follows AND followed_by, computed at read time.';


--
-- Name: COLUMN instagram_connections.person_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.instagram_connections.person_id IS 'Set at import when the username matches a confirmed identity_links row (platform instagram). Never mints a people row.';


--
-- Name: COLUMN instagram_connections.updated_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.instagram_connections.updated_at IS 'Writer-stamped on refresh, no trigger (identity_links convention).';


--
-- Name: COLUMN instagram_connections.created_by_import; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.instagram_connections.created_by_import IS 'The import that CREATED this row (null for rows predating the table, and for rows an import only refreshed). Undo deletes by this column.';


--
-- Name: instagram_follow_edges; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.instagram_follow_edges (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    follower_username text NOT NULL,
    followee_username text NOT NULL,
    follower_full_name text,
    is_private boolean,
    is_verified boolean,
    follower_person_id uuid,
    followee_person_id uuid,
    captured_by uuid,
    first_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    last_seen_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: interview_agent_threads; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.interview_agent_threads (
    interview_id uuid NOT NULL,
    actor_id uuid NOT NULL,
    channel text NOT NULL,
    slack_channel_id text NOT NULL,
    thread_ts text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT interview_agent_threads_channel_check CHECK ((channel = ANY (ARRAY['grok_bot_webhook'::text, 'claude_routine_webhook'::text]))),
    CONSTRAINT interview_agent_threads_slack_channel_id_check CHECK ((slack_channel_id ~ '^[A-Z0-9]+$'::text)),
    CONSTRAINT interview_agent_threads_thread_ts_check CHECK ((thread_ts ~ '^[0-9]+\.[0-9]+$'::text))
);


--
-- Name: TABLE interview_agent_threads; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.interview_agent_threads IS 'The Slack thread an outside agent opened with one interviewer about one interview, so every later event about it (check-in, cancellation) goes to the same thread. Written only through core''s notify/ module.';


--
-- Name: interview_feedback; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.interview_feedback (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    interview_id uuid NOT NULL,
    interviewer_actor_id uuid NOT NULL,
    recommendation text NOT NULL,
    rating smallint,
    notes text NOT NULL,
    submitted_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    CONSTRAINT interview_feedback_rating_check CHECK (((rating >= 1) AND (rating <= 4))),
    CONSTRAINT interview_feedback_recommendation_check CHECK ((recommendation = ANY (ARRAY['strong_yes'::text, 'yes'::text, 'no'::text, 'strong_no'::text])))
);


--
-- Name: TABLE interview_feedback; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.interview_feedback IS 'One interviewer''s feedback on one interview: a recommendation, an optional 1-4 rating, and notes. Private to the Tacit team: never read by anything that writes to a candidate or a client. Written only through core''s connector/feedback.ts.';


--
-- Name: interview_feedback_ratings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.interview_feedback_ratings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    feedback_id uuid NOT NULL,
    attribute_id uuid NOT NULL,
    rating smallint NOT NULL,
    note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT interview_feedback_ratings_note_check CHECK (((note IS NULL) OR (length(note) <= 1000))),
    CONSTRAINT interview_feedback_ratings_rating_check CHECK (((rating >= 1) AND (rating <= 4)))
);


--
-- Name: TABLE interview_feedback_ratings; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.interview_feedback_ratings IS 'One interviewer''s 1-4 rating of one scorecard attribute, on their feedback. Private like the feedback: read when it is.';


--
-- Name: interview_processes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.interview_processes (
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    graph jsonb NOT NULL,
    updated_by_actor_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE interview_processes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.interview_processes IS 'How a company interviews, as a flowchart, at most one row per org. No row means none drawn. Written by the org''s admins; read by whoever can_see_prospects().';


--
-- Name: COLUMN interview_processes.graph; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.interview_processes.graph IS 'An object with a nodes array and an edges array, at most 256 KiB as text. The app decides what the nodes and edges mean; the database checks only this shape and size.';


--
-- Name: COLUMN interview_processes.updated_by_actor_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.interview_processes.updated_by_actor_id IS 'The member who last saved it, stamped by the trigger. Null once that actor is deleted, or for a row written without a member.';


--
-- Name: interview_reminder_timers; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.interview_reminder_timers (
    interview_id uuid NOT NULL,
    starts_at timestamp with time zone NOT NULL,
    run_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE interview_reminder_timers; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.interview_reminder_timers IS 'One durable reminder timer per (interview, start time): the claim taken before the Workflow run is started. Written only through core''s notify/reminder-timers.ts.';


--
-- Name: interview_reviews; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.interview_reviews (
    interview_id uuid NOT NULL,
    actor_id uuid DEFAULT public.current_actor_id() NOT NULL,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    reviewed_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE interview_reviews; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.interview_reviews IS 'A member checking off an interview on the ATS''s Interviews page. Own rows to write; read by whoever can read the interview. Ids and a timestamp, never feedback.';


--
-- Name: COLUMN interview_reviews.actor_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.interview_reviews.actor_id IS 'Who checked it off. One row each, so "have I reviewed this" and "has anyone" are both answered here.';


--
-- Name: interview_types; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.interview_types (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    name text NOT NULL,
    archived_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT interview_types_name_check CHECK (((name = btrim(name)) AND ((length(name) >= 1) AND (length(name) <= 100))))
);


--
-- Name: TABLE interview_types; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.interview_types IS 'The kinds of interview a company runs, per org. Unique by lower(name) per org, archived included; archived, never deleted. Written by the org''s admins; read by whoever can_see_prospects().';


--
-- Name: interviewer_interview_types; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.interviewer_interview_types (
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    actor_id uuid NOT NULL,
    type_id uuid NOT NULL,
    prioritized boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE interviewer_interview_types; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.interviewer_interview_types IS 'Which interview types a member runs, per org. Written by the org''s admins; read by whoever can_see_prospects(), which is not the member themselves if they are an interviewer or an external recruiter.';


--
-- Name: COLUMN interviewer_interview_types.prioritized; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.interviewer_interview_types.prioritized IS 'Prefer this member for this type (design/tats''s star). The company''s call, not the member''s.';


--
-- Name: interviewer_profiles; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.interviewer_profiles (
    actor_id uuid DEFAULT public.current_actor_id() NOT NULL,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    interview_preference text,
    weekly_interview_cap integer,
    focus_areas text[] DEFAULT '{}'::text[] NOT NULL,
    preferred_channel text,
    away_until date,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    title text,
    CONSTRAINT interviewer_profiles_away_until_check CHECK (((away_until >= '0001-01-01'::date) AND (away_until < '10000-01-01'::date))),
    CONSTRAINT interviewer_profiles_focus_areas_check CHECK (((COALESCE(array_ndims(focus_areas), 1) = 1) AND (cardinality(focus_areas) <= 20))),
    CONSTRAINT interviewer_profiles_interview_preference_check CHECK ((interview_preference = ANY (ARRAY['loves'::text, 'either'::text, 'avoids'::text]))),
    CONSTRAINT interviewer_profiles_preferred_channel_check CHECK ((preferred_channel = ANY (ARRAY['slack'::text, 'imessage'::text, 'email'::text]))),
    CONSTRAINT interviewer_profiles_title_check CHECK (((title = btrim(title)) AND ((length(title) >= 1) AND (length(title) <= 120)) AND (title !~ '[[:cntrl:]]'::text))),
    CONSTRAINT interviewer_profiles_weekly_interview_cap_check CHECK (((weekly_interview_cap >= 0) AND (weekly_interview_cap <= 40)))
);


--
-- Name: TABLE interviewer_profiles; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.interviewer_profiles IS 'How a member wants to be used as an interviewer, at most one row per member. Written by the member or an admin of their org; read by the member and by elevated and admin members of the org. No row or a null means they have not said.';


--
-- Name: COLUMN interviewer_profiles.interview_preference; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.interviewer_profiles.interview_preference IS 'loves, either or avoids (design/tats: Likes it, Either way, Rather not). Null: has not said, which is not the same as either.';


--
-- Name: COLUMN interviewer_profiles.weekly_interview_cap; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.interviewer_profiles.weekly_interview_cap IS 'Most interviews a week. Null: no limit set. 0: none this week, so divide by it with care. At most 40.';


--
-- Name: COLUMN interviewer_profiles.focus_areas; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.interviewer_profiles.focus_areas IS 'What the member can interview on, as they wrote it (design/tats: Knows). Each one trimmed of Unicode whitespace and invisible marks, one line, at most 60 characters, no repeats ignoring case and composition; at most 20.';


--
-- Name: COLUMN interviewer_profiles.preferred_channel; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.interviewer_profiles.preferred_channel IS 'Where to reach them about interviews: slack, imessage or email. Null: has not said.';


--
-- Name: COLUMN interviewer_profiles.away_until; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.interviewer_profiles.away_until IS 'The last day they are away, inclusive. A date, not an instant: orgs have no time zone yet. Null or a past date means not away; nothing clears it. Years 1 to 9999 only: Date.parse cannot read infinity, BC or a five-digit year.';


--
-- Name: COLUMN interviewer_profiles.title; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.interviewer_profiles.title IS 'What the member''s job is called, as they or an admin wrote it. One trimmed line, 1 to 120 characters. Null: not said.';


--
-- Name: interviews; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.interviews (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    application_id uuid,
    starts_at timestamp with time zone NOT NULL,
    ends_at timestamp with time zone NOT NULL,
    interviewer_actor_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    location_or_link text,
    status text DEFAULT 'scheduled'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    step text,
    google_event_id text,
    google_event_link text,
    calendar_actor_id uuid,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    person_id uuid,
    CONSTRAINT interviews_about_one CHECK (((application_id IS NULL) <> (person_id IS NULL))),
    CONSTRAINT interviews_ends_after_start CHECK ((ends_at > starts_at)),
    CONSTRAINT interviews_status_check CHECK ((status = ANY (ARRAY['scheduled'::text, 'done'::text, 'cancelled'::text])))
);


--
-- Name: TABLE interviews; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.interviews IS 'A scheduled interview on one application. interviewer_actor_ids are actors rows. Written only through core''s connector module.';


--
-- Name: COLUMN interviews.application_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.interviews.application_id IS 'The application a client-role interview is a step of. Null on Tacit''s own interview, which has person_id instead.';


--
-- Name: COLUMN interviews.step; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.interviews.step IS 'The step of the role''s interview process this is, as named in roles.interview_steps. At most one scheduled interview per (application, step).';


--
-- Name: COLUMN interviews.calendar_actor_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.interviews.calendar_actor_id IS 'The teammate whose Google Calendar holds the event (google_event_id): the one who booked it.';


--
-- Name: COLUMN interviews.person_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.interviews.person_id IS 'Set on Tacit''s own interview (the intro call), on the person; null on a client-role interview, which has application_id instead. Exactly one of the two is set.';


--
-- Name: invite_prefills; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.invite_prefills (
    token_digest text NOT NULL,
    unique_about text,
    person_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    invitee_name text,
    answers jsonb
);


--
-- Name: TABLE invite_prefills; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.invite_prefills IS 'Granola-derived draft answers for the /apply unique_about question, keyed by sha256 of the personal invite token. Written by the Slack mint flow, read once by /apply?invite= to prefill the form.';


--
-- Name: COLUMN invite_prefills.invitee_name; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.invite_prefills.invitee_name IS 'The /intake name the prefill was drafted for -- the digest-miss fallback key, so re-minted links still find the latest draft.';


--
-- Name: COLUMN invite_prefills.answers; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.invite_prefills.answers IS 'Drafted answers keyed by people column name (unique_about, showcase_links, admired_people, deep_concept) -- only the questions the transcript supported. Null on rows written before 2026-09-15.';


--
-- Name: job_access; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.job_access (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    actor_id uuid NOT NULL,
    role_id uuid NOT NULL,
    access_role_id uuid NOT NULL,
    source text DEFAULT 'manual'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT job_access_source_check CHECK ((source = ANY (ARRAY['manual'::text, 'hiring_team'::text])))
);


--
-- Name: TABLE job_access; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.job_access IS 'One actor''s access role on one job (a roles row). At most one per (actor, job).';


--
-- Name: job_offices; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.job_offices (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    role_id uuid NOT NULL,
    office_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE job_offices; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.job_offices IS 'The offices a job (roles row) is in, once each. Written by whoever can manage the job.';


--
-- Name: job_post_attempts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.job_post_attempts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    job_post_id uuid NOT NULL,
    email_digest text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT job_post_attempts_email_digest_check CHECK ((email_digest ~ '^[0-9a-f]{32}$'::text))
);


--
-- Name: TABLE job_post_attempts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.job_post_attempts IS 'submit_job_application''s rate limit: one row per accepted submission, by post and an md5 of the address. Read by nothing else; pruned after a day.';


--
-- Name: job_post_views; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.job_post_views (
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    job_post_id uuid NOT NULL,
    day date NOT NULL,
    views integer DEFAULT 0 NOT NULL,
    minute_at timestamp with time zone DEFAULT now() NOT NULL,
    minute_views integer DEFAULT 0 NOT NULL,
    CONSTRAINT job_post_views_minute_views_check CHECK ((minute_views >= 0)),
    CONSTRAINT job_post_views_views_check CHECK ((views >= 0))
);


--
-- Name: TABLE job_post_views; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.job_post_views IS 'A public job post''s views per UTC day. A count and nothing about who: no reader identity of any kind. Written only by record_job_post_view.';


--
-- Name: COLUMN job_post_views.day; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.job_post_views.day IS 'The UTC day, as tacit-ats''s Analytics buckets applications: an org has no time zone yet.';


--
-- Name: COLUMN job_post_views.views; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.job_post_views.views IS 'Views counted that day, stopping at 100,000. Page loads, not people: nothing here can tell a reader from a repeat or a bot.';


--
-- Name: COLUMN job_post_views.minute_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.job_post_views.minute_at IS 'record_job_post_view''s rate limit: the start of the minute it last counted a view.';


--
-- Name: COLUMN job_post_views.minute_views; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.job_post_views.minute_views IS 'record_job_post_view''s rate limit: views counted in that minute, stopping at 300.';


--
-- Name: job_posts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.job_posts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    role_id uuid NOT NULL,
    slug text DEFAULT replace((gen_random_uuid())::text, '-'::text, ''::text) NOT NULL,
    title text NOT NULL,
    description text,
    location text,
    questions jsonb DEFAULT '[{"id": "name", "type": "name", "label": "Full name", "required": true}, {"id": "email", "type": "email", "label": "Email", "required": true}]'::jsonb NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    created_by_actor_id uuid,
    published_at timestamp with time zone,
    closed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT job_posts_description_check CHECK (((description IS NULL) OR ((length(description) >= 1) AND (length(description) <= 20000)))),
    CONSTRAINT job_posts_location_check CHECK (((location IS NULL) OR ((location = btrim(location)) AND ((length(location) >= 1) AND (length(location) <= 200))))),
    CONSTRAINT job_posts_slug_check CHECK ((slug ~ '^[a-z0-9]{24,64}$'::text)),
    CONSTRAINT job_posts_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'live'::text, 'closed'::text]))),
    CONSTRAINT job_posts_title_check CHECK (((title = btrim(title)) AND ((length(title) >= 1) AND (length(title) <= 200))))
);


--
-- Name: TABLE job_posts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.job_posts IS 'A job''s public post: title, description, location, the application form''s questions, draft | live | closed, and an unguessable slug. Read publicly only through job_post_public.';


--
-- Name: linkedin_connections; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.linkedin_connections (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    actor_id uuid NOT NULL,
    first_name text,
    last_name text,
    full_name text NOT NULL,
    linkedin_url text NOT NULL,
    email text,
    company text,
    "position" text,
    connected_on date,
    person_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by_import uuid
);


--
-- Name: TABLE linkedin_connections; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.linkedin_connections IS 'One LinkedIn connection of one teammate (actors row), from their uploaded Connections.csv export. Written by core''s importLinkedInConnections via apps/internal''s /connections page; upserts on (actor_id, linkedin_url) so re-uploads refresh rather than duplicate.';


--
-- Name: COLUMN linkedin_connections.linkedin_url; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.linkedin_connections.linkedin_url IS 'Canonical profile URL (core''s canonicalLinkedInUrl: lowercased host+path, no query/fragment/trailing slash) -- the dedup and person-match key.';


--
-- Name: COLUMN linkedin_connections.person_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.linkedin_connections.person_id IS 'Set at import when the connection matches an existing person by canonical URL or email identifier. Never mints a people row.';


--
-- Name: COLUMN linkedin_connections.updated_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.linkedin_connections.updated_at IS 'Writer-stamped on refresh, no trigger (identity_links convention).';


--
-- Name: COLUMN linkedin_connections.created_by_import; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.linkedin_connections.created_by_import IS 'The import that CREATED this row (null for rows predating the table, and for rows an import only refreshed). Undo deletes by this column.';


--
-- Name: lookup_runs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.lookup_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    person_id uuid NOT NULL,
    lookup text NOT NULL,
    identifier_used jsonb NOT NULL,
    outcome text NOT NULL,
    detail text,
    ran_at timestamp with time zone DEFAULT now() NOT NULL,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    CONSTRAINT lookup_runs_outcome_check CHECK ((outcome = ANY (ARRAY['hit'::text, 'miss'::text, 'error'::text])))
);


--
-- Name: mailbox_connections; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.mailbox_connections (
    actor_id uuid NOT NULL,
    org_id uuid NOT NULL,
    provider text DEFAULT 'google'::text NOT NULL,
    account_email text NOT NULL,
    refresh_token text NOT NULL,
    scopes text DEFAULT ''::text NOT NULL,
    connected_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT mailbox_connections_account_email_check CHECK (((account_email = lower(btrim(account_email))) AND ((length(account_email) >= 3) AND (length(account_email) <= 320)) AND (account_email ~~ '%@%'::text))),
    CONSTRAINT mailbox_connections_provider_check CHECK ((provider = 'google'::text)),
    CONSTRAINT mailbox_connections_refresh_token_check CHECK (((length(refresh_token) >= 1) AND (length(refresh_token) <= 4096))),
    CONSTRAINT mailbox_connections_scopes_check CHECK ((length(scopes) <= 2000))
);


--
-- Name: TABLE mailbox_connections; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.mailbox_connections IS 'A client member''s own Gmail, connected by OAuth: candidate email is sent through it as them. refresh_token is never granted to authenticated.';


--
-- Name: COLUMN mailbox_connections.refresh_token; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.mailbox_connections.refresh_token IS 'The provider''s refresh token. Read only by the service role (tacit-ats); written only by client_connect_mailbox.';


--
-- Name: mailbox_sync_optouts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.mailbox_sync_optouts (
    actor_id uuid NOT NULL,
    org_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE mailbox_sync_optouts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.mailbox_sync_optouts IS 'A member who turned their own Gmail sync off. Set and cleared only by client_set_mailbox_sync.';


--
-- Name: mailbox_sync_state; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.mailbox_sync_state (
    actor_id uuid NOT NULL,
    org_id uuid NOT NULL,
    history_id text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT mailbox_sync_state_history_id_check CHECK (((length(history_id) >= 1) AND (length(history_id) <= 40)))
);


--
-- Name: TABLE mailbox_sync_state; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.mailbox_sync_state IS 'Where tacit-ats''s Gmail sync is in each member''s mailbox history (Gmail historyId). The service role''s alone.';


--
-- Name: mcp_calls; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.mcp_calls (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    actor_id uuid,
    tool text NOT NULL,
    args_digest text,
    person_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    ok boolean NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: merge_candidates; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.merge_candidates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    cluster_key text NOT NULL,
    member_ids uuid[] NOT NULL,
    name_key text NOT NULL,
    confidence numeric NOT NULL,
    rationale text NOT NULL,
    status text NOT NULL,
    proposed_survivor_id uuid,
    rejected_confidence numeric,
    asked_actor_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    repoke_count integer DEFAULT 0 NOT NULL,
    last_scored_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT merge_candidates_confidence_check CHECK (((confidence >= (0)::numeric) AND (confidence <= (1)::numeric))),
    CONSTRAINT merge_candidates_status_check CHECK ((status = ANY (ARRAY['below_floor'::text, 'asking'::text, 'merged'::text, 'rejected'::text, 'exhausted'::text, 'actor_collision'::text, 'stale'::text])))
);


--
-- Name: network_people; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.network_people (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    display_name text NOT NULL,
    first_name text,
    last_name text,
    person_id uuid,
    actor_id uuid,
    bio text,
    card text,
    card_tsv tsvector GENERATED ALWAYS AS (to_tsvector('english'::regconfig, ((COALESCE(display_name, ''::text) || ' '::text) || COALESCE(card, ''::text)))) STORED,
    card_updated_at timestamp with time zone,
    import_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: network_imports; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.network_imports (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    source text NOT NULL,
    actor_id uuid,
    file_name text,
    counts jsonb DEFAULT '{}'::jsonb NOT NULL,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    undone_at timestamp with time zone
);


--
-- Name: notify_deliveries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.notify_deliveries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    event_id uuid NOT NULL,
    actor_id uuid,
    channel text NOT NULL,
    target text,
    status text DEFAULT 'pending'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    error text,
    claimed_at timestamp with time zone,
    sent_at timestamp with time zone,
    external_ref text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    org_id uuid DEFAULT '7ac17000-0000-4000-8000-000000000001'::uuid NOT NULL,
    CONSTRAINT notify_deliveries_actor_or_target CHECK (((actor_id IS NOT NULL) OR (target IS NOT NULL))),
    CONSTRAINT notify_deliveries_channel_check CHECK ((channel = ANY (ARRAY['slack'::text, 'imessage'::text, 'grok_bot_webhook'::text, 'claude_routine_webhook'::text]))),
    CONSTRAINT notify_deliveries_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'sending'::text, 'sent'::text, 'failed'::text, 'skipped'::text])))
);


--
-- Name: TABLE notify_deliveries; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.notify_deliveries IS 'One message to one recipient on one channel about one event. Unique per (event, actor, channel), and only claim_notify_delivery moves a row out of pending, so no retry or overlapping run sends twice.';


--
-- Name: notify_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.notify_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    type text NOT NULL,
    source text NOT NULL,
    dedupe_key text NOT NULL,
    subject jsonb DEFAULT '{}'::jsonb NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    occurred_at timestamp with time zone NOT NULL,
    notify boolean DEFAULT true NOT NULL,
    fanned_out_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    recipient_actor_ids uuid[],
    org_id uuid DEFAULT '7ac17000-0000-4000-8000-000000000001'::uuid NOT NULL
);


--
-- Name: TABLE notify_events; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.notify_events IS 'One row per event the notification hub was told about, stored once (dedupe_key). notify = false means recorded as already seen, never announced. Written only through core''s notify/ module.';


--
-- Name: COLUMN notify_events.recipient_actor_ids; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.notify_events.recipient_actor_ids IS 'Null = broadcast to subscribers of the type. Set = a directed event: only these actors, on their subscribed channels or Slack by default; never the team channel.';


--
-- Name: notify_sources; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.notify_sources (
    key text NOT NULL,
    baselined_at timestamp with time zone,
    last_ok_at timestamp with time zone,
    last_error text,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE notify_sources; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.notify_sources IS 'Polling state per event source. baselined_at null = first run not finished, so nothing from it is announced yet.';


--
-- Name: notify_subscriptions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.notify_subscriptions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    actor_id uuid NOT NULL,
    event_type text NOT NULL,
    channel text NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT notify_subscriptions_channel_check CHECK ((channel = ANY (ARRAY['slack'::text, 'imessage'::text, 'grok_bot_webhook'::text, 'claude_routine_webhook'::text])))
);


--
-- Name: TABLE notify_subscriptions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.notify_subscriptions IS 'A teammate''s opt-in to one event type on one channel. No row means no message.';


--
-- Name: nudges; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.nudges (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    actor_id uuid NOT NULL,
    type text NOT NULL,
    ref_type text NOT NULL,
    ref_id uuid NOT NULL,
    application_id uuid,
    text text NOT NULL,
    source_url text,
    due_at timestamp with time zone NOT NULL,
    due_on date GENERATED ALWAYS AS (((due_at AT TIME ZONE 'UTC'::text))::date) STORED,
    status text DEFAULT 'open'::text NOT NULL,
    snoozed_until timestamp with time zone,
    dismiss_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    resolved_at timestamp with time zone,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    CONSTRAINT nudges_ref_type_check CHECK ((ref_type = ANY (ARRAY['interview'::text, 'application'::text]))),
    CONSTRAINT nudges_snoozed_has_until CHECK (((status <> 'snoozed'::text) OR (snoozed_until IS NOT NULL))),
    CONSTRAINT nudges_status_check CHECK ((status = ANY (ARRAY['open'::text, 'done'::text, 'snoozed'::text, 'dismissed'::text]))),
    CONSTRAINT nudges_type_check CHECK ((type = ANY (ARRAY['interview_soon'::text, 'next_action_due'::text, 'quiet_candidate'::text, 'feedback_due'::text])))
);


--
-- Name: TABLE nudges; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.nudges IS 'One thing a teammate should do, computed when they ask for their list and kept so their answer sticks. Unique per (actor, type, ref, UTC day of due_at). done = they did it, or it stopped being true; dismissed = they said it was not useful (dismiss_reason, for tuning). Written only through core''s connector/nudges.ts.';


--
-- Name: offers; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.offers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    application_id uuid NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    salary bigint,
    currency text DEFAULT 'USD'::text NOT NULL,
    bonus text,
    equity text,
    start_date date,
    expires_on date,
    notes text,
    created_by_actor_id uuid,
    extended_at timestamp with time zone,
    resolved_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT offers_bonus_check CHECK (((bonus IS NULL) OR (length(bonus) <= 500))),
    CONSTRAINT offers_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT offers_equity_check CHECK (((equity IS NULL) OR (length(equity) <= 500))),
    CONSTRAINT offers_notes_check CHECK (((notes IS NULL) OR (length(notes) <= 5000))),
    CONSTRAINT offers_salary_check CHECK (((salary IS NULL) OR ((salary >= 0) AND (salary <= 100000000)))),
    CONSTRAINT offers_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'extended'::text, 'accepted'::text, 'declined'::text, 'withdrawn'::text])))
);


--
-- Name: TABLE offers; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.offers IS 'An offer on one application. draft -> extended -> accepted | declined; draft or extended -> withdrawn. Closed offers never change.';


--
-- Name: offices; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.offices (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    name text NOT NULL,
    location text,
    created_by_actor_id uuid,
    archived_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT offices_location_check CHECK (((location IS NULL) OR ((location = btrim(location)) AND ((length(location) >= 1) AND (length(location) <= 200))))),
    CONSTRAINT offices_name_check CHECK (((name = btrim(name)) AND ((length(name) >= 1) AND (length(name) <= 100))))
);


--
-- Name: TABLE offices; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.offices IS 'Per org: the offices jobs are in (job_offices). Unique by lower(name) per org; archived, never deleted.';


--
-- Name: openings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.openings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    role_id uuid NOT NULL,
    number integer DEFAULT 0 NOT NULL,
    opening_code text,
    status text DEFAULT 'open'::text NOT NULL,
    target_start_date date,
    close_reason text,
    filled_by_application_id uuid,
    filled_at timestamp with time zone,
    closed_at timestamp with time zone,
    created_by_actor_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT openings_close_reason_check CHECK (((close_reason IS NULL) OR ((close_reason = btrim(close_reason)) AND ((length(close_reason) >= 1) AND (length(close_reason) <= 200))))),
    CONSTRAINT openings_opening_code_check CHECK (((opening_code IS NULL) OR ((opening_code = btrim(opening_code)) AND ((length(opening_code) >= 1) AND (length(opening_code) <= 50))))),
    CONSTRAINT openings_status_check CHECK ((status = ANY (ARRAY['open'::text, 'filled'::text, 'closed'::text])))
);


--
-- Name: TABLE openings; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.openings IS 'A job''s headcount, one row per seat: open -> filled (by a hired application) | closed (with a reason), and back to open.';


--
-- Name: org_members; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.org_members WITH (security_invoker='true') AS
 SELECT id,
    org_id,
    display_name,
    email,
    access_level
   FROM public.actors
  WHERE (archived_at IS NULL);


--
-- Name: orgs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.orgs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    slug text NOT NULL,
    kind text DEFAULT 'client'::text NOT NULL,
    workos_org_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    company_id uuid,
    feedback_visibility text DEFAULT 'after_submit'::text NOT NULL,
    connector_access text DEFAULT 'read_write'::text NOT NULL,
    connector_access_set_by_actor_id uuid,
    connector_access_set_at timestamp with time zone,
    brand_domain text,
    brand_accent text,
    brand_logo_url text,
    CONSTRAINT orgs_brand_accent_check CHECK ((brand_accent ~ '^#[0-9a-f]{6}$'::text)),
    CONSTRAINT orgs_connector_access_check CHECK ((connector_access = ANY (ARRAY['read_write'::text, 'read_only'::text]))),
    CONSTRAINT orgs_feedback_visibility_check CHECK ((feedback_visibility = ANY (ARRAY['always'::text, 'after_submit'::text, 'never'::text]))),
    CONSTRAINT orgs_kind_check CHECK ((kind = ANY (ARRAY['agency'::text, 'client'::text])))
);


--
-- Name: TABLE orgs; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.orgs IS 'A tenant. Every ATS row belongs to exactly one org; Tacit is the agency org. Rows in one org never reference rows in another (same-org composite FKs).';


--
-- Name: COLUMN orgs.workos_org_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.orgs.workos_org_id IS 'The WorkOS organization this org signs in through. When set, current_org_id() also requires the token''s org_id claim to match it.';


--
-- Name: COLUMN orgs.company_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.orgs.company_id IS 'The row in Tacit''s companies for this client: the company Tacit recruits for. Every client org has one (createClientOrg requires it; 20261017160000 backfilled the rest), and a company has at most one org.';


--
-- Name: COLUMN orgs.feedback_visibility; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.orgs.feedback_visibility IS 'When someone with can_view_feedback reads other interviewers'' feedback on an application: always; after_submit (once they have filed their own for every interview of it they are on); never (admins only).';


--
-- Name: COLUMN orgs.connector_access; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.orgs.connector_access IS 'read_write | read_only: whether tacit-ats''s client connector (/api/client) may write. Enforced by client_claim_write; set through set_connector_access.';


--
-- Name: outreach_messages; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.outreach_messages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    person_id uuid,
    actor_id uuid,
    sent_by_actor_id uuid,
    to_email text NOT NULL,
