    to_name text,
    vertical text,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    CONSTRAINT outreach_messages_status_check CHECK ((status = ANY (ARRAY['sent'::text, 'failed'::text])))
);


--
-- Name: COLUMN outreach_messages.person_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.outreach_messages.person_id IS 'The CRM person this went to, when the recipient happened to be one. NULL for cold outreach to a raw email address (the common case) -- to_email is always the real target.';


--
-- Name: COLUMN outreach_messages.to_name; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.outreach_messages.to_name IS 'Recipient display name typed at compose time (used for {{name}}/{{first_name}} and shown in the outbox). Optional.';


--
-- Name: COLUMN outreach_messages.vertical; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.outreach_messages.vertical IS 'The vertical the sender picked at compose time, which drove the routing. Recorded for the outbox''s "why this inbox" trail.';


--
-- Name: people_merges; Type: TABLE; Schema: public; Owner: -
