--
-- Name: rejection_reasons; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.rejection_reasons (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    kind text NOT NULL,
    name text NOT NULL,
    "position" integer DEFAULT 100 NOT NULL,
    archived_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT rejection_reasons_kind_check CHECK ((kind = ANY (ARRAY['rejected'::text, 'withdrew'::text]))),
    CONSTRAINT rejection_reasons_name_check CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 120)))
);


--
-- Name: TABLE rejection_reasons; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.rejection_reasons IS 'Per org: why an application can close. kind rejected = the company passed, withdrew = the candidate did.';


--
-- Name: roles; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.roles (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    title text NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    location text,
    seniority text,
    description text,
    must_haves text[],
    nice_to_haves text[],
    looking_for text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    pay_min integer,
    pay_max integer,
    equity_note text,
    interview_steps jsonb DEFAULT '[]'::jsonb NOT NULL,
    owner_actor_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    confidential boolean DEFAULT false NOT NULL,
    department_id uuid,
    CONSTRAINT roles_interview_steps_is_list CHECK ((jsonb_typeof(interview_steps) = 'array'::text)),
    CONSTRAINT roles_pay_min_below_max CHECK ((pay_min <= pay_max)),
    CONSTRAINT roles_pay_not_negative CHECK (((pay_min >= 0) AND (pay_max >= 0))),
    CONSTRAINT roles_status_check CHECK ((status = ANY (ARRAY['pending_approval'::text, 'open'::text, 'paused'::text, 'filled'::text, 'closed'::text])))
);


--
-- Name: COLUMN roles.pay_min; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.roles.pay_min IS 'Bottom of the base pay range, whole US dollars a year.';


--
-- Name: COLUMN roles.pay_max; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.roles.pay_max IS 'Top of the base pay range, whole US dollars a year.';


--
-- Name: COLUMN roles.interview_steps; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.roles.interview_steps IS 'The interview process in order, as a JSON array of step names: ["Recruiter screen", "Take-home", "Onsite"].';


--
-- Name: COLUMN roles.owner_actor_ids; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.roles.owner_actor_ids IS 'The Tacit teammates working this role. actors rows; no FK on an array, so a deleted actor is dropped at read time.';


--
-- Name: COLUMN roles.confidential; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.roles.confidential IS 'Visible only to actors with job_access on it, and admins with can_view_all_confidential.';


--
-- Name: rubrics; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.rubrics (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    title text NOT NULL,
    content text NOT NULL,
    stage_default text,
    company text,
    role text,
    storage_path text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    CONSTRAINT rubrics_stage_default_check CHECK ((stage_default = ANY (ARRAY['interview_1'::text, 'interview_2'::text])))
);


--
-- Name: scheduling_cursors; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.scheduling_cursors (
    actor_id uuid NOT NULL,
    person_id uuid NOT NULL,
    last_inbound_sent_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    negotiating_since timestamp with time zone,
    last_event_start timestamp with time zone,
    last_event_id text
);


--
-- Name: TABLE scheduling_cursors; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.scheduling_cursors IS 'Per-(actor, person) high-watermark for the ambient scheduling agent: the sent_at of the newest inbound message already considered. The driver processes only messages newer than this. Durable and multi-Mac coherent.';


--
-- Name: COLUMN scheduling_cursors.negotiating_since; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.scheduling_cursors.negotiating_since IS 'Set when a scheduling draft was pushed for this thread; gates the locked-time detector so it only runs while a negotiation is active. Null = not negotiating. Cleared when an event is created.';


--
-- Name: COLUMN scheduling_cursors.last_event_start; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.scheduling_cursors.last_event_start IS 'Start (UTC) of the most recent calendar event the agent created for this thread. A newly-detected locked time equal to this is a no-op (dedup); a different one books a fresh event (reschedule).';


--
-- Name: COLUMN scheduling_cursors.last_event_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.scheduling_cursors.last_event_id IS 'Google Calendar event id of the most recent event the agent created for this thread. Audit + a handle for a future update/cancel path.';


--
-- Name: scorecard_attributes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.scorecard_attributes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL,
    role_id uuid NOT NULL,
    name text NOT NULL,
    description text,
    "position" integer DEFAULT 100 NOT NULL,
    archived_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT scorecard_attributes_description_check CHECK (((description IS NULL) OR (length(description) <= 1000))),
    CONSTRAINT scorecard_attributes_name_check CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 120)))
);


--
-- Name: TABLE scorecard_attributes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.scorecard_attributes IS 'Per job: what an interviewer rates a candidate on. Archived, never deleted, so old ratings keep their attribute.';


