);


--
-- Name: TABLE tacit_submissions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.tacit_submissions IS 'A Tacit teammate''s submission of a Tacit person into a client org''s job (tacit_submit_to_client). Tacit''s side only.';


--
