);


--
-- Name: TABLE talent_pools; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.talent_pools IS 'Per org: named lists of people (prospects or candidates) the team keeps warm. Unique by lower(name) per org; archived, never deleted.';


--
