    expires_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT testbench_links_active_has_token CHECK (((status <> 'active'::text) OR ((token IS NOT NULL) AND (client_id IS NOT NULL) AND (expires_at IS NOT NULL)))),
    CONSTRAINT testbench_links_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'active'::text])))
);


--
-- Name: TABLE testbench_links; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.testbench_links IS 'One teammate''s read-only connection to one Tacit Testbench company, made by device approval. Holds the reporting token; assessment data itself is never copied here.';


