    org_id uuid DEFAULT public.org_id_set_by_trigger() NOT NULL
);


--
-- Name: COLUMN transcript_entries.speaker_label; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.transcript_entries.speaker_label IS 'Granola diarization_label ("Speaker A", "Speaker B", ...) when the source distinguishes speakers without an attribution guess. Null for imessage and for granola segments where attribution ("me"/"them") is the only speaker signal available.';


--
-- Name: COLUMN transcript_entries.ingested_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.transcript_entries.ingested_by IS 'Actor whose device/account captured this entry. Attribution metadata, deliberately not part of the dedup key; client-asserted by the ingesting process. iMessage source_refs are namespaced <actor_id>:<rowid> instead.';


