CREATE POLICY client_write ON public.hiring_team_role_access TO authenticated USING (((org_id = ( SELECT public.current_org_id() AS current_org_id)) AND (( SELECT public.current_access_level() AS current_access_level) = 'admin'::text))) WITH CHECK (((org_id = ( SELECT public.current_org_id() AS current_org_id)) AND (( SELECT public.current_access_level() AS current_access_level) = 'admin'::text)));


--
-- Name: interview_feedback_ratings client_write; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY client_write ON public.interview_feedback_ratings TO authenticated USING (((org_id = ( SELECT public.current_org_id() AS current_org_id)) AND (EXISTS ( SELECT 1
   FROM public.interview_feedback f
  WHERE ((f.id = interview_feedback_ratings.feedback_id) AND (f.interviewer_actor_id = ( SELECT public.current_actor_id() AS current_actor_id))))))) WITH CHECK (((org_id = ( SELECT public.current_org_id() AS current_org_id)) AND (EXISTS ( SELECT 1
   FROM public.interview_feedback f
  WHERE ((f.id = interview_feedback_ratings.feedback_id) AND (f.interviewer_actor_id = ( SELECT public.current_actor_id() AS current_actor_id)))))));


--
-- Name: interviews client_write; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY client_write ON public.interviews TO authenticated USING (((org_id = ( SELECT public.current_org_id() AS current_org_id)) AND public.can_on_role(public.application_role(application_id), 'can_schedule'::text))) WITH CHECK (((org_id = ( SELECT public.current_org_id() AS current_org_id)) AND public.can_on_role(public.application_role(application_id), 'can_schedule'::text)));


--
-- Name: job_access client_write; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY client_write ON public.job_access TO authenticated USING (((org_id = ( SELECT public.current_org_id() AS current_org_id)) AND (( SELECT public.current_access_level() AS current_access_level) = 'admin'::text) AND public.can_on_role(role_id, 'can_manage_job'::text))) WITH CHECK (((org_id = ( SELECT public.current_org_id() AS current_org_id)) AND (( SELECT public.current_access_level() AS current_access_level) = 'admin'::text) AND public.can_on_role(role_id, 'can_manage_job'::text)));


